INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Fantassin britannique', 'Soldat d''infanterie britannique', 'Soldats coriaces et professionnels, d''une réserve toute britannique même au cœur de la bataille. Malgré les défaites du début de la guerre, ils ne sont jamais mis en déroute et se replient toujours en bon ordre. Armés du fusil Lee-Enfield, avec une mitrailleuse Bren par section et un antichar Boys puis PIAT (après 1943). (VO : British Infantryman)', '["Troupe","Alliés"]', 'Gamemaster Guide', 161, '{"rank":"trooper","truths":["Tommy britannique inébranlable"],"attributes":{"agility":8,"brawn":8,"coordination":9,"insight":7,"reason":7,"will":9},"skills":[{"key":"athletics","rank":2,"focuses":[]},{"key":"fighting","rank":2,"focuses":["Fusils"]},{"key":"medicine","rank":1,"focuses":[]},{"key":"resilience","rank":3,"focuses":[]},{"key":"stealth","rank":1,"focuses":["Camouflage"]},{"key":"survival","rank":1,"focuses":[]}],"stress":6,"injuries":1,"armour":1,"courage":2,"attacks":[{"name":"Lee-Enfield Rifle","focus":"Fusils","range":"long","damage":6,"salvo":"Vicieux","qualities":"Fiable","escalation":false},{"name":"Baïonnette","focus":"Armes de mêlée","range":"contact","damage":3,"salvo":null,"qualities":"Perforant 1","escalation":false},{"name":"Bren Machine Gun","focus":"Fusils","range":"medium","damage":5,"salvo":"Zone","qualities":"Lourd, Imprécis","escalation":true},{"name":"Mills Bomb (No.36M)","focus":"Lancer","range":"close","damage":6,"salvo":null,"qualities":"Zone, Étourdissant, Imprécis, Munition","escalation":true},{"name":"PIAT Anti-Tank Weapon","focus":"Armes lourdes","range":"medium","damage":6,"salvo":null,"qualities":"Perforant 1, Vicieux, Encombrant, Escalade, Tueur de géants, Lourd, Imprécis, Munition","escalation":true}],"abilities":[],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Fantassin britannique' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Officier de l''armée britannique', 'Officier d''infanterie britannique', 'Bien formés, professionnels et très disciplinés, les officiers sont la colonne vertébrale de l''armée britannique. Malgré leur goût de la prudence et de la consolidation plutôt que du risque, leur courage, leur engagement et leur sens tactique ne font aucun doute, même dans les situations les plus éprouvantes. (VO : British Army Officer)', '["Troupe","Alliés"]', 'Gamemaster Guide', 161, '{"rank":"trooper","truths":["Chef sur le champ de bataille"],"attributes":{"agility":8,"brawn":7,"coordination":8,"insight":8,"reason":9,"will":8},"skills":[{"key":"academia","rank":1,"focuses":[]},{"key":"athletics","rank":1,"focuses":[]},{"key":"fighting","rank":2,"focuses":["Armes de poing"]},{"key":"medicine","rank":1,"focuses":[]},{"key":"resilience","rank":2,"focuses":[]},{"key":"stealth","rank":1,"focuses":[]},{"key":"survival","rank":1,"focuses":[]},{"key":"tactics","rank":1,"focuses":["Commandement"]}],"stress":5,"injuries":1,"armour":1,"courage":1,"attacks":[{"name":"Enfield No.2 .38/200 Service Revolver","focus":"Armes de poing","range":"close","damage":4,"salvo":"Vicieux","qualities":"Combat rapproché, Fiable","escalation":false},{"name":"Mills Bomb (No.36M)","focus":"Lancer","range":"close","damage":6,"salvo":null,"qualities":"Zone, Étourdissant, Imprécis, Munition","escalation":true}],"abilities":[{"name":"Rallier les troupes","text":"L''officier affronte les pires situations avec flegme et un calme imperturbable ; c''est un excellent meneur d''hommes. En dépensant 1 Élan par une action mineure, il accorde +1 Moral à tous les troupiers alliés à portée Courte."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Officier de l''armée britannique' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Régiments de la Garde', 'Infanterie d''élite britannique', 'Les cinq régiments de la Foot Guards (Grenadier, Coldstream, Scots, Irish et Welsh Guards) comptent parmi les plus anciens et prestigieux de Grande-Bretagne. Troupes les plus aguerries de l''armée, souvent placées en fer de lance des assauts grâce à leur redoutable réputation, elles sont une force avec laquelle il faut compter. (VO : Guards Regiments)', '["Lieutenant","Alliés"]', 'Gamemaster Guide', 162, '{"rank":"lieutenant","truths":["Infanterie d''élite britannique"],"attributes":{"agility":8,"brawn":9,"coordination":9,"insight":9,"reason":7,"will":9},"skills":[{"key":"athletics","rank":2,"focuses":[]},{"key":"fighting","rank":3,"focuses":["Corps à corps","Fusils","Vigilance"]},{"key":"medicine","rank":1,"focuses":[]},{"key":"observation","rank":2,"focuses":[]},{"key":"resilience","rank":3,"focuses":[]},{"key":"stealth","rank":2,"focuses":["Camouflage"]},{"key":"survival","rank":2,"focuses":[]},{"key":"tactics","rank":1,"focuses":[]},{"key":"vehicles","rank":1,"focuses":[]}],"stress":12,"injuries":2,"armour":2,"courage":4,"attacks":[{"name":"Thompson Submachine Gun","focus":"Corps à corps","range":"close","damage":5,"salvo":"Étourdissant","qualities":"Imprécis","escalation":false},{"name":"Mills Bomb (No.36M)","focus":"Lancer","range":"close","damage":7,"salvo":null,"qualities":"Zone, Étourdissant, Imprécis, Munition","escalation":false},{"name":"Bren Machine Gun","focus":"Fusils","range":"medium","damage":6,"salvo":"Zone","qualities":"Lourd, Imprécis","escalation":true},{"name":"PIAT Anti-Tank Weapon","focus":"Armes lourdes","range":"medium","damage":7,"salvo":null,"qualities":"Perforant 1, Vicieux, Encombrant, Escalade, Tueur de géants, Lourd, Imprécis, Munition","escalation":true}],"abilities":[{"name":"Fer de lance","text":"Les régiments de la Garde ont l''habitude d''être jetés sous le feu. Les gardes peuvent conserver l''initiative pour 1 Élan au lieu de 2."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Régiments de la Garde' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Commandos et SAS', 'Forces spéciales britanniques d''élite', 'Les Commandos (brigades du Special Service) sont les forces spéciales alliées les plus influentes de la guerre, d''abord petites forces de raid très mobiles, puis fer de lance des assauts alliés de la Tunisie au Débarquement. Très entraînés et maîtres de la guerre non conventionnelle, ils savent tuer une sentinelle en silence, se battre à mains nues, escalader, naviguer en terrain difficile et faire sauter des cibles. (VO : The Commandos and SAS)', '["Lieutenant","Alliés"]', 'Gamemaster Guide', 162, '{"rank":"lieutenant","truths":["Forces spéciales britanniques d''élite"],"attributes":{"agility":9,"brawn":9,"coordination":9,"insight":8,"reason":7,"will":9},"skills":[{"key":"athletics","rank":3,"focuses":[]},{"key":"fighting","rank":3,"focuses":["Main nue","Corps à corps","Vigilance"]},{"key":"medicine","rank":1,"focuses":[]},{"key":"observation","rank":2,"focuses":[]},{"key":"resilience","rank":3,"focuses":[]},{"key":"stealth","rank":3,"focuses":["Camouflage"]},{"key":"survival","rank":2,"focuses":[]}],"stress":12,"injuries":2,"armour":2,"courage":4,"attacks":[{"name":"Sten Mk IIS Suppressed SMG","focus":"Corps à corps","range":"close","damage":3,"salvo":"Étourdissant","qualities":"Imprécis, Subtil","escalation":false},{"name":"Couteau de combat Fairbairn-Sykes","focus":"Armes de mêlée","range":"contact","damage":3,"salvo":null,"qualities":"Perforant 1, Caché, Subtil","escalation":false},{"name":"Bren Machine Gun","focus":"Fusils","range":"medium","damage":5,"salvo":"Zone","qualities":"Lourd, Imprécis","escalation":true},{"name":"Mills Bomb (No.36M)","focus":"Lancer","range":"close","damage":6,"salvo":null,"qualities":"Zone, Étourdissant, Imprécis, Lancer","escalation":true},{"name":"1½lbs/3lbs Standard Charge","focus":"Explosifs","range":"close","damage":10,"salvo":"Intense","qualities":"Zone, Étourdissant","escalation":true}],"abilities":[{"name":"Commandos","text":"Les commandos sont des maîtres du meurtre silencieux et du sabotage. Lorsqu''il attaque en étant caché, le commando est toujours considéré comme ayant un focus approprié."},{"name":"Sabotage","text":"Experts du sabotage, les commandos peuvent utiliser leur compétence Combat à la place d''Ingénierie lorsqu''ils tentent un sabotage."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Commandos et SAS' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Commandos de Badger', 'Commandos anti-Mythe d''élite (Section M)', 'Ces commandos alliés audacieux opèrent loin derrière les lignes ennemies dans toutes sortes d''opérations clandestines, rompus aussi bien aux forces de l''Axe qu''aux horreurs de la Guerre secrète. Troupes d''élite prêtes à agir sur terre, sur mer et dans les airs, ils emploient les armes à vapeur Blevin contre le Mythe et tiennent leur nom de leur chef, Eric « Badger » Harris. (VO : Badger''s Commandos)', '["Lieutenant","Alliés"]', 'Gamemaster Guide', 163, '{"rank":"lieutenant","truths":["Commandos anti-Mythe d''élite"],"attributes":{"agility":9,"brawn":8,"coordination":9,"insight":8,"reason":7,"will":10},"skills":[{"key":"athletics","rank":3,"focuses":[]},{"key":"fighting","rank":3,"focuses":["Main nue","Corps à corps","Vigilance"]},{"key":"observation","rank":2,"focuses":[]},{"key":"resilience","rank":3,"focuses":["Discipline"]},{"key":"stealth","rank":3,"focuses":[]},{"key":"survival","rank":2,"focuses":[]},{"key":"tactics","rank":1,"focuses":[]}],"stress":13,"injuries":2,"armour":1,"courage":5,"attacks":[{"name":"Fusil à vapeur Blevin","focus":"Fusils","range":"medium","damage":4,"salvo":"Intense ou Persistant 2","qualities":"Fléau","escalation":false},{"name":"Couteau de combat Fairbairn-Sykes","focus":"Armes de mêlée","range":"contact","damage":3,"salvo":null,"qualities":"Perforant 1, Caché, Subtil","escalation":false},{"name":"Mills Bomb (No.36M)","focus":"Lancer","range":"close","damage":6,"salvo":null,"qualities":"Zone, Étourdissant, Imprécis, Lancer","escalation":false},{"name":"Bren Machine Gun","focus":"Fusils","range":"medium","damage":5,"salvo":"Zone","qualities":"Lourd, Imprécis","escalation":true},{"name":"1½lbs/3lbs Standard Charge","focus":"Explosifs","range":"close","damage":10,"salvo":"Intense","qualities":"Zone, Étourdissant","escalation":true}],"abilities":[{"name":"Commandos","text":"Les commandos sont des maîtres du meurtre silencieux et du sabotage. Lorsqu''il attaque en étant caché, le commando est toujours considéré comme ayant un focus approprié."},{"name":"Savoir du Mythe","text":"Les commandos de Badger ont affronté le Mythe à maintes reprises et ont survécu pour le raconter. Ils peuvent relancer 1d20 lors d''un test pour résister à une attaque mentale."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Commandos de Badger' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'La Garde grise', 'Guerriers des Highlands anti-Mythe (Section M)', 'Troupe d''élite de guerriers écossais triés parmi les régiments des Highlands pour leur bravoure face à la terreur du Mythe, presque immunisés à ses effets sur l''esprit. Redoutables au corps à corps, vêtus d''un tartan gris et vert, ils sont toujours accompagnés d''un joueur des Cornemuses de McMurden, instrument enchanté qui effraie les entités du Mythe et les rend vulnérables aux armes conventionnelles. (VO : The Grey Watch)', '["Lieutenant","Alliés"]', 'Gamemaster Guide', 163, '{"rank":"lieutenant","truths":["Guerriers intrépides des Highlands"],"attributes":{"agility":9,"brawn":9,"coordination":9,"insight":7,"reason":7,"will":10},"skills":[{"key":"athletics","rank":3,"focuses":[]},{"key":"fighting","rank":4,"focuses":["Main nue","Armes de mêlée","Corps à corps"]},{"key":"observation","rank":2,"focuses":[]},{"key":"persuasion","rank":2,"focuses":["Intimidation"]},{"key":"resilience","rank":4,"focuses":[]},{"key":"stealth","rank":1,"focuses":[]},{"key":"survival","rank":1,"focuses":[]},{"key":"tactics","rank":1,"focuses":["Tactique de terrain"]},{"key":"vehicles","rank":1,"focuses":[]}],"stress":13,"injuries":2,"armour":4,"courage":6,"attacks":[{"name":"Winchester M12 Shotgun","focus":"Corps à corps","range":"close","damage":6,"salvo":"Vicieux","qualities":"Fiable, Imprécis","escalation":false},{"name":"Claymore à garde en panier","focus":"Exotique","range":"contact","damage":5,"salvo":null,"qualities":"Fléau, Parade","escalation":false},{"name":"Bouclier","focus":"Armes de mêlée","range":"contact","damage":4,"salvo":null,"qualities":"Étourdissant, Fléau, +2 Armure (incluse)","escalation":false},{"name":"Tromblon Turpin''s Bane","focus":"Fusils","range":"close","damage":5,"salvo":"Intense","qualities":"Zone, Fléau, Fiable","escalation":true},{"name":"Arme à énergie dirigée Green Knight","focus":"Exotique","range":"close","damage":6,"salvo":"Vidange ou Intense","qualities":"Zone, Fléau","escalation":true}],"abilities":[{"name":"Jamais un pas en arrière","text":"La Garde grise marche toujours au combat aux accents des Cornemuses de McMurden. Tant que les cornemuses se font entendre, chaque membre de la Garde grise gagne +3 Moral."},{"name":"Pas une bestiole craintive","text":"La Garde grise se montre particulièrement inflexible face aux créatures du Mythe. Toutes ses attaques Armes de mêlée et Main nue gagnent la qualité Fléau et infligent +1 dégât (inclus ci-dessus)."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'La Garde grise' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Les Lames sacrées : les Gurkhas de Gopal', 'Montagnards chasseurs du Mythe (Section M)', 'Issus du peuple kirat de l''ouest du Népal, ces guerriers suivent les enseignements du Mundhum et possèdent une puissante tradition chamanique. Menés par le subedar Govinda Gopal, ils manient un redoutable khukri sacré et ont gagné leur réputation pendant la bataille de France en anéantissant un nid d''horreurs invoquées par le Soleil Noir, ce qui leur valut d''être détachés auprès des forces spéciales de la Section M. (VO : The Sacred Blades: Gopal''s Ghurkhas)', '["Lieutenant","Alliés"]', 'Gamemaster Guide', 164, '{"rank":"lieutenant","truths":["Redoutables montagnards chasseurs du Mythe"],"attributes":{"agility":10,"brawn":9,"coordination":8,"insight":8,"reason":8,"will":8},"skills":[{"key":"athletics","rank":3,"focuses":[]},{"key":"fighting","rank":3,"focuses":["Main nue","Armes de mêlée"]},{"key":"medicine","rank":1,"focuses":[]},{"key":"observation","rank":2,"focuses":[]},{"key":"resilience","rank":2,"focuses":[]},{"key":"stealth","rank":3,"focuses":["Camouflage","Discrétion rurale"]},{"key":"survival","rank":2,"focuses":[]},{"key":"tactics","rank":1,"focuses":["Tactique de terrain"]}],"stress":11,"injuries":2,"armour":3,"courage":2,"attacks":[{"name":"Sten Mk.V Submachine Gun","focus":"Corps à corps","range":"close","damage":4,"salvo":"Étourdissant","qualities":"Imprécis","escalation":false},{"name":"Khukri sacré","focus":"Armes de mêlée","range":"contact","damage":5,"salvo":null,"qualities":"Vicieux, Fléau","escalation":false},{"name":"Mills Bomb (No.36M)","focus":"Lancer","range":"close","damage":6,"salvo":null,"qualities":"Zone, Étourdissant, Imprécis, Munition","escalation":false},{"name":"Grenade Ibn Ghazi","focus":"Lancer","range":"close","damage":6,"salvo":null,"qualities":"Zone, Imprécis, Munition, révèle les ennemis cachés","escalation":true},{"name":"Pistolet Blevin","focus":"Armes de poing","range":"close","damage":3,"salvo":"Intense ou Persistant 3","qualities":"Fléau","escalation":true}],"abilities":[{"name":"Durs à cuire","text":"Les Gurkhas comptent parmi les soldats les plus coriaces de la planète et gagnent +1 Armure (incluse)."},{"name":"À l''affût","text":"Lorsque les Gurkhas sont appelés en renfort, ils peuvent payer 1 Menace supplémentaire pour avoir tendu une embuscade : ils surgissent alors de leur cachette n''importe où à portée Courte de l''ennemi."}],"threatSpends":[{"name":"À l''affût","cost":"1","text":"En plus du coût du renfort : les Gurkhas surgissent d''une embuscade n''importe où à portée Courte de l''ennemi."}]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Les Lames sacrées : les Gurkhas de Gopal' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Les Bérets de bronze', 'Tireurs d''élite anti-horreurs (Section M)', 'Pour frapper les créatures du Mythe de loin, la division de l''intendance de la Section M du Dr Parker a conçu un fusil de précision à rail portatif, le Beowulf Mk 1, tirant des munitions gravées du Signe des Anciens. Des tireurs d''élite recrutés dans les unités d''élite le servent et reçoivent un béret de bronze ; ils marquent chaque victime du Mythe sur leur arme et gagnent des écussons « Grendel » (10), « Mère de Grendel » (30) et « Dragon » (50). (VO : The Bronze Berets)', '["Lieutenant","Alliés"]', 'Gamemaster Guide', 164, '{"rank":"lieutenant","truths":["Tireurs d''élite anti-horreurs"],"attributes":{"agility":9,"brawn":8,"coordination":10,"insight":9,"reason":7,"will":8},"skills":[{"key":"academia","rank":1,"focuses":["Occultisme"]},{"key":"athletics","rank":2,"focuses":[]},{"key":"fighting","rank":3,"focuses":["Fusils"]},{"key":"observation","rank":3,"focuses":["Vue"]},{"key":"resilience","rank":2,"focuses":[]},{"key":"stealth","rank":3,"focuses":["Camouflage"]},{"key":"survival","rank":2,"focuses":[]},{"key":"tactics","rank":1,"focuses":[]}],"stress":10,"injuries":2,"armour":1,"courage":2,"attacks":[{"name":"Fusil de précision Beowulf Mk 1","focus":"Fusils","range":"extreme","damage":8,"salvo":"Vicieux","qualities":"Perforant 1, Précis, Fléau","escalation":false},{"name":"Mills Bomb (No.36M)","focus":"Lancer","range":"close","damage":7,"salvo":null,"qualities":"Zone, Étourdissant, Imprécis, Munition","escalation":false},{"name":"Pistolet à vapeur Blevin","focus":"Armes de poing","range":"close","damage":3,"salvo":null,"qualities":"Fléau","escalation":false},{"name":"Grenade Ibn Ghazi","focus":"Lancer","range":"close","damage":3,"salvo":null,"qualities":"Zone, Imprécis, Munition, révèle les ennemis cachés","escalation":false}],"abilities":[{"name":"Flegme à toute épreuve","text":"Les Bérets de bronze sont imperturbables et répondent généralement à l''ennemi par une balle de Beowulf. Si un Béret de bronze subit du stress mental d''une créature ou d''un objet du Mythe, il peut payer 1 Menace pour attaquer immédiatement la source de sa terreur en Réaction ; cette attaque voit sa difficulté augmenter de +2."},{"name":"À un mille de distance","text":"Les Bérets de bronze, si on les voit jamais, ne sont qu''un point à l''horizon. Appelés en renfort, ils apparaissent à portée Extrême, en général dans un arbre ou sur une hauteur. Lors de leur première attaque de la scène au fusil Beowulf, ils gagnent +3d20 ; l''attaque est si surprenante que tous les ennemis mortels de la zone de la cible doivent réussir un test de Résilience de difficulté 1 ou subir 3 de stress mental avec l''effet Étourdissant."}],"threatSpends":[{"name":"Flegme à toute épreuve","cost":"1","text":"Après avoir subi du stress mental d''une source du Mythe : attaque immédiate de cette source en Réaction, difficulté +2."}]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Les Bérets de bronze' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Capitaine Eric « Badger » Harris', 'Chef des commandos de Badger (Section M)', 'Le capitaine Harris et ses hommes sont le bras armé de la Section M, département secret du renseignement britannique ; son unité reçoit toutes sortes de prototypes pour combattre les nazis et le Mythe. Meneur d''hommes exemplaire, toujours en première ligne et calme face aux horreurs, il allie une carrure imposante, un sens tactique hors pair et une compréhension instinctive des armes expérimentales. (VO : Captain Eric "Badger" Harris)', '["Némésis","Alliés"]', 'Gamemaster Guide', 165, '{"rank":"nemesis","truths":["Chef héroïque des commandos de Badger"],"attributes":{"agility":9,"brawn":10,"coordination":9,"insight":9,"reason":8,"will":9},"skills":[{"key":"academia","rank":1,"focuses":[]},{"key":"athletics","rank":3,"focuses":[]},{"key":"engineering","rank":1,"focuses":[]},{"key":"fighting","rank":3,"focuses":["Main nue","Corps à corps","Fusils"]},{"key":"medicine","rank":1,"focuses":[]},{"key":"observation","rank":2,"focuses":[]},{"key":"resilience","rank":3,"focuses":["Discipline"]},{"key":"stealth","rank":3,"focuses":[]},{"key":"survival","rank":2,"focuses":[]},{"key":"tactics","rank":1,"focuses":[]},{"key":"vehicles","rank":1,"focuses":[]}],"stress":13,"injuries":3,"armour":3,"courage":4,"attacks":[{"name":"Fusil à vapeur Blevin","focus":"Fusils","range":"medium","damage":5,"salvo":"Intense ou Persistant 3","qualities":"Fléau","escalation":false},{"name":"Sten Mk.V Submachine Gun","focus":"Corps à corps","range":"close","damage":5,"salvo":"Étourdissant","qualities":"Imprécis","escalation":false},{"name":"Couteau de combat Fairbairn-Sykes","focus":"Armes de mêlée","range":"contact","damage":4,"salvo":null,"qualities":"Perforant 1, Caché, Subtil","escalation":false},{"name":"Mills Bomb (No.36M)","focus":"Lancer","range":"close","damage":7,"salvo":null,"qualities":"Zone, Étourdissant, Imprécis, Munition","escalation":false}],"abilities":[{"name":"Guérillero par excellence","text":"Lorsqu''il mène des troupes alliées, commandos ou simple infanterie, Badger peut utiliser les règles spéciales de l''escouade qu''il dirige, en plus de celles de ses propres hommes."},{"name":"Ennemi juré du Soleil Noir","text":"Badger a affronté le Soleil Noir encore et encore et compte parmi ses ennemis les plus implacables. Face à leurs monstres invoqués, lui et ses hommes gagnent +2 Moral."},{"name":"Féru de technique","text":"Badger connaît bien les nouvelles technologies et ne se laisse pas impressionner par les objets occultes ou le matériel expérimental. Lorsqu''il tente d''utiliser une telle technologie, il peut relancer 1d20."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Capitaine Eric « Badger » Harris' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Caporal Akhee « l''Œil » Singh', 'Guerrier mystique hanté (Section M)', 'Presque aussi craint des Alliés que de l''Axe, Singh a découvert dans un temple abandonné la statue d''un dieu oublié et en a reçu une amulette à l''œil qui, une fois libérée, le change en tourbillon de lames répandant une brume noire mortelle. Il commence à peine à maîtriser ce pouvoir et redoute que l''Œil ne s''éveille tout à fait ; sombre et renfermé, il a pourtant servi la Section M avec bravoure, souvent aux côtés des commandos de Badger Harris. (VO : Corporal Akhee "The Eye" Singh)', '["Némésis","Alliés"]', 'Gamemaster Guide', 166, '{"rank":"nemesis","truths":["Guerrier mystique hanté"],"attributes":{"agility":10,"brawn":10,"coordination":10,"insight":7,"reason":8,"will":9},"skills":[{"key":"academia","rank":2,"focuses":["Occultisme"]},{"key":"athletics","rank":2,"focuses":[]},{"key":"engineering","rank":1,"focuses":[]},{"key":"fighting","rank":4,"focuses":["Armes de mêlée","Fusils"]},{"key":"observation","rank":2,"focuses":["Instinct"]},{"key":"persuasion","rank":1,"focuses":[]},{"key":"resilience","rank":2,"focuses":[]},{"key":"stealth","rank":2,"focuses":[]},{"key":"survival","rank":2,"focuses":[]},{"key":"tactics","rank":1,"focuses":[]},{"key":"vehicles","rank":1,"focuses":[]}],"stress":12,"injuries":3,"armour":2,"courage":3,"attacks":[{"name":"Fusil à vapeur Blevin","focus":"Fusils","range":"medium","damage":4,"salvo":"Intense ou Persistant 3","qualities":"Fléau","escalation":false},{"name":"Kirpan","focus":"Armes de mêlée","range":"contact","damage":5,"salvo":null,"qualities":"Perforant 2, Caché, Subtil","escalation":false},{"name":"Mills Bomb (No.36M)","focus":"Lancer","range":"close","damage":6,"salvo":null,"qualities":"Zone, Étourdissant, Imprécis, Lancer","escalation":false}],"abilities":[{"name":"L''Œil s''ouvre","text":"Une fois par scène, Singh peut payer 2 Menace pour déclarer que l''Œil s''ouvre. Il prend alors sa forme libérée et peut attaquer tous les ennemis à portée Courte avec +3d20 pour toucher et l''effet Zone sur son kirpan. À la fin de son attaque, il doit réussir un test Volonté + Érudition de difficulté 2 pour rendormir l''Œil et reprendre sa forme mortelle ; en cas d''échec, toute personne à portée Courte subit 5 de stress mental. Chaque tour, les vrilles noires de l''Œil gagnent une zone adjacente et Singh doit consacrer une action majeure à le calmer, sinon tous ceux de cette zone subissent l''attaque mentale. La brume s''étend d''une zone par tour, jusqu''à huit zones, jusqu''à ce que tous les ennemis soient vaincus ou la scène d''action terminée, puis se dissipe sans danger."}],"threatSpends":[{"name":"L''Œil s''ouvre","cost":"2","text":"Une fois par scène : forme libérée, attaque de tous les ennemis à portée Courte (+3d20, Zone sur le kirpan)."}]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Caporal Akhee « l''Œil » Singh' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, '« Mad » Jack McMasters', 'Lieutenant-colonel, héros allié ennemi du Soleil Noir (Section M)', 'Héros allié couvert de décorations et légèrement dérangé, le lieutenant-colonel McMasters doit à son intrépidité, à son charisme et à sa haine de l''Ordre du Soleil Noir d''être une des armes les plus redoutables des Alliés. Amateur d''armes anciennes, il utilise son arc long en infiltration et adore croiser le fer avec les chanoines du Soleil Noir ou les horreurs du Mythe avec son épée « Nelly » ; il garderait dans une boîte la tête du chanoine qui a tué son frère et lui parle lors de ses accès de folie. (VO : "Mad" Jack McMasters)', '["Némésis","Alliés"]', 'Gamemaster Guide', 167, '{"rank":"nemesis","truths":["Ennemi héroïque du Soleil Noir","Gentleman de la vieille école"],"attributes":{"agility":8,"brawn":9,"coordination":8,"insight":9,"reason":8,"will":12},"skills":[{"key":"academia","rank":1,"focuses":["Occultisme"]},{"key":"athletics","rank":2,"focuses":["Entraînement physique"]},{"key":"fighting","rank":3,"focuses":["Armes de mêlée","Corps à corps","Exotique"]},{"key":"observation","rank":2,"focuses":[]},{"key":"persuasion","rank":2,"focuses":[]},{"key":"resilience","rank":4,"focuses":[]},{"key":"stealth","rank":2,"focuses":[]},{"key":"survival","rank":2,"focuses":[]},{"key":"tactics","rank":1,"focuses":[]},{"key":"vehicles","rank":1,"focuses":[]}],"stress":16,"injuries":3,"armour":2,"courage":7,"attacks":[{"name":"Sten Mk.V Submachine Gun","focus":"Corps à corps","range":"close","damage":5,"salvo":"Étourdissant","qualities":"Imprécis","escalation":false},{"name":"Longbow","focus":"Exotique","range":"long","damage":6,"salvo":"Vicieux","qualities":"Perforant 1, Fiable, Subtil","escalation":false},{"name":"Épée longue (Nelly)","focus":"Armes de mêlée","range":"contact","damage":6,"salvo":null,"qualities":"Fléau","escalation":false},{"name":"Mills Bomb (No.36M)","focus":"Lancer","range":"close","damage":7,"salvo":null,"qualities":"Zone, Étourdissant, Imprécis, Lancer","escalation":false}],"abilities":[{"name":"Mort au Soleil Noir !","text":"McMasters est sujet à des accès de… (texte interrompu dans le livre)."},{"name":"Au-delà de la peur","text":"Si McMasters subit une blessure due à une attaque mentale ou à une source du Mythe, il peut payer 2 Menace pour l''ignorer."},{"name":"Mélancolie","text":"Mad Jack est sujet à la mélancolie et ne s''anime souvent qu''en complotant la chute du Soleil Noir. Face à ces scélérats nazis, il peut, après avoir effectué une attaque, dépenser 2 Élan pour en faire une seconde."}],"threatSpends":[{"name":"Au-delà de la peur","cost":"2","text":"Ignore une blessure due à une attaque mentale ou à une source du Mythe."}]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = '« Mad » Jack McMasters' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Major Seraph, le Sorcier blanc', 'Sorcier et adepte, « chef des barbouzes » de la Section M', 'Puissant sorcier et adepte, Seraph est mince, pâle et anguleux, avec des traits chevalins et une crinière d''un blanc surnaturel. Vêtu d''une tenue militaire et d''un manteau ou d''un blouson d''aviateur, il préfère son khukri aux armes conventionnelles, mais la sorcellerie reste son arme principale, adaptée aux traditions locales (magie viking en Scandinavie, égyptienne dans le désert) ; on dit qu''il prend parfois la forme d''un archange vengeur ou d''un démon en libérant ses sorts les plus puissants. (VO : Major Seraph: The White Witchman)', '["Némésis","Alliés"]', 'Gamemaster Guide', 167, '{"rank":"nemesis","truths":["Sorcier mystérieux venu d''ailleurs"],"attributes":{"agility":8,"brawn":8,"coordination":8,"insight":9,"reason":9,"will":12},"skills":[{"key":"academia","rank":5,"focuses":["Occultisme"]},{"key":"athletics","rank":1,"focuses":["Entraînement physique"]},{"key":"fighting","rank":2,"focuses":["Armes de mêlée","Exotique"]},{"key":"observation","rank":2,"focuses":[]},{"key":"persuasion","rank":2,"focuses":[]},{"key":"resilience","rank":2,"focuses":[]},{"key":"stealth","rank":2,"focuses":["Camouflage"]},{"key":"survival","rank":2,"focuses":[]},{"key":"tactics","rank":2,"focuses":["Tactique de terrain"]}],"stress":14,"injuries":3,"armour":1,"courage":5,"attacks":[{"name":"Khukri enchanté","focus":"Armes de mêlée","range":"contact","damage":4,"salvo":null,"qualities":"Vicieux, Fléau","escalation":false},{"name":"Revolver Webley","focus":"Armes de poing","range":"close","damage":5,"salvo":"Vicieux","qualities":"Combat rapproché, Fiable","escalation":false},{"name":"Mills Bomb (No.36M)","focus":"Lancer","range":"close","damage":7,"salvo":null,"qualities":"Zone, Étourdissant, Imprécis, Munition","escalation":false},{"name":"Grenade Ibn Ghazi","focus":"Lancer","range":"close","damage":3,"salvo":null,"qualities":"Zone, Imprécis, Munition, révèle les ennemis cachés","escalation":false}],"abilities":[{"name":"Pouvoir","text":"Pouvoir : 6."},{"name":"Sorts et rituels","text":"Seraph est un puissant lanceur de sorts qui lance ses sorts avec la Volonté ; il peut apprendre des sorts de traditions différentes et a accès à tous les livres de sorts, des traditions alliées comme du Mythe, et à tous les rituels. Sélection type : Lance de Lug, Bienfaits du Dagda, Cor de Néit, Racines de la Terre, Malédiction de Loki, Sagesse de Frigg, Tempête de vagues, Bassin de félicité limpide, Voie du Gardien de la porte, Renvoi d''entité (rituel), Détection d''enchantement (rituel), Arpenteur des plans (rituel)."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Major Seraph, le Sorcier blanc' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Le très honorable Alexander (Alec) Ward-Gray, vicomte Towton', 'Chef patricien de la Section M', 'Parti chercher fortune en mer, Alec Towton est revenu bâtir son propre empire commercial et s''est lancé dans son plus grand défi : aider la Section M à défendre la Grande-Bretagne contre l''occultisme nazi, dont il a lui-même éprouvé les dangers lors de ses voyages. Petit, souple et charismatique, déterminé, il entretient des liens étroits avec des universitaires d''Oxford et de Miskatonic, notamment le professeur Richard Deadman. (VO : The Right Hon. Alexander (Alec) Ward-Gray, Viscount Towton)', '["Némésis","Alliés"]', 'Gamemaster Guide', 168, '{"rank":"nemesis","truths":["Chef patricien de la Section M","Linguiste prodige"],"attributes":{"agility":8,"brawn":8,"coordination":8,"insight":9,"reason":11,"will":10},"skills":[{"key":"academia","rank":2,"focuses":["Linguistique","Occultisme"]},{"key":"athletics","rank":2,"focuses":[]},{"key":"engineering","rank":1,"focuses":[]},{"key":"fighting","rank":1,"focuses":[]},{"key":"observation","rank":2,"focuses":[]},{"key":"persuasion","rank":3,"focuses":[]},{"key":"resilience","rank":2,"focuses":[]},{"key":"stealth","rank":2,"focuses":["Déguisement"]},{"key":"survival","rank":2,"focuses":[]},{"key":"tactics","rank":2,"focuses":["Commandement"]},{"key":"vehicles","rank":1,"focuses":[]}],"stress":12,"injuries":3,"armour":1,"courage":4,"attacks":[{"name":"Revolver Webley","focus":"Armes de poing","range":"close","damage":5,"salvo":"Vicieux","qualities":"Combat rapproché, Fiable","escalation":false}],"abilities":[{"name":"Amis et alliés","text":"Towton s''est fait des alliés dans le monde entier et dans tous les milieux. S''il a le temps de faire jouer ses contacts, il peut payer 1 Menace pour trouver un ami ou un allié en mesure de l''aider."},{"name":"Aventurier chevronné","text":"Le vicomte Towton a mené une vie de défis et d''aventures. Lors de tout test utilisant la Perception ou le Raisonnement, il peut relancer 1d20."}],"threatSpends":[{"name":"Amis et alliés","cost":"1","text":"Avec du temps pour activer ses contacts : un ami ou allié en mesure de l''aider."}]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Le très honorable Alexander (Alec) Ward-Gray, vicomte Towton' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Margaret « Peggy » Walsh', 'Assistante personnelle de Lord Towton (Section M)', 'Élevée dans une famille écossaise stricte, Miss Walsh semble être la secrétaire modèle, chargée du bon déroulement des journées de Lord Towton. Les apparences sont trompeuses : toujours impeccable, elle a gardé une âme sauvage et a pris ce poste justement pour le danger et l''aventure ; jeune, jolie et intrépide, elle a aussi la tête sur les épaules et un grand sens de l''organisation. (VO : Margaret "Peggy" Walsh)', '["Némésis","Alliés"]', 'Gamemaster Guide', 169, '{"rank":"nemesis","truths":["Assistante personnelle inébranlable"],"attributes":{"agility":8,"brawn":7,"coordination":8,"insight":10,"reason":9,"will":12},"skills":[{"key":"academia","rank":2,"focuses":["Occultisme"]},{"key":"athletics","rank":1,"focuses":[]},{"key":"fighting","rank":1,"focuses":[]},{"key":"medicine","rank":1,"focuses":[]},{"key":"observation","rank":3,"focuses":["Ouïe"]},{"key":"persuasion","rank":3,"focuses":["Négociation"]},{"key":"resilience","rank":2,"focuses":[]},{"key":"stealth","rank":2,"focuses":["Déguisement"]},{"key":"survival","rank":1,"focuses":[]},{"key":"tactics","rank":3,"focuses":["Commandement"]},{"key":"vehicles","rank":1,"focuses":[]}],"stress":14,"injuries":3,"armour":0,"courage":5,"attacks":[{"name":"Parapluie Wellington (tir)","focus":"Armes de poing","range":"close","damage":6,"salvo":"Vicieux","qualities":"Caché, Fiable","escalation":false}],"abilities":[{"name":"Tirée à quatre épingles","text":"Miss Walsh présente une façade parfaite de bonnes manières : tantôt elle se fond dans le décor, tantôt son regard réprobateur arrête les plus têtus. Elle réduit de 1 la difficulté de tous ses tests de Discrétion, son air réservé poussant les autres à l''ignorer. Quand elle veut être remarquée, elle peut payer 2 Menace pour faire une attaque mentale contre un seul personnage à portée Courte : test Volonté + Persuasion de difficulté 1 qui inflige 5 de stress mental avec l''effet Étourdissant. Les blessures mentales qu''elle inflige relèvent de l''embarras plus que du mal et se récupèrent automatiquement (sans risque de séquelle) à la fin de la scène."},{"name":"Âme sauvage","text":"Miss Walsh adore l''aventure et les prouesses audacieuses. Quand elle achète un ou plusieurs d20 sur un test de compétence d''acrobatie, d''escalade ou de course, elle peut relancer 1d20."}],"threatSpends":[{"name":"Regard réprobateur","cost":"2","text":"Attaque mentale contre un personnage à portée Courte : Volonté + Persuasion, difficulté 1, 5 de stress mental, Étourdissant ; blessures récupérées à la fin de la scène."}]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Margaret « Peggy » Walsh' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Arthur Morris', 'Garde du corps et chauffeur de Lord Towton (Section M)', 'Recruté après être intervenu dans une bagarre devant un club de Soho, Morris est désormais chauffeur, homme à tout faire et partenaire d''entraînement de Sa Seigneurie. Aussi loyal que Miss Walsh, il parle rarement de l''étrange rencontre qui les a menés à la Section M, sauf à glisser de sombres allusions après quelques verres. Fort, trapu, le nez cassé par son ancienne carrière, il est réputé pour son sens du devoir plus que pour son humour.', '["Némésis","Alliés"]', 'Gamemaster Guide', 169, '{"rank":"nemesis","truths":["Garde du corps de confiance","Ancien lutteur et voyou"],"attributes":{"agility":9,"brawn":12,"coordination":9,"insight":8,"reason":7,"will":9},"skills":[{"key":"athletics","rank":2,"focuses":["Entraînement physique"]},{"key":"engineering","rank":1,"focuses":[]},{"key":"fighting","rank":4,"focuses":["Main nue"]},{"key":"medicine","rank":1,"focuses":[]},{"key":"observation","rank":2,"focuses":[]},{"key":"persuasion","rank":3,"focuses":["Intimidation"]},{"key":"resilience","rank":3,"focuses":["Endurance"]},{"key":"stealth","rank":1,"focuses":[]},{"key":"survival","rank":1,"focuses":[]},{"key":"vehicles","rank":2,"focuses":["Voitures"]}],"stress":15,"injuries":3,"armour":3,"courage":4,"attacks":[{"name":"Poing américain","focus":"Main nue","range":"contact","damage":6,"salvo":null,"qualities":"Étourdissant, Caché","escalation":false}],"abilities":[{"name":"Le une-deux","text":"Si Morris porte un coup avec son focus Main nue et génère 2 Élan, il peut frapper la cible une seconde fois, sans nouveau test ; l''Élan peut être dépensé normalement. Cela ne compte pas comme une action supplémentaire, mais après l''avoir utilisé, Morris ne peut plus faire d''attaque de mêlée jusqu''à son prochain tour."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Arthur Morris' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Dr Dennis Parker', 'Chef de la recherche et intendant de la Section M', 'Chef de la recherche à Clemens Park, ancien chimiste industriel de Towton, le Dr Parker garde une attitude ouverte face aux étrangetés qui l''entourent, tout en restant perplexe devant le tour que prend sa vie. Il doit fournir sans fin gadgets et inventions aux agents de terrain de la Section M ; calme et méthodique, l''œil vert qui ne rate rien, il est capable de grands bonds de logique mais ne donne son avis que lorsqu''il a quelque chose à dire.', '["Némésis","Alliés"]', 'Gamemaster Guide', 170, '{"rank":"nemesis","truths":["Génie technologique","Intendant"],"attributes":{"agility":7,"brawn":7,"coordination":7,"insight":10,"reason":12,"will":11},"skills":[{"key":"academia","rank":5,"focuses":["Science"]},{"key":"athletics","rank":1,"focuses":[]},{"key":"engineering","rank":4,"focuses":["Génie mécanique"]},{"key":"fighting","rank":1,"focuses":[]},{"key":"medicine","rank":1,"focuses":[]},{"key":"observation","rank":4,"focuses":["Vue"]},{"key":"persuasion","rank":2,"focuses":[]},{"key":"resilience","rank":1,"focuses":[]},{"key":"vehicles","rank":1,"focuses":[]}],"stress":12,"injuries":3,"armour":0,"courage":3,"attacks":[{"name":"Derringer à vapeur de Parker","focus":"Exotique","range":"close","damage":5,"salvo":"Intense","qualities":"Fléau, Caché","escalation":false}],"abilities":[{"name":"Intellect de génie","text":"Parker peut relancer 1d20 sur tout test utilisant la Perception ou le Raisonnement."},{"name":"Mon petit ami","text":"Parker bricole sans cesse et invente des variantes intéressantes de gadgets existants. S''il paie 1 Menace, il a un tel appareil sur lui : en général son Derringer à vapeur (version compacte du fusil à vapeur Blevin), mais le MJ peut autoriser toutes sortes de gadgets."}],"threatSpends":[{"name":"Mon petit ami","cost":"1","text":"Parker a sur lui un gadget de son invention (en général le Derringer à vapeur)."}]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Dr Dennis Parker' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Résistant / partisan', 'Combattant de la Résistance', 'Ces braves combattants opèrent clandestinement, vivant parmi la population ou frappant depuis les collines, les montagnes et les lieux abandonnés. Les valeurs données sont celles d''un résistant type ; compétences, armes et équipement varient selon le milieu, le métier et le pays, qu''ils soient parachutés depuis Londres ou pris à l''occupant. (VO : Resistance Fighter/Partisan)', '["Troupe","Alliés"]', 'Gamemaster Guide', 170, '{"rank":"trooper","truths":["Civil voué à renverser l''occupant nazi"],"attributes":{"agility":8,"brawn":8,"coordination":9,"insight":7,"reason":7,"will":9},"skills":[{"key":"athletics","rank":1,"focuses":[]},{"key":"engineering","rank":1,"focuses":["Explosifs"]},{"key":"fighting","rank":2,"focuses":["Corps à corps"]},{"key":"resilience","rank":3,"focuses":[]},{"key":"stealth","rank":2,"focuses":[]},{"key":"tactics","rank":1,"focuses":[]}],"stress":6,"injuries":1,"armour":0,"courage":2,"attacks":[{"name":"Maschinenpistole 40 (MP 40)","focus":"Corps à corps","range":"close","damage":4,"salvo":"Étourdissant","qualities":"Imprécis","escalation":false},{"name":"Stielhandgranate 24","focus":"Lancer","range":"close","damage":5,"salvo":null,"qualities":"Zone, Étourdissant, Munition","escalation":true}],"abilities":[],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Résistant / partisan' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Ariane Dubois', 'Héroïne et cheffe de la Résistance française', 'Pilier de la Résistance française, Ariane est la hantise des officiers de la Wehrmacht. Poussée d''abord par la vengeance après la mort de ses parents aux mains du Soleil Noir, elle chargeait Lugers au poing tandis que la terrifiante créature liée à elle depuis l''opération Pandemonium dévorait l''esprit d''un nazi de plus. Elle a compris depuis que la vengeance est un plat qui se mange froid et est devenue une cheffe rusée et coriace qui planifie de féroces attaques contre l''occupant.', '["Némésis","Alliés"]', 'Gamemaster Guide', 171, '{"rank":"nemesis","truths":["Héroïne de la Résistance","Hantée par une créature symbiotique"],"attributes":{"agility":9,"brawn":9,"coordination":10,"insight":9,"reason":8,"will":9},"skills":[{"key":"academia","rank":1,"focuses":["Occultisme"]},{"key":"athletics","rank":2,"focuses":["Course"]},{"key":"engineering","rank":2,"focuses":["Explosifs"]},{"key":"fighting","rank":3,"focuses":["Armes de poing"]},{"key":"observation","rank":2,"focuses":[]},{"key":"persuasion","rank":2,"focuses":[]},{"key":"resilience","rank":2,"focuses":[]},{"key":"stealth","rank":2,"focuses":["Déguisement"]},{"key":"survival","rank":1,"focuses":[]},{"key":"tactics","rank":2,"focuses":[]},{"key":"vehicles","rank":1,"focuses":[]}],"stress":11,"injuries":3,"armour":4,"courage":3,"attacks":[{"name":"Deux Luger P08 9 mm","focus":"Armes de poing","range":"close","damage":5,"salvo":"Vicieux","qualities":"Combat rapproché","escalation":false},{"name":"Stielhandgranate 24","focus":"Lancer","range":"medium","damage":6,"salvo":null,"qualities":"Zone, Étourdissant, Munition","escalation":false}],"abilities":[{"name":"Les deux flingues","text":"Dubois est experte du tir à deux pistolets. Elle peut faire deux attaques avec ses Lugers comme tout personnage maniant deux armes, ou concentrer son feu sur un seul ennemi : elle fait alors une seule attaque à distance, mais ajoute +2 au stress infligé et l''effet Intense."},{"name":"Protecteur démoniaque","text":"Dubois a un allié démoniaque, son compagnon de chaque instant. Si Ariane est menacée, le démon laisse tout tomber pour venir à son aide et la défendre jusqu''à la mort."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Ariane Dubois' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'La créature d''Ariane', 'Démon buveur d''âmes lié à Ariane Dubois', 'La créature spirituelle d''Ariane a évolué avec elle. Du petit démon ailé qui se perchait sur son épaule, elle peut désormais grandir et se transformer en béhémoth brutal et irrésistible sur le champ de bataille. (VO : Ariane''s Creature)', '["Lieutenant","Alliés"]', 'Gamemaster Guide', 171, '{"rank":"lieutenant","truths":["Démon buveur d''âmes"],"attributes":{"agility":10,"brawn":14,"coordination":10,"insight":8,"reason":6,"will":12},"skills":[{"key":"academia","rank":5,"focuses":["Occultisme"]},{"key":"athletics","rank":4,"focuses":[]},{"key":"fighting","rank":3,"focuses":[]},{"key":"persuasion","rank":3,"focuses":[]},{"key":"resilience","rank":5,"focuses":[]}],"stress":20,"injuries":2,"armour":5,"courage":8,"attacks":[{"name":"Serres horribles","focus":"Main nue","range":"contact","damage":7,"salvo":null,"qualities":"Vicieux","escalation":false}],"abilities":[{"name":"Boire l''âme","text":"Par une action majeure, la créature peut utiliser Boire l''âme contre une victime ennemie de taille humaine à son contact. Elle fait un test Volonté + Persuasion opposé à Volonté + Résilience de la cible (difficulté 1 des deux côtés) ; en cas de réussite, elle inflige 6 de stress mental avec les effets Vidange et Perforant 1, et Ariane récupère 1 stress par point de Fatigue infligé. Si la victime est vaincue par cette attaque, le démon boit son âme : ses pensées et souvenirs rejoignent la créature (et donc Ariane). Le démon ne peut tenter cette attaque qu''une fois par individu."},{"name":"Force extraordinaire 1","text":"Le démon gagne un succès automatique à tous les tests de compétence basés sur la Force. Il inflige en outre +1 stress physique en mêlée, a +1 Stress maximum et +1 Armure, le tout inclus dans le profil."},{"name":"Menaçant","text":"Quand la créature entre en scène, générez immédiatement 1 Menace."},{"name":"Coup de queue","text":"Si le démon subit du stress d''une attaque de mêlée, il peut payer 2 Menace pour infliger 4 de stress physique à son attaquant et le renverser."}],"threatSpends":[{"name":"Coup de queue","cost":"2","text":"Après avoir subi du stress d''une attaque de mêlée : 4 de stress physique à l''attaquant, qui est renversé."}]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'La créature d''Ariane' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Fantassin américain', 'Soldat d''infanterie américain', 'L''infanterie est la colonne vertébrale de l''armée américaine, une force de combat souple et efficace. Parfois desservie par la qualité de ses recrues (les meilleures partant dans les unités d''élite), elle est bien équipée et bien nourrie, et s''appuie sur la plus grande structure de soutien de toutes les armées : aviation, artillerie et soins de premier ordre. (VO : US Infantryman)', '["Troupe","Alliés"]', 'Gamemaster Guide', 172, '{"rank":"trooper","truths":["Fantassin bien équipé"],"attributes":{"agility":8,"brawn":8,"coordination":9,"insight":8,"reason":8,"will":7},"skills":[{"key":"athletics","rank":2,"focuses":[]},{"key":"fighting","rank":2,"focuses":["Fusils"]},{"key":"medicine","rank":1,"focuses":[]},{"key":"resilience","rank":1,"focuses":[]},{"key":"stealth","rank":1,"focuses":["Camouflage"]},{"key":"survival","rank":1,"focuses":[]},{"key":"tactics","rank":1,"focuses":[]},{"key":"vehicles","rank":1,"focuses":[]}],"stress":5,"injuries":1,"armour":1,"courage":1,"attacks":[{"name":"M1 Garand Rifle","focus":"Fusils","range":"medium","damage":5,"salvo":"Vicieux","qualities":"Fiable","escalation":false},{"name":"Baïonnette","focus":"Armes de mêlée","range":"contact","damage":3,"salvo":null,"qualities":"Perforant 1","escalation":false},{"name":"Pineapple Grenade (M17)","focus":"Lancer","range":"close","damage":6,"salvo":null,"qualities":"Zone, Étourdissant, Imprécis, Munition","escalation":true},{"name":"M1A1 Bazooka","focus":"Armes lourdes","range":"medium","damage":6,"salvo":null,"qualities":"Vicieux, Encombrant, Escalade, Imprécis, Tueur de géants, Lourd, Munition","escalation":true},{"name":"Browning Automatic Rifle (BAR)","focus":"Fusils","range":"medium","damage":5,"salvo":"Zone","qualities":"Lourd, Imprécis","escalation":true}],"abilities":[],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Fantassin américain' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Officier d''infanterie américain', 'Officier d''infanterie américain', 'Les officiers d''infanterie américains connaissent bien la théorie de la guerre mais manquent de l''expérience du terrain et du savoir tactique de leurs homologues britanniques. Après l''entrée en guerre des États-Unis en 1941, ils reçoivent leur baptême du feu en Europe comme en Orient et s''affirment comme des meneurs courageux et déterminés. (VO : US Infantry Officer)', '["Troupe","Alliés"]', 'Gamemaster Guide', 172, '{"rank":"trooper","truths":["Chef bien formé mais inexpérimenté"],"attributes":{"agility":8,"brawn":8,"coordination":8,"insight":8,"reason":9,"will":7},"skills":[{"key":"academia","rank":1,"focuses":[]},{"key":"athletics","rank":1,"focuses":[]},{"key":"fighting","rank":1,"focuses":["Armes de poing"]},{"key":"observation","rank":3,"focuses":[]},{"key":"persuasion","rank":2,"focuses":[]},{"key":"tactics","rank":2,"focuses":["Commandement"]}],"stress":4,"injuries":1,"armour":1,"courage":1,"attacks":[{"name":"M1911A1","focus":"Armes de poing","range":"close","damage":4,"salvo":"Vicieux","qualities":"Combat rapproché","escalation":false},{"name":"Pineapple Grenade (M17)","focus":"Lancer","range":"close","damage":6,"salvo":null,"qualities":"Zone, Étourdissant, Imprécis, Munition","escalation":false}],"abilities":[],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Officier d''infanterie américain' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Forces d''élite américaines', 'Parachutiste ou ranger américain', 'Les divisions aéroportées et les Rangers forment l''essentiel des forces d''élite américaines. Les parachutistes, tenaces, sont entraînés à tomber sur des positions stratégiques et à les tenir, sans être équipés pour des combats prolongés ; les Rangers, volontaires issus d''autres unités, misent sur la discipline physique, l''expertise tactique et l''adaptation rapide en petites équipes soudées. (VO : US Elite Forces)', '["Lieutenant","Alliés"]', 'Gamemaster Guide', 173, '{"rank":"lieutenant","truths":["Forces d''élite américaines"],"attributes":{"agility":9,"brawn":9,"coordination":9,"insight":8,"reason":8,"will":8},"skills":[{"key":"athletics","rank":3,"focuses":[]},{"key":"fighting","rank":3,"focuses":["Corps à corps"]},{"key":"observation","rank":2,"focuses":[]},{"key":"persuasion","rank":1,"focuses":[]},{"key":"resilience","rank":2,"focuses":[]},{"key":"stealth","rank":2,"focuses":["Discrétion rurale"]},{"key":"survival","rank":2,"focuses":[]},{"key":"tactics","rank":1,"focuses":["Opérations clandestines"]},{"key":"vehicles","rank":1,"focuses":[]}],"stress":11,"injuries":2,"armour":2,"courage":2,"attacks":[{"name":"Thompson Submachine Gun","focus":"Corps à corps","range":"close","damage":4,"salvo":"Étourdissant","qualities":"Imprécis","escalation":false},{"name":"Couteau de tranchée","focus":"Armes de mêlée","range":"contact","damage":3,"salvo":null,"qualities":"Vicieux, Caché","escalation":false},{"name":"Pineapple Grenade (M17)","focus":"Lancer","range":"close","damage":6,"salvo":null,"qualities":"Zone, Étourdissant, Imprécis, Munition","escalation":false}],"abilities":[{"name":"Au choix","text":"Le PNJ a soit la capacité Aéroporté, soit Derrière les lignes ennemies, plus la capacité Vaincre ou mourir."},{"name":"Aéroporté","text":"Entraînées au saut en parachute, ces troupes peuvent, appelées en renfort, arriver par les airs depuis un avion de transport. Toute attaque à distance contre elles avant qu''elles n''atterrissent, au début de leur premier tour, subit +1 difficulté."},{"name":"Derrière les lignes ennemies","text":"Les Rangers ont l''habitude d''opérer derrière les lignes ennemies et peuvent relancer un d20 sur tout test de Discrétion ou de Survie."},{"name":"Vaincre ou mourir","text":"Parachutistes et Rangers savent qu''ils seront souvent coupés de tout soutien. Leur détermination est telle qu''ils peuvent payer 1 Menace pour gagner +2 Moral."}],"threatSpends":[{"name":"Vaincre ou mourir","cost":"1","text":"Gagne +2 Moral."}]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Forces d''élite américaines' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Chasseurs de démons Pathfinders', 'Guerriers spirituels des Premières Nations (Majestic)', 'Les Chasseurs de démons, appelés Keijín (« cinq » en tlingit) par leur peuple, sont les guerriers les plus braves et les plus spirituels, seuls à apprendre les voies des démons et l''art de les vaincre. Armés d''armures et d''armes tlingit Shé Xelit, ils ont rejoint les Pathfinders américains sous les ordres de Majestic pour combattre le mal déchaîné par le Troisième Reich. (VO : Pathfinder Demon Hunters)', '["Lieutenant","Alliés"]', 'Gamemaster Guide', 174, '{"rank":"lieutenant","truths":["Guerriers spirituels des Premières Nations"],"attributes":{"agility":9,"brawn":8,"coordination":8,"insight":8,"reason":8,"will":10},"skills":[{"key":"athletics","rank":3,"focuses":["Entraînement physique"]},{"key":"fighting","rank":3,"focuses":["Armes de mêlée"]},{"key":"observation","rank":2,"focuses":[]},{"key":"persuasion","rank":1,"focuses":[]},{"key":"resilience","rank":2,"focuses":[]},{"key":"stealth","rank":2,"focuses":["Discrétion rurale"]},{"key":"survival","rank":2,"focuses":[]},{"key":"tactics","rank":1,"focuses":["Opérations clandestines"]},{"key":"vehicles","rank":1,"focuses":[]}],"stress":10,"injuries":2,"armour":2,"courage":4,"attacks":[{"name":"Pistolet à vapeur Blevin","focus":"Armes de poing","range":"close","damage":3,"salvo":"Intense ou Persistant 3","qualities":"Fléau","escalation":false},{"name":"Arc tlingit","focus":"Exotique","range":"long","damage":5,"salvo":"Vicieux","qualities":"Perforant 1, Fiable, Subtil, Fléau","escalation":false},{"name":"Épée tlingit","focus":"Armes de mêlée","range":"contact","damage":6,"salvo":null,"qualities":"Perforant 2, Fiable, Subtil, Fléau","escalation":false}],"abilities":[{"name":"Croyances spirituelles","text":"Les Chasseurs de démons acceptent le surnaturel comme partie ordinaire de l''existence. Face aux menaces du Mythe, ils gagnent l''effet Vicieux sur toutes leurs attaques à l''arc tlingit et toutes leurs attaques de mêlée, et augmentent leur Armure de +4 contre les sorts et les attaques des créatures du Mythe."},{"name":"La victoire m''apaise","text":"Chaque fois qu''un sorcier nazi ou une créature occulte est vaincu à portée Moyenne d''un Chasseur de démons, celui-ci récupère immédiatement 3 Stress."},{"name":"La Volonté et elle seule","text":"Les Chasseurs de démons tirent leur bonus d''Armure et de dégâts de mêlée de la Volonté plutôt que de la Force."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Chasseurs de démons Pathfinders' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Les Salamandres flamboyantes', 'Marines pyromanes anti-Mythe (Majestic)', '« Si ça rampe, fais-le flétrir. Un doute ? Brûle-le ! » : telle est la devise des Salamandres flamboyantes du corps Majestic, des Marines pyromanes dont la réponse aux horreurs du Mythe est de les purifier par le feu. Opérant en petites sections dans une combinaison intégrale ignifugée et pare-balles, sous les ordres du capitaine Leon Husk, ils emploient toutes sortes d''armes incendiaires, jusqu''au redoutable lance-flammes Dragon''s Breath Mk II. (VO : The Flaming Salamanders)', '["Lieutenant","Alliés"]', 'Gamemaster Guide', 174, '{"rank":"lieutenant","truths":["Pyromanes anti-Mythe"],"attributes":{"agility":8,"brawn":10,"coordination":9,"insight":8,"reason":7,"will":9},"skills":[{"key":"athletics","rank":2,"focuses":[]},{"key":"engineering","rank":2,"focuses":["Génie de combat","Explosifs"]},{"key":"fighting","rank":2,"focuses":["Armes lourdes"]},{"key":"medicine","rank":1,"focuses":[]},{"key":"observation","rank":1,"focuses":[]},{"key":"persuasion","rank":1,"focuses":[]},{"key":"resilience","rank":3,"focuses":[]},{"key":"survival","rank":2,"focuses":[]},{"key":"tactics","rank":2,"focuses":[]},{"key":"vehicles","rank":1,"focuses":[]}],"stress":13,"injuries":2,"armour":3,"courage":4,"attacks":[{"name":"Lance-flammes Dragon''s Breath Mk II","focus":"Armes lourdes","range":"medium","damage":6,"salvo":"Zone ou Perforant 2","qualities":"Persistant 4, Escalade, Fléau, Débilitant","escalation":false},{"name":"Bazooka électrique Crackler M5-1","focus":"Armes lourdes","range":"medium","damage":7,"salvo":"Zone ou Intense","qualities":"Étourdissant, Fléau, Escalade, Imprécis","escalation":true},{"name":"Grenade au napalm","focus":"Lancer","range":"close","damage":5,"salvo":null,"qualities":"Zone, Persistant 4, Imprécis, Munition","escalation":true}],"abilities":[{"name":"Tout brûler","text":"Les Salamandres préfèrent les lance-flammes à toute autre arme, mais quand il faut porter plus loin, elles remplacent les munitions ordinaires par des balles incendiaires. Lors d''une attaque en salve avec une arme à feu conventionnelle (arme de poing, carabine, fusil, mitraillette, etc.), une Salamandre peut ajouter l''effet Perforant 4 à l''attaque au lieu des options de salve normales."},{"name":"Ignifugé","text":"Les uniformes et armures des Salamandres sont traités contre le feu : elles gagnent +1 Armure et ignorent l''effet Persistant X des attaques de feu, de flammes ou de chaleur."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Les Salamandres flamboyantes' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Les Furies de Foley', 'Parachutistes d''élite de réaction rapide (Majestic)', 'Cohorte de parachutistes d''élite largués pour contrer les assauts soutenus par le Mythe ou nettoyer les horreurs égarées, les Furies sont pour Majestic l''escouade de nettoyage ultime. Armées des toutes dernières armes de Majestic, elles comptent plus de 100 sauts de combat, des déserts d''Afrique aux jungles de Birmanie ; leur insigne montre une déesse grecque vengeresse déchirant un Serviteur, et elles sont commandées par le colonel Frank « Furious » Foley, vétéran de la 101e aéroportée. (VO : Foley''s Furies)', '["Lieutenant","Alliés"]', 'Gamemaster Guide', 175, '{"rank":"lieutenant","truths":["La mère de toutes les unités de réaction rapide","Le meilleur équipement possible"],"attributes":{"agility":9,"brawn":9,"coordination":9,"insight":8,"reason":8,"will":8},"skills":[{"key":"athletics","rank":3,"focuses":[]},{"key":"fighting","rank":3,"focuses":["Corps à corps"]},{"key":"observation","rank":2,"focuses":[]},{"key":"persuasion","rank":1,"focuses":[]},{"key":"resilience","rank":2,"focuses":[]},{"key":"stealth","rank":2,"focuses":["Discrétion rurale"]},{"key":"survival","rank":2,"focuses":[]},{"key":"tactics","rank":1,"focuses":["Opérations clandestines"]},{"key":"vehicles","rank":1,"focuses":[]}],"stress":11,"injuries":2,"armour":2,"courage":2,"attacks":[{"name":"Fusil Arclight Eastin-Bakhaus (EBAR)","focus":"Fusils","range":"medium","damage":5,"salvo":"Intense","qualities":"Étourdissant, Fléau, Escalade","escalation":false},{"name":"Couteau de tranchée Mk1 à électrificateur","focus":"Armes de mêlée","range":"contact","damage":4,"salvo":null,"qualities":"Étourdissant, Vicieux, Fléau","escalation":false},{"name":"Pineapple Grenade (M17)","focus":"Lancer","range":"close","damage":6,"salvo":null,"qualities":"Zone, Étourdissant, Imprécis, Munition","escalation":false},{"name":"Lance-grenades Coyote (grenades à fragmentation)","focus":"Armes lourdes","range":"long","damage":6,"salvo":null,"qualities":"Zone, Étourdissant, Indirect, Escalade, Imprécis, Munition","escalation":true}],"abilities":[{"name":"Aéroportés à jamais","text":"Les Furies sont tirées des meilleurs rangers aéroportés. Appelées en renfort, elles peuvent arriver par les airs depuis un avion de transport ; toute attaque à distance contre elles avant qu''elles n''atterrissent, au début de leur premier tour, subit +2 difficulté."},{"name":"T''es pas encore mort ?","text":"Pour les Furies, le soutien est un luxe dont on se passe. Lorsqu''elles opèrent sans soutien direct, elles gagnent +2 Moral."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Les Furies de Foley' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Sergent Brandon Carter', 'Sous-officier de l''armée américaine détaché auprès de Majestic', 'Détaché de l''armée américaine, Carter est l''un des rares survivants de « l''affaire de Stratford » ; depuis, il ne quitte plus un médaillon au Signe des Anciens qui donne à sa Thompson une vie propre et crache des balles chargées du Mythe. Grande gueule sans manières qui froisse officiers et supérieurs, il n''en a pas moins un courage et un engagement absolus, une haine des nazis et une fureur particulière envers le Soleil Noir ; soldat-né et excellent chef d''escouade, il n''hésite pas à affronter les pires horreurs. (VO : Sergeant Brandon Carter)', '["Némésis","Alliés"]', 'Gamemaster Guide', 176, '{"rank":"nemesis","truths":["Audacieux, effronté et direct","Sous-officier courageux"],"attributes":{"agility":9,"brawn":10,"coordination":10,"insight":8,"reason":8,"will":9},"skills":[{"key":"athletics","rank":3,"focuses":["Lancer"]},{"key":"engineering","rank":2,"focuses":["Explosifs"]},{"key":"fighting","rank":3,"focuses":["Corps à corps"]},{"key":"observation","rank":1,"focuses":[]},{"key":"persuasion","rank":1,"focuses":[]},{"key":"resilience","rank":3,"focuses":[]},{"key":"stealth","rank":2,"focuses":["Discrétion rurale"]},{"key":"survival","rank":2,"focuses":[]},{"key":"tactics","rank":2,"focuses":[]},{"key":"vehicles","rank":1,"focuses":[]}],"stress":13,"injuries":3,"armour":3,"courage":4,"attacks":[{"name":"Thompson Submachine Gun","focus":"Corps à corps","range":"close","damage":4,"salvo":"Étourdissant","qualities":"Imprécis","escalation":false},{"name":"Pineapple Grenade (M17)","focus":"Lancer","range":"close","damage":6,"salvo":null,"qualities":"Zone, Étourdissant, Imprécis, Munition, Fléau, Vicieux","escalation":false}],"abilities":[{"name":"Médaillon de pouvoir","text":"Le médaillon de Carter le protège du Mythe : son Armure contre les attaques des créatures du Mythe augmente de +3. De plus, ses attaques à la mitraillette ont les qualités Fléau et Vicieux contre toutes les créatures du Mythe."},{"name":"Avec moi, soldat !","text":"Quand le sergent Carter mène une escouade, il peut effectuer des réactions, mais doit payer 1 Menace pour cela."}],"threatSpends":[{"name":"Avec moi, soldat !","cost":"1","text":"En menant une escouade : effectuer une réaction."}]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Sergent Brandon Carter' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Professeur Richard Deadman', 'Professeur et sorcier, cofondateur de la Section M et de Majestic', '« Pasty » Deadman, comme on le surnomme à son grand dépit, est le professeur américain classique pris dans l''action, mais assez savant pour vaincre la magie du Mythe des nazis ; il a contribué à fonder la Section M et Majestic et compte parmi les plus puissants adeptes alliés. Il privilégie les magies protectrices, a l''œil pour les détails (« saviez-vous que… ») et collectionne avec obsession livres rares et antiquités, cherchant sans relâche les Chroniclos Atlantis et Lemuria, quitte à en oublier tout autre objectif. (VO : Professor Richard Deadman)', '["Némésis","Alliés"]', 'Gamemaster Guide', 176, '{"rank":"nemesis","truths":["Rat de bibliothèque distrait","Sorcier puissant"],"attributes":{"agility":9,"brawn":7,"coordination":8,"insight":9,"reason":11,"will":10},"skills":[{"key":"academia","rank":5,"focuses":["Histoire","Occultisme"]},{"key":"fighting","rank":2,"focuses":["Armes de poing"]},{"key":"medicine","rank":3,"focuses":["Premiers secours"]},{"key":"observation","rank":1,"focuses":[]},{"key":"persuasion","rank":3,"focuses":[]},{"key":"resilience","rank":5,"focuses":["Discipline"]},{"key":"stealth","rank":1,"focuses":[]}],"stress":15,"injuries":3,"armour":1,"courage":5,"attacks":[{"name":"M1911A1","focus":"Armes de poing","range":"close","damage":5,"salvo":null,"qualities":"Précis","escalation":false}],"abilities":[{"name":"Pouvoir","text":"Pouvoir : 5."},{"name":"Protections personnelles","text":"Les magies protectrices de Deadman augmentent de 2 la difficulté de tout sort lancé contre lui."},{"name":"Magies protectrices","text":"Deadman entretient une grande variété de charmes protecteurs sur lui-même et ses compagnons. Lui et tout allié à portée Courte gagnent +4 Couvert et Moral contre le stress causé par les sorts et les attaques magiques."},{"name":"Sorts et rituels","text":"Deadman est un puissant lanceur de sorts qui utilise le Raisonnement et a appris des sorts de nombreuses traditions ; il a accès à tous les livres de sorts, alliés comme du Mythe, et à tous les rituels. Sélection représentative : Lance de Lug, Bienfaits du Dagda, Cor de Néit, Racines de la Terre, Malédiction de Loki, Sagesse de Frigg, Tempête de vagues, Bassin de félicité limpide, Voie du Gardien de la porte, Renvoi d''entité (rituel), Détection d''enchantement (rituel), Arpenteur des plans (rituel)."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Professeur Richard Deadman' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Sally Armitage', 'Dirigeante de Majestic', 'L''implication de son père dans d''étranges événements à la fin des années 1920 et son enfance au bord du Miskatonic ont préparé Miss Armitage aux affaires déroutantes que traite Majestic. Directe, analytique et fine juge des caractères, elle exige de son équipe le même dévouement qu''elle ; sans pratiquer elle-même, elle admire et se méfie de quiconque prétend maîtriser les arts occultes, et sait mener les gens à en dire plus qu''ils ne devraient par des questions d''apparence anodine.', '["Némésis","Alliés"]', 'Gamemaster Guide', 178, '{"rank":"nemesis","truths":["Une main calme et sûre","Perspicace, se méfie de l''occulte"],"attributes":{"agility":8,"brawn":8,"coordination":8,"insight":9,"reason":9,"will":12},"skills":[{"key":"academia","rank":4,"focuses":["Occultisme"]},{"key":"athletics","rank":1,"focuses":[]},{"key":"fighting","rank":2,"focuses":["Armes de poing"]},{"key":"medicine","rank":2,"focuses":[]},{"key":"observation","rank":3,"focuses":[]},{"key":"persuasion","rank":3,"focuses":[]},{"key":"resilience","rank":2,"focuses":["Discipline"]},{"key":"tactics","rank":3,"focuses":["Commandement"]}],"stress":10,"injuries":3,"armour":0,"courage":5,"attacks":[{"name":"M1911A1","focus":"Armes de poing","range":"close","damage":5,"salvo":"Vicieux","qualities":"Combat rapproché","escalation":false}],"abilities":[{"name":"Conversation tranquille","text":"Lorsqu''elle converse avec un autre personnage, Sally peut, sans faire de test, poser une seule question comme avec la dépense d''Élan Obtenir des informations."},{"name":"Élevée au bord du Miskatonic","text":"Il en faut beaucoup pour faire paniquer une Armitage. Chaque fois que Sally subit une blessure mentale de source du Mythe (créatures, sorts, cultistes), elle peut payer 2 Menace pour l''ignorer."}],"threatSpends":[{"name":"Élevée au bord du Miskatonic","cost":"2","text":"Ignore une blessure mentale de source du Mythe."}]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Sally Armitage' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Dr Wilfred C. Llanfer', 'Bibliothécaire en chef de l''université Miskatonic (Majestic)', 'Bibliothécaire en chef de Miskatonic depuis le milieu des années 1930, le Dr Llanfer a beaucoup d''affection pour Sally Armitage, fille de son ancien mentor, et sert volontiers son pays, tout en craignant les conséquences d''une plongée trop profonde dans le savoir interdit. Précis et charmant, il ne s''emporte que devant le mépris du savoir ou des livres ; grand, sec, couronné de cheveux blancs, un peu voûté, il garde un esprit acéré et connaît l''emplacement de chaque livre de sa bibliothèque et le nom de chaque emprunteur. (VO : Dr. Wilfred C Llanfer)', '["Némésis","Alliés"]', 'Gamemaster Guide', 178, '{"rank":"nemesis","truths":["Universitaire de renommée mondiale","Autorité ésotérique"],"attributes":{"agility":9,"brawn":7,"coordination":8,"insight":10,"reason":11,"will":9},"skills":[{"key":"academia","rank":4,"focuses":["Histoire","Occultisme"]},{"key":"engineering","rank":2,"focuses":[]},{"key":"fighting","rank":2,"focuses":[]},{"key":"medicine","rank":2,"focuses":[]},{"key":"observation","rank":3,"focuses":[]},{"key":"persuasion","rank":3,"focuses":["Intimidation"]},{"key":"resilience","rank":2,"focuses":["Discipline"]},{"key":"tactics","rank":2,"focuses":[]}],"stress":11,"injuries":3,"armour":0,"courage":3,"attacks":[{"name":"M1911A1","focus":"Armes de poing","range":"close","damage":4,"salvo":"Vicieux","qualities":"Combat rapproché","escalation":false}],"abilities":[{"name":"Payez vos amendes, sinon…","text":"La bibliothèque de l''université Miskatonic est considérée comme un site sensible. À tout moment, le Dr Llanfer peut faire appel à une demi-douzaine de soldats des Forces d''élite américaines (règles normales des renforts ; ces renforts sont toujours disponibles en sa présence). Ces tueurs entraînés sont aussi des bibliothécaires compétents, avec 2 rangs en Érudition."},{"name":"Bibliothécaire occulte ultime","text":"La bibliothèque de Miskatonic est la première bibliothèque occulte du sol américain. En plus des règles habituelles des bibliothèques, elle compte comme un site occulte et possède au moins un exemplaire de chaque ouvrage du Mythe (sauf les Chroniclos Atlantis et Lemuria)."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Dr Wilfred C. Llanfer' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Étienne-Laurent de Marigny', 'Mystique créole, bureau officieux de Majestic dans le Sud', 'De Marigny vit dans une demeure extravagante de La Nouvelle-Orléans dont une annexe sert de bureau officieux à Majestic dans le Sud ; versé dans l''occulte et ancien légionnaire, il connaît les dangers de la guerre et des forces en jeu. Peu enthousiaste à l''idée de s''engager, il voit pourtant son travail contre le Soleil Noir et les Nachtwölfe comme un devoir solennel, ne prend que les élèves les plus doués et ne supporte pas les sots ; élégant, à la mode un peu surannée teintée d''uniforme, il a le regard souvent perdu ailleurs. (VO : Etienne-Laurent de Marigny)', '["Némésis","Alliés"]', 'Gamemaster Guide', 179, '{"rank":"nemesis","truths":["Mystique créole renommé","Spécialiste de l''occulte et de l''Orient","Soldat retraité"],"attributes":{"agility":9,"brawn":7,"coordination":8,"insight":10,"reason":10,"will":12},"skills":[{"key":"academia","rank":3,"focuses":["Histoire","Occultisme"]},{"key":"fighting","rank":2,"focuses":["Armes de poing","Armes de mêlée"]},{"key":"medicine","rank":1,"focuses":[]},{"key":"observation","rank":3,"focuses":[]},{"key":"persuasion","rank":3,"focuses":["Intimidation"]},{"key":"resilience","rank":3,"focuses":["Discipline"]},{"key":"stealth","rank":2,"focuses":[]},{"key":"survival","rank":2,"focuses":[]},{"key":"vehicles","rank":1,"focuses":[]}],"stress":15,"injuries":3,"armour":1,"courage":6,"attacks":[{"name":"M1911A1","focus":"Armes de poing","range":"close","damage":4,"salvo":"Vicieux","qualities":"Combat rapproché","escalation":false}],"abilities":[{"name":"Pouvoir","text":"Pouvoir : 5."},{"name":"Un homme aux multiples facettes","text":"Avec un héritage mêlant pratiquants français et africains, De Marigny puise dans une multitude de traditions ; en les honorant, il s''est entouré d''un cortège de fantômes et d''esprits qui le protègent des autres sorciers. Tous les sorts hostiles lancés sur lui voient leur difficulté augmenter de +2."},{"name":"Élèves doués","text":"De Marigny a toujours un apprenti à ses côtés pour l''aider à lancer des sorts et à se défendre. Ces élèves particulièrement doués ont Érudition 3 (Occultisme) en plus de leurs autres compétences."},{"name":"Sorts et rituels","text":"De Marigny lance ses sorts avec la Volonté et a appris des sorts de nombreuses traditions. Sélection représentative : Lance de Lug, Bienfaits du Dagda, Cor de Néit, Racines de la Terre, Malédiction de Loki, Sagesse de Frigg, Tempête de vagues, Renvoi d''entité (rituel), Détection d''enchantement (rituel), Arpenteur des plans (rituel)."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Étienne-Laurent de Marigny' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Kiyoshi Kato', 'Chef de la R&D et de la fabrication de Majestic', 'Descendant de forgerons de sabres du domaine d''Aizu installés à Hawaï, Kiyoshi s''est tourné vers les sciences : docteur en biologie, chimie et physique, pilier du MIT à la fin des années 1930 et proche du professeur Deadman, il voit le Mythe comme « de la science qu''il reste à démêler ». À la tête de la R&D de Majestic, il veille à ce que tous ses prototypes soient robustes et fiables ; mince, le regard perçant, il semble distrait mais évalue sans cesse la situation tout en rêvant de nouvelles armes.', '["Némésis","Alliés"]', 'Gamemaster Guide', 180, '{"rank":"nemesis","truths":["Maître technicien et armurier","Chef de la R&D et de la fabrication de Majestic"],"attributes":{"agility":9,"brawn":8,"coordination":11,"insight":11,"reason":11,"will":9},"skills":[{"key":"academia","rank":4,"focuses":["Science"]},{"key":"athletics","rank":1,"focuses":[]},{"key":"engineering","rank":4,"focuses":["Architecture","Génie de combat","Électronique","Explosifs","Génie mécanique"]},{"key":"fighting","rank":1,"focuses":[]},{"key":"medicine","rank":1,"focuses":[]},{"key":"observation","rank":3,"focuses":[]},{"key":"persuasion","rank":3,"focuses":[]},{"key":"resilience","rank":3,"focuses":[]},{"key":"survival","rank":1,"focuses":[]},{"key":"tactics","rank":1,"focuses":[]},{"key":"vehicles","rank":1,"focuses":[]}],"stress":10,"injuries":3,"armour":2,"courage":2,"attacks":[{"name":"M1911A1","focus":"Armes de poing","range":"close","damage":4,"salvo":"Vicieux","qualities":"Précis","escalation":false},{"name":"Katana Shé Xelit","focus":"Armes de mêlée","range":"contact","damage":4,"salvo":null,"qualities":"Parade, Fléau","escalation":false}],"abilities":[{"name":"Rétro-ingénierie","text":"Avec suffisamment de temps, Kato peut analyser et reproduire les effets de toute arme, munition ou appareil capturé, conventionnel, magique ou autre. Tous les tests du processus voient leur difficulté réduite de 2."},{"name":"Gilet Shé Xelit","text":"Ce gilet discret porté sous ses vêtements accorde +2 Armure et +1 Moral contre les attaques mentales des créatures du Mythe. Son porteur gagne en outre la vérité « Invisible aux yeux de l''Anormal »."},{"name":"Maître d''armes","text":"Kato excelle à créer des armes conventionnelles, expérimentales et magiques. Il peut doter toute arme qu''il fabrique d''un effet automatique de son choix."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Kiyoshi Kato' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Fantassin allemand', 'Soldat d''infanterie de la Heer', 'Très entraîné et discipliné, le fantassin allemand est aguerri, a le moral haut et a pris goût à la victoire après le Blitzkrieg. Déployé de la Norvège à l''Afrique du Nord, il forme le cœur de l''armée allemande. La plupart sont armés de fusils Gewehr 41 ou Karabiner 43, mais il n''est pas rare de voir un membre de l''escouade avec une MP40 ou un binôme servant une MG34 ou une MG42. (VO : German Infantry Soldier)', '["Troupe","Axe"]', 'Gamemaster Guide', 181, '{"rank":"trooper","truths":["Simple soldat"],"attributes":{"agility":8,"brawn":9,"coordination":8,"insight":8,"reason":8,"will":7},"skills":[{"key":"athletics","rank":2,"focuses":[]},{"key":"fighting","rank":2,"focuses":["Fusils"]},{"key":"resilience","rank":2,"focuses":[]},{"key":"stealth","rank":1,"focuses":[]},{"key":"survival","rank":1,"focuses":[]},{"key":"tactics","rank":1,"focuses":[]},{"key":"vehicles","rank":1,"focuses":[]}],"stress":6,"injuries":1,"armour":2,"courage":2,"attacks":[{"name":"Gewehr 41 / Karabiner 43","focus":"Fusils","range":"medium","damage":5,"salvo":"Vicieux","qualities":"Fiable","escalation":false},{"name":"Baïonnette","focus":"Armes de mêlée","range":"contact","damage":4,"salvo":null,"qualities":"Perforant","escalation":false},{"name":"Maschinengewehr 42 (MG 42)","focus":"Fusils","range":"medium","damage":6,"salvo":"Zone","qualities":"Escalade, Lourd, Imprécis","escalation":true},{"name":"Stielhandgranate 24","focus":"Lancer","range":"close","damage":5,"salvo":null,"qualities":"Zone, Étourdissant, Munition","escalation":true},{"name":"Panzerfaust 60","focus":"Armes lourdes","range":"long","damage":5,"salvo":null,"qualities":"Perforant 1, Vicieux, Encombrant, Escalade, Tueur de géants, Lourd, Imprécis, Munition","escalation":true}],"abilities":[],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Fantassin allemand' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Officier d''infanterie allemand', 'Officier d''infanterie de la Heer', 'Du Leutnant à l''Oberst, les officiers d''infanterie allemands sont des meneurs d''hommes très entraînés, organisés et inspirants. Encouragés à se montrer agressifs, ils jouissent d''une grande liberté et d''une grande souplesse pour atteindre leurs objectifs tactiques. (VO : Infantry Officer)', '["Troupe","Axe"]', 'Gamemaster Guide', 182, '{"rank":"trooper","truths":["Chef d''infanterie expérimenté"],"attributes":{"agility":7,"brawn":8,"coordination":8,"insight":8,"reason":9,"will":8},"skills":[{"key":"academia","rank":1,"focuses":[]},{"key":"athletics","rank":2,"focuses":[]},{"key":"fighting","rank":2,"focuses":["Armes de poing"]},{"key":"resilience","rank":2,"focuses":[]},{"key":"stealth","rank":1,"focuses":[]},{"key":"survival","rank":1,"focuses":[]},{"key":"tactics","rank":1,"focuses":["Commandement"]}],"stress":5,"injuries":1,"armour":1,"courage":2,"attacks":[{"name":"Luger Pistol","focus":"Armes de poing","range":"close","damage":4,"salvo":"Vicieux","qualities":"Combat rapproché","escalation":false}],"abilities":[],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Officier d''infanterie allemand' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Panzergrenadier', 'Infanterie motorisée ou mécanisée allemande', 'Appelés à l''origine Schützen ou Kavallerieschützen, les Panzergrenadiere sont l''infanterie motorisée ou mécanisée de l''armée allemande, généralement issue de l''infanterie régulière promue au fil de la guerre. Conçus pour opérer avec les formations blindées rapides, ils sont transportés en camions ou en semi-chenillés Sd.Kfz 251/1 et sont plus expérimentés que les unités régulières.', '["Lieutenant","Axe"]', 'Gamemaster Guide', 182, '{"rank":"lieutenant","truths":["Fantassin d''élite"],"attributes":{"agility":8,"brawn":9,"coordination":9,"insight":7,"reason":8,"will":9},"skills":[{"key":"athletics","rank":2,"focuses":[]},{"key":"engineering","rank":2,"focuses":[]},{"key":"fighting","rank":3,"focuses":["Fusils"]},{"key":"medicine","rank":1,"focuses":[]},{"key":"resilience","rank":2,"focuses":[]},{"key":"stealth","rank":1,"focuses":[]},{"key":"survival","rank":2,"focuses":[]},{"key":"tactics","rank":2,"focuses":["Tactique de terrain"]},{"key":"vehicles","rank":2,"focuses":[]}],"stress":11,"injuries":2,"armour":2,"courage":3,"attacks":[{"name":"Gewehr/Karabiner 43 (G/K43)","focus":"Fusils","range":"medium","damage":5,"salvo":"Vicieux","qualities":"Fiable","escalation":false},{"name":"Baïonnette","focus":"Armes de mêlée","range":"contact","damage":4,"salvo":null,"qualities":"Perforant 1","escalation":false},{"name":"Maschinengewehr 42 (MG 42)","focus":"Fusils","range":"medium","damage":6,"salvo":"Zone","qualities":"Escalade, Lourd, Imprécis","escalation":true},{"name":"Stielhandgranate 24","focus":"Lancer","range":"close","damage":5,"salvo":null,"qualities":"Zone, Étourdissant, Munition","escalation":true}],"abilities":[],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Panzergrenadier' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Fallschirmjäger', 'Parachutiste d''élite allemand', 'Créés peu avant la guerre, les Fallschirmjäger (« chasseurs parachutistes ») sont l''infanterie parachutiste d''élite de l''Allemagne : endoctrinés, intrépides et féroces, des troupes de choc dont le modèle a été copié par les Britanniques et les Américains. Malgré de lourdes pertes, ils atteignent presque toujours leurs objectifs ; armés d''abord du Karabiner 98k ou de la MP38/40, puis du StG 44, ils alignent aussi leurs propres sapeurs d''assaut équipés de lance-flammes et de charges.', '["Lieutenant","Axe"]', 'Gamemaster Guide', 182, '{"rank":"lieutenant","truths":["Troupes parachutistes d''élite"],"attributes":{"agility":9,"brawn":10,"coordination":8,"insight":8,"reason":7,"will":9},"skills":[{"key":"athletics","rank":3,"focuses":[]},{"key":"fighting","rank":3,"focuses":["Fusils","Armes de mêlée"]},{"key":"medicine","rank":1,"focuses":[]},{"key":"observation","rank":1,"focuses":[]},{"key":"resilience","rank":3,"focuses":[]},{"key":"stealth","rank":1,"focuses":[]},{"key":"survival","rank":2,"focuses":[]},{"key":"tactics","rank":2,"focuses":[]},{"key":"vehicles","rank":1,"focuses":[]}],"stress":13,"injuries":2,"armour":3,"courage":4,"attacks":[{"name":"Maschinenpistole 40 (MP 40)","focus":"Corps à corps","range":"close","damage":4,"salvo":"Étourdissant","qualities":"Imprécis","escalation":false},{"name":"Sturmgewehr 44 (StG 44)","focus":"Fusils","range":"medium","damage":5,"salvo":"Étourdissant","qualities":"Peu fiable","escalation":false},{"name":"Baïonnette","focus":"Armes de mêlée","range":"contact","damage":5,"salvo":null,"qualities":"Perforant 1","escalation":false},{"name":"Maschinengewehr 42 (MG 42)","focus":"Fusils","range":"medium","damage":6,"salvo":"Zone","qualities":"Escalade, Lourd, Imprécis","escalation":true},{"name":"Flammenwerfer 41 (FmW 41)","focus":"Armes lourdes","range":"medium","damage":5,"salvo":"Zone","qualities":"Persistant 4, Débilitant, Escalade","escalation":true}],"abilities":[{"name":"Aéroporté","text":"Les Fallschirmjäger sont entraînés au saut en parachute. Appelés en renfort, ils peuvent arriver par les airs depuis un avion de transport ; toute attaque à distance contre eux avant qu''ils n''atterrissent, au début de leur premier tour, subit +1 difficulté."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Fallschirmjäger' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Brandebourgeois', 'Commando allemand d''élite', 'Les Brandenburger sont les commandos allemands, conçus pour opérer en petites unités derrière les lignes ennemies et désorganiser le commandement adverse. Spécialistes de l''infiltration et du sabotage, organisés par région et par langue, ils se font passer pour des soldats américains pendant l''offensive des Ardennes. Victimes des luttes internes nazies, ceux qui ne rejoignent pas les Nachtwölfe passent au SD et finissent pratiquement anéantis lors de la retraite d''URSS. (VO : Brandenburger)', '["Lieutenant","Axe"]', 'Gamemaster Guide', 183, '{"rank":"lieutenant","truths":["Commando allemand d''élite"],"attributes":{"agility":9,"brawn":8,"coordination":9,"insight":9,"reason":8,"will":9},"skills":[{"key":"athletics","rank":2,"focuses":[]},{"key":"fighting","rank":3,"focuses":["Corps à corps","Fusils"]},{"key":"observation","rank":2,"focuses":[]},{"key":"resilience","rank":2,"focuses":[]},{"key":"stealth","rank":3,"focuses":["Discrétion rurale","Discrétion urbaine"]},{"key":"survival","rank":2,"focuses":[]},{"key":"tactics","rank":2,"focuses":[]},{"key":"vehicles","rank":1,"focuses":[]}],"stress":13,"injuries":2,"armour":1,"courage":3,"attacks":[{"name":"Maschinenpistole 40 (MP 40)","focus":"Corps à corps","range":"close","damage":5,"salvo":"Étourdissant","qualities":"Imprécis","escalation":false},{"name":"Sturmgewehr 44 (StG 44)","focus":"Fusils","range":"medium","damage":6,"salvo":"Étourdissant","qualities":"Peu fiable","escalation":false},{"name":"Baïonnette","focus":"Armes de mêlée","range":"contact","damage":3,"salvo":null,"qualities":"Perforant 1","escalation":false},{"name":"Maschinengewehr 42 (MG 42)","focus":"Fusils","range":"medium","damage":6,"salvo":"Zone","qualities":"Escalade, Lourd, Imprécis","escalation":true}],"abilities":[{"name":"Commandos","text":"Les commandos sont des maîtres du meurtre silencieux et du sabotage. Lorsqu''il attaque en étant caché, le commando est toujours considéré comme ayant un focus applicable."},{"name":"Bonne chance !","text":"Les Brandebourgeois sont des maîtres du déguisement. Lorsqu''ils tentent de se faire passer pour des soldats alliés, tout test pour déceler la supercherie voit sa difficulté augmenter de +1."},{"name":"Sabotage","text":"Experts du sabotage, les commandos peuvent utiliser leur compétence Combat à la place d''Ingénierie pour ce genre d''activité."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Brandebourgeois' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Waffen-SS', 'Soldat politique fanatique', 'Branche armée de la SS, la Waffen-SS combat aux côtés de la Heer tout en ne répondant qu''à la direction politique du parti nazi. Fanatiques dans leurs convictions et responsables de certains des pires crimes de guerre, ses soldats impitoyables et disciplinés reçoivent le meilleur entraînement, le meilleur équipement et les meilleurs véhicules, et sont engagés comme troupes de choc. Ce profil représente le soldat SS moyen.', '["Lieutenant","Axe"]', 'Gamemaster Guide', 184, '{"rank":"lieutenant","truths":["Soldat politique fanatique"],"attributes":{"agility":8,"brawn":9,"coordination":9,"insight":8,"reason":8,"will":9},"skills":[{"key":"athletics","rank":2,"focuses":[]},{"key":"engineering","rank":2,"focuses":[]},{"key":"fighting","rank":3,"focuses":["Fusils"]},{"key":"medicine","rank":1,"focuses":[]},{"key":"resilience","rank":2,"focuses":[]},{"key":"stealth","rank":1,"focuses":[]},{"key":"survival","rank":2,"focuses":[]},{"key":"tactics","rank":2,"focuses":["Tactique de terrain"]},{"key":"vehicles","rank":2,"focuses":[]}],"stress":11,"injuries":2,"armour":2,"courage":4,"attacks":[{"name":"Maschinenpistole 40 (MP 40)","focus":"Corps à corps","range":"close","damage":4,"salvo":"Étourdissant","qualities":"Imprécis","escalation":false},{"name":"Sturmgewehr 44 (StG 44)","focus":"Fusils","range":"medium","damage":5,"salvo":"Étourdissant","qualities":"Peu fiable","escalation":false},{"name":"Baïonnette","focus":"Armes de mêlée","range":"contact","damage":4,"salvo":null,"qualities":"Perforant 1","escalation":false}],"abilities":[{"name":"Fanatique","text":"Les fanatiques gagnent +1 en Courage (inclus ci-dessus) et +X Moral, X étant le nombre de fanatiques de leur camp présents dans la scène (maximum +5 Moral)."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Waffen-SS' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Einsatzgruppen', 'Escadron de la mort SS', 'Les Einsatzgruppen sont la manifestation la plus abjecte du régime nazi : créés en 1938 par Reinhard Heydrich, ces escadrons de la mort suivent les troupes en territoire occupé pour assassiner tous ceux que le régime tient pour ennemis. Encore plus fanatiques que la Waffen-SS, ils multiplient les atrocités ; le Soleil Noir les emploie volontiers en défense comme en attaque. Leurs statistiques sont celles des fantassins réguliers, avec le fanatisme en plus.', '["Troupe","Axe"]', 'Gamemaster Guide', 184, '{"rank":"trooper","truths":["Fanatiques meurtriers"],"attributes":{"agility":8,"brawn":9,"coordination":8,"insight":8,"reason":8,"will":7},"skills":[{"key":"athletics","rank":2,"focuses":[]},{"key":"fighting","rank":2,"focuses":["Fusils"]},{"key":"resilience","rank":2,"focuses":[]},{"key":"stealth","rank":1,"focuses":[]},{"key":"survival","rank":1,"focuses":[]},{"key":"tactics","rank":1,"focuses":[]},{"key":"vehicles","rank":1,"focuses":[]}],"stress":6,"injuries":1,"armour":2,"courage":3,"attacks":[{"name":"Gewehr/Karabiner 43 (G/K43)","focus":"Fusils","range":"medium","damage":5,"salvo":"Vicieux","qualities":"Fiable","escalation":false},{"name":"Baïonnette","focus":"Armes de mêlée","range":"contact","damage":4,"salvo":null,"qualities":"Perforant 1","escalation":false},{"name":"Maschinengewehr 42 (MG 42)","focus":"Fusils","range":"medium","damage":6,"salvo":"Zone","qualities":"Escalade, Lourd, Imprécis","escalation":true},{"name":"Stielhandgranate 24","focus":"Lancer","range":"close","damage":6,"salvo":null,"qualities":"Zone, Étourdissant, Munition","escalation":true}],"abilities":[{"name":"Fanatique","text":"Les fanatiques gagnent +1 en Courage (inclus ci-dessus) et +X Moral, X étant le nombre de fanatiques de leur camp présents dans la scène (maximum +5 Moral)."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Einsatzgruppen' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'SS-Sonderkommando', 'Officier conseiller d''un groupe de combat SS temporaire', 'Les SS-Sonderkommandos sont des groupes de combat temporaires formés à partir d''unités SS pour remplir des objectifs précis, renforcés par la Waffen-SS sur le terrain et dotés de toutes les ressources nécessaires. Le Soleil Noir et les Nachtwölfe en font grand usage, comme le Sonderkommando H (« Hexen »), chargé officiellement d''étudier la persécution des sorcières et en réalité leurs rituels ; là où ils apparaissent, le Mythe n''est jamais loin, et ceux qui conseillent le Soleil Noir ou les Nachtwölfe sont d''une redoutable compétence. (VO : SS Sonderkommando)', '["Némésis","Axe"]', 'Gamemaster Guide', 185, '{"rank":"nemesis","truths":["Fanatique dangereusement intelligent"],"attributes":{"agility":9,"brawn":9,"coordination":9,"insight":8,"reason":10,"will":9},"skills":[{"key":"academia","rank":2,"focuses":[]},{"key":"athletics","rank":2,"focuses":[]},{"key":"fighting","rank":2,"focuses":["Armes de poing","Fusils"]},{"key":"medicine","rank":1,"focuses":[]},{"key":"observation","rank":1,"focuses":[]},{"key":"persuasion","rank":3,"focuses":[]},{"key":"resilience","rank":2,"focuses":[]},{"key":"stealth","rank":2,"focuses":[]},{"key":"survival","rank":2,"focuses":[]},{"key":"tactics","rank":3,"focuses":["Commandement","Opérations clandestines"]}],"stress":11,"injuries":3,"armour":2,"courage":4,"attacks":[{"name":"Sturmgewehr 44 (StG 44)","focus":"Fusils","range":"medium","damage":5,"salvo":"Étourdissant","qualities":"Peu fiable","escalation":false},{"name":"Luger Pistol","focus":"Armes de poing","range":"close","damage":4,"salvo":"Vicieux","qualities":"Combat rapproché","escalation":false}],"abilities":[{"name":"Commandos","text":"Les Sonderkommandos sont des maîtres du meurtre silencieux et du sabotage. Lorsqu''il attaque en étant caché, le Sonderkommando est toujours considéré comme ayant un focus applicable pour l''arme qu''il utilise."},{"name":"Conseil mortel","text":"Les officiers Sonderkommando parlent doucement mais portent une grosse arme. Lorsqu''un officier conseille et soutient une unité de troupiers du Soleil Noir, ces troupiers comptent comme des PNJ Lieutenants dotés de la règle Commandos. Lorsqu''il mène d''autres PNJ militaires allemands, ceux-ci gagnent les règles Commandos et Fanatique."},{"name":"Fanatique","text":"Les fanatiques gagnent +1 en Courage (inclus ci-dessus) et +X Moral, X étant le nombre de fanatiques de leur camp présents dans la scène (maximum +5 Moral)."},{"name":"Sabotage","text":"Experts du sabotage, les Sonderkommandos peuvent utiliser leur compétence Combat à la place d''Ingénierie pour ce genre d''activité."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'SS-Sonderkommando' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Troupier du Soleil Noir', 'Fantassin fanatique du Soleil Noir', 'Soldats triés dans la SS et d''autres unités d''élite, ils sont le poing blindé des forces du Soleil Noir. Sans être adeptes, un entraînement intensif et un lavage de cerveau les rendent insensibles aux horreurs captives invoquées par les Maîtres et les Chanoines. Le brassard du Soleil Noir qu''ils portent au bras gauche contient un charme semblable au Totenkopfring, qui les désigne comme alliés et les protège des créatures invoquées. (VO : Black Sun Trooper)', '["Troupe","Axe"]', 'Gamemaster Guide', 186, '{"rank":"trooper","truths":["Infanterie fanatique"],"attributes":{"agility":8,"brawn":10,"coordination":8,"insight":6,"reason":7,"will":9},"skills":[{"key":"athletics","rank":1,"focuses":[]},{"key":"fighting","rank":3,"focuses":["Fusils"]},{"key":"resilience","rank":2,"focuses":["Discipline"]},{"key":"survival","rank":2,"focuses":[]},{"key":"tactics","rank":1,"focuses":[]},{"key":"vehicles","rank":1,"focuses":[]}],"stress":6,"injuries":1,"armour":2,"courage":3,"attacks":[{"name":"Sturmgewehr 44 (StG 44)","focus":"Fusils","range":"medium","damage":5,"salvo":"Étourdissant","qualities":"Peu fiable (premiers modèles expérimentaux à partir de 1942 ; avant, plutôt des MP40)","escalation":false},{"name":"Luger Pistol","focus":"Armes de poing","range":"close","damage":4,"salvo":"Vicieux","qualities":"Combat rapproché","escalation":false},{"name":"Flammenwerfer 41 (FmW 41)","focus":"Armes lourdes","range":"medium","damage":5,"salvo":"Zone","qualities":"Persistant 4, Escalade, Débilitant","escalation":true},{"name":"Maschinengewehr 42 (MG 42)","focus":"Fusils","range":"medium","damage":6,"salvo":"Zone","qualities":"Escalade, Imprécis","escalation":true}],"abilities":[{"name":"Fanatique","text":"Les fanatiques gagnent +1 en Courage (inclus ci-dessus) et +X Moral, X étant le nombre de fanatiques de leur camp présents dans la scène (maximum +5 Moral)."},{"name":"Brassard Schwarzsonne","text":"Désigne le porteur comme un allié aux yeux des créatures invoquées par le Soleil Noir."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Troupier du Soleil Noir' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Dompteur de démons du Soleil Noir (Dämonenbändiger)', 'Maître-chien d''une horreur liée', 'Si la plupart des horreurs captives du Soleil Noir sont invoquées sur le champ de bataille, certaines sont liées durablement et confiées à des maîtres spécialisés qui les emploient comme troupes de choc, pisteurs ou gardes. Le plus courant est le dompteur lié à un Teufelshund par une puissante sorcellerie noire ; d''autres peuvent être liés à un Élu, voire à des créatures plus exotiques du Mythe (Froids, maigres bêtes de la nuit, Halja). (VO : Black Sun Demon Tamer: Dämonenbändiger)', '["Lieutenant","Axe"]', 'Gamemaster Guide', 186, '{"rank":"lieutenant","truths":["Maître de créature","Lié à une horreur"],"attributes":{"agility":8,"brawn":9,"coordination":8,"insight":8,"reason":9,"will":10},"skills":[{"key":"academia","rank":3,"focuses":["Occultisme"]},{"key":"athletics","rank":2,"focuses":[]},{"key":"fighting","rank":2,"focuses":["Corps à corps"]},{"key":"medicine","rank":1,"focuses":[]},{"key":"resilience","rank":3,"focuses":[]},{"key":"stealth","rank":1,"focuses":[]},{"key":"survival","rank":2,"focuses":[]},{"key":"tactics","rank":2,"focuses":["Tactique de terrain"]},{"key":"vehicles","rank":1,"focuses":[]}],"stress":13,"injuries":2,"armour":2,"courage":6,"attacks":[{"name":"Luger Pistol","focus":"Armes de poing","range":"close","damage":4,"salvo":"Vicieux","qualities":"Combat rapproché","escalation":false}],"abilities":[{"name":"Allié démoniaque","text":"Le dompteur a une créature, comme un Teufelshund, liée à lui par de puissants sorts lors de rituels célébrés dans les profondeurs du château de Wewelsburg. Elle obéit sans discussion, mais le dompteur doit se concentrer pour la diriger : chaque nouvel ordre lui coûte une action majeure. Le lien est tel que chaque fois que la créature subit une blessure, le dompteur subit 5 de stress mental avec l''effet Perforant 2."},{"name":"Fanatique","text":"Les fanatiques gagnent +1 en Courage (inclus ci-dessus) et +X Moral, X étant le nombre de fanatiques de leur camp présents dans la scène (maximum +5 Moral)."},{"name":"Brassard Schwarzsonne","text":"Désigne le porteur comme un allié aux yeux des créatures invoquées par le Soleil Noir."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Dompteur de démons du Soleil Noir (Dämonenbändiger)' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Novice du Soleil Noir', 'Chercheur et initié du Soleil Noir', 'Les Novices sont les fantassins du Soleil Noir : chercheurs, enquêteurs et analystes sur le terrain comme à Wewelsburg, tenus à l''écart de la vraie nature du culte jusqu''à leur initiation. Souvent détachés auprès d''autres services nazis, notamment l''Ahnenerbe, ils ne sont généralement pas formés au combat et comptent sur la SS ; quelques-uns pratiquent la sorcellerie (au sein du Hexenzirkel), mais la plupart sont des spécialistes universitaires ou scientifiques. (VO : Black Sun Novice)', '["Troupe","Axe"]', 'Gamemaster Guide', 187, '{"rank":"trooper","truths":["Initié du Soleil Noir","Universitaire dévoyé"],"attributes":{"agility":8,"brawn":7,"coordination":8,"insight":8,"reason":9,"will":8},"skills":[{"key":"academia","rank":2,"focuses":["Occultisme"]},{"key":"athletics","rank":2,"focuses":[]},{"key":"fighting","rank":1,"focuses":["Corps à corps"]},{"key":"medicine","rank":1,"focuses":[]},{"key":"resilience","rank":2,"focuses":[]},{"key":"stealth","rank":1,"focuses":[]},{"key":"vehicles","rank":1,"focuses":[]}],"stress":5,"injuries":1,"armour":1,"courage":5,"attacks":[{"name":"Luger Pistol","focus":"Armes de poing","range":"close","damage":4,"salvo":"Vicieux","qualities":"Combat rapproché","escalation":false}],"abilities":[{"name":"Pouvoir","text":"Pouvoir : 1."},{"name":"Fanatique","text":"Les fanatiques gagnent +1 en Courage (inclus ci-dessus) et +X Moral, X étant le nombre de fanatiques de leur camp présents dans la scène (maximum +5 Moral)."},{"name":"Néophyte occulte","text":"Les Novices n''ont pas encore éveillé tout leur potentiel magique. Bien qu''ils aient un Pouvoir de 1, ils ne lancent pas de sorts eux-mêmes : leur Pouvoir ne sert qu''à aider d''autres personnages à accomplir des rituels."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Novice du Soleil Noir' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Maître du Soleil Noir', 'Commandant de terrain et sorcier du Soleil Noir', 'Les Maîtres sont les principaux agents de terrain du Soleil Noir, chargés de commander les Novices dans leur quête des trésors occultes de la Terre. Ils opèrent sous couvert de la SS, seul leur insigne du Soleil Noir les distinguant en uniforme, et mènent aussi des opérations clandestines derrière les lignes ennemies ; moins puissants que les Chanoines en sorcellerie, ils ne doivent jamais être sous-estimés. (VO : Black Sun Master)', '["Lieutenant","Axe"]', 'Gamemaster Guide', 187, '{"rank":"lieutenant","truths":["Commandant sur le champ de bataille","Universitaire dévoyé"],"attributes":{"agility":8,"brawn":8,"coordination":8,"insight":8,"reason":10,"will":9},"skills":[{"key":"academia","rank":3,"focuses":["Occultisme"]},{"key":"athletics","rank":1,"focuses":[]},{"key":"engineering","rank":1,"focuses":[]},{"key":"fighting","rank":2,"focuses":["Corps à corps"]},{"key":"medicine","rank":1,"focuses":[]},{"key":"resilience","rank":2,"focuses":[]},{"key":"stealth","rank":1,"focuses":[]},{"key":"survival","rank":2,"focuses":[]},{"key":"tactics","rank":2,"focuses":["Tactique de terrain"]},{"key":"vehicles","rank":2,"focuses":[]}],"stress":11,"injuries":2,"armour":1,"courage":4,"attacks":[{"name":"Degen du Soleil Noir","focus":"Armes de mêlée","range":"contact","damage":4,"salvo":null,"qualities":"Perforant 1, Faim, Fléau, Parade","escalation":false},{"name":"Walther P Series (P38)","focus":"Armes de poing","range":"close","damage":3,"salvo":"Vicieux","qualities":"Combat rapproché, Caché, Fiable","escalation":false}],"abilities":[{"name":"Pouvoir","text":"Pouvoir : 3."},{"name":"Fanatique","text":"Les fanatiques gagnent +1 en Courage (inclus ci-dessus) et +X Moral, X étant le nombre de fanatiques de leur camp présents dans la scène (maximum +5 Moral)."},{"name":"Sorts et rituels","text":"Le Maître a entamé sa descente sur une sombre voie occulte : il lance ses sorts avec le Raisonnement et connaît trois sorts du grimoire de Nyarlathotep, en général ceux ci-dessous (cela peut varier)."},{"name":"Masque du Sphinx sans visage","text":"Raisonnement + Discrétion, difficulté 2, coût 4 Drain. Pendant 4 rounds, les alliés à portée Courte augmentent de +1 la difficulté des attaques à distance qui les visent et gagnent +2 Couvert."},{"name":"Rayons du Soleil Noir","text":"Raisonnement + Combat, difficulté 3, coût 5 Drain, Perforant 1. Le Maître vise un seul ennemi à portée Moyenne par une attaque à distance qui inflige 6 de stress mental avec les effets Perforant 1 et Piège."},{"name":"Les Brumes sans nom","text":"Raisonnement + Résilience, difficulté 2, coût 5 Drain et +1 Menace par effet. Le sort fait naître dans la zone une brume immonde qui dure 4 rounds : tout ennemi dans la brume à la fin de son tour subit 5 de stress mental, Perforant 2, Étourdissant. La zone gagne la vérité « Brumes immondes mouvantes »."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Maître du Soleil Noir' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Chanoine du Soleil Noir', 'Mage de bataille du cercle intérieur du Soleil Noir', 'Reconnaissables à leurs masques de soie noire, les Chanoines sont la principale force magique du Soleil Noir sur le champ de bataille, usant des arts noirs pour infliger d''effroyables dégâts. Seuls les Maîtres les plus zélés et impitoyables rejoignent leurs rangs, où ils apprennent à semer douleur, mort et terreur par la magie ; sur le terrain, des troupes de combat les protègent pendant qu''ils invoquent leurs enchantements immondes. (VO : Black Sun Canon)', '["Lieutenant","Axe"]', 'Gamemaster Guide', 188, '{"rank":"lieutenant","truths":["Initié du cercle intérieur","Par-delà le bien et le mal"],"attributes":{"agility":7,"brawn":7,"coordination":8,"insight":9,"reason":11,"will":9},"skills":[{"key":"academia","rank":4,"focuses":["Occultisme"]},{"key":"athletics","rank":1,"focuses":[]},{"key":"fighting","rank":2,"focuses":["Corps à corps"]},{"key":"medicine","rank":2,"focuses":[]},{"key":"resilience","rank":3,"focuses":["Discipline"]},{"key":"survival","rank":1,"focuses":[]},{"key":"stealth","rank":1,"focuses":[]},{"key":"tactics","rank":3,"focuses":["Tactique de terrain"]}],"stress":12,"injuries":2,"armour":1,"courage":5,"attacks":[{"name":"Degen du Soleil Noir","focus":"Armes de mêlée","range":"contact","damage":4,"salvo":null,"qualities":"Perforant 1, Faim, Fléau, Parade","escalation":false},{"name":"Walther P Series (P38)","focus":"Armes de poing","range":"close","damage":4,"salvo":"Vicieux","qualities":"Combat rapproché, Caché, Fiable","escalation":false}],"abilities":[{"name":"Pouvoir","text":"Pouvoir : 4."},{"name":"Fanatique","text":"Les fanatiques gagnent +1 en Courage (inclus ci-dessus) et +X Moral, X étant le nombre de fanatiques de leur camp présents dans la scène (maximum +5 Moral)."},{"name":"Sorts et rituels","text":"Le Chanoine suit une sombre voie occulte : il lance ses sorts avec le Raisonnement et connaît quatre sorts du grimoire de Nyarlathotep, en général ceux ci-dessous (cela peut varier)."},{"name":"Naissance des Suzerains","text":"Raisonnement + Persuasion, difficulté 1 + nombre de suzerains, coût 5 Drain, Perforant 2. Le Chanoine invoque 1 à 3 Suzerains serviteurs jusqu''à la fin de la scène."},{"name":"Masque du Sphinx sans visage","text":"Raisonnement + Discrétion, difficulté 2, coût 4 Drain. Pendant 4 rounds, les alliés à portée Courte augmentent de +1 la difficulté des attaques à distance qui les visent et gagnent 2 Couvert."},{"name":"Rayons du Soleil Noir","text":"Raisonnement + Combat, difficulté 3, coût 5 Drain, Perforant 1. Le Chanoine vise un seul ennemi à portée Moyenne par une attaque à distance qui inflige 6 de stress mental avec les effets Perforant 1 et Piège."},{"name":"Les Brumes sans nom","text":"Raisonnement + Résilience, difficulté 2, coût 5 Drain. Le sort fait naître dans la zone une brume immonde qui dure 4 rounds : tout ennemi dans la brume à la fin de son tour subit 5 de stress mental, Perforant 2, Étourdissant. La zone gagne la vérité « Brumes immondes mouvantes »."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Chanoine du Soleil Noir' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Rêveuse Norne du Soleil Noir', 'Rêveur télépathe du Soleil Noir', 'Recrutées dans les sanatoriums et asiles du Reich, les Nornes possèdent des dons de rêve hors du commun ; d''abord lancées contre l''esprit endormi des commandants ennemis, elles sont cantonnées à la défense et au contre-espionnage après la déroute infligée par la Fraternité de la Lumière intérieure en 1940. Elles servent aussi à consolider Wewelsburg II, au prix de leur santé mentale ; majoritairement des femmes, la plupart présentent troubles et névroses, et l''Exarque serait toujours accompagné de deux d''entre elles. (VO : Black Sun Norn Dreamer)', '["Lieutenant","Axe"]', 'Gamemaster Guide', 189, '{"rank":"lieutenant","truths":["Initiée du Soleil Noir","Rêveuse","Internée"],"attributes":{"agility":7,"brawn":8,"coordination":7,"insight":10,"reason":9,"will":10},"skills":[{"key":"academia","rank":2,"focuses":["Occultisme"]},{"key":"athletics","rank":1,"focuses":[]},{"key":"engineering","rank":1,"focuses":[]},{"key":"fighting","rank":2,"focuses":["Armes de mêlée"]},{"key":"medicine","rank":2,"focuses":[]},{"key":"observation","rank":2,"focuses":[]},{"key":"persuasion","rank":2,"focuses":[]},{"key":"resilience","rank":2,"focuses":[]},{"key":"stealth","rank":0,"focuses":[]},{"key":"survival","rank":1,"focuses":[]},{"key":"tactics","rank":1,"focuses":[]},{"key":"vehicles","rank":1,"focuses":[]}],"stress":12,"injuries":2,"armour":1,"courage":5,"attacks":[{"name":"Luger Pistol","focus":"Armes de poing","range":"close","damage":6,"salvo":null,"qualities":"Combat rapproché","escalation":false},{"name":"Lance d''acier noir","focus":"Armes de mêlée","range":"contact","damage":4,"salvo":null,"qualities":"Perforant 1, Faim, Fléau","escalation":false}],"abilities":[{"name":"Rêveuse","text":"Les Rêveurs sont extrêmement puissants dans les Contrées du Rêve et peuvent y substituer leur Volonté à l''Agilité, la Force ou la Coordination."},{"name":"Magie latente","text":"Sans lancer de sorts elles-mêmes, les Nornes ont un Pouvoir de 3 qu''elles peuvent utiliser pour aider un autre lanceur de sorts à accomplir un rituel. Une Norne qui aide à un rituel génère automatiquement 1 succès au lieu de lancer les dés, et apporte la totalité de ses 3 points de Pouvoir au lanceur principal au lieu de la moitié."},{"name":"Sens télépathiques","text":"Une Norne peut dépenser 1 Menace lors d''un test Perception + Observation pour repérer des personnages hostiles, des pièges ou des menaces semblables ; la difficulté du test est alors réduite de 2 (minimum 0)."}],"threatSpends":[{"name":"Sens télépathiques","cost":"1","text":"Test Perception + Observation pour repérer hostiles, pièges ou menaces : difficulté −2 (minimum 0)."}]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Rêveuse Norne du Soleil Noir' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Die Auserwählten, les Élus (mineurs et majeurs)', 'Mutant difforme gardien des lieux secrets du Soleil Noir', 'Lors de leur élévation au rang de Maître, les initiés se tiennent devant le soleil noir et se laissent baigner par sa lumière ; certains en ressortent l''âme à jamais tordue, réduits à des masses de chair hurlante ou, pour d''autres, changés en Élus : des parodies d''humanité aux membres et tentacules surnuméraires. D''abord gardiens des lieux les plus secrets, surtout Wewelsburg II, ils sont lâchés comme troupes de choc contre les Soviétiques, puis dans les rues de Berlin en avril 1945 ; certains n''ont plus qu''une intelligence animale, d''autres pensent encore et manient des armes. (VO : Lesser and Greater Die Auserwählten: The Chosen)', '["Troupe","Axe"]', 'Gamemaster Guide', 190, '{"rank":"trooper","truths":["Mutant hideux","Raison en lambeaux"],"attributes":{"agility":9,"brawn":10,"coordination":9,"insight":6,"reason":5,"will":9},"skills":[{"key":"athletics","rank":2,"focuses":[]},{"key":"fighting","rank":2,"focuses":["Main nue"]},{"key":"observation","rank":1,"focuses":[]},{"key":"resilience","rank":5,"focuses":[]},{"key":"stealth","rank":1,"focuses":[]},{"key":"survival","rank":2,"focuses":[]},{"key":"tactics","rank":1,"focuses":[]},{"key":"vehicles","rank":1,"focuses":[]}],"stress":8,"injuries":2,"armour":5,"courage":6,"attacks":[{"name":"Poings matraqueurs, tentacules cinglants et griffes lacérantes","focus":"Main nue","range":"contact","damage":5,"salvo":null,"qualities":"Voir « Mutilé par les mutants »","escalation":false}],"abilities":[{"name":"Immunisé au froid, à la maladie, à la peur et à la douleur","text":"Die Auserwählten sont immunisés au stress, aux complications et aux vérités qui représentent l''une de ces conditions."},{"name":"Mutilé par les mutants","text":"Lors d''une attaque de mêlée d''un Élu, le MJ peut ajouter l''un des effets suivants : Perforant 1, Piège ou Étourdissant."},{"name":"Coriace 1","text":"Un Élu supporte une blessure de plus que la plupart des PNJ Troupiers (inclus ci-dessus). De plus, chaque fois qu''il subit une blessure, le MJ peut dépenser 3 Menace pour l''ignorer."},{"name":"Élu majeur","text":"Chaque Élu est une créature unique bénie par Yog-Sothoth, mais certains reçoivent de plus grandes bénédictions. Quand un ou plusieurs Élus apparaissent pour la première fois dans une scène, le MJ peut dépenser 1 Menace pour changer l''un d''eux en Élu majeur, qui devient un PNJ Lieutenant (Stress maximum 15, Blessures maximum 3, Coriace 1 compris). Les Élus majeurs présentent souvent des mutations plus bizarres : le MJ peut tirer ou choisir des mutations supplémentaires dans la table (1 Menace par mutation, pas deux fois la même)."},{"name":"Mutations aléatoires (d20)","text":"1-2 Carrure massive : Force extraordinaire 1 (1 succès automatique aux tests de Force, +1 dégât en mêlée, +1 Stress maximum et +1 Armure) et Échelle 1 (il faut 6 stress après réduction pour lui infliger une blessure). 3-4 Vitesse surprenante : Agilité extraordinaire 1 et Rapidité mortelle (+1 difficulté aux attaques à distance contre lui ; si une telle attaque le rate, il peut dépenser 1 Menace pour une action mineure de mouvement). 5-6 Ruse tordue : Perception et Raisonnement passent à 8, gagne le focus Corps à corps et peut utiliser des armes à distance (souvent une MP40 : Corps à corps, portée Courte, 4, salve Étourdissant, Imprécis) ; Se nourrir de la peur (chaque fois qu''un personnage à portée Moyenne subit une blessure mentale, générez 2 Menace). 7-8 Monstrueux et terrifiant : Effroyable 1 (attaque mentale de 4 stress mental Perforant 1 ; la première fois qu''un PJ le voit, test Volonté + Résilience de difficulté 1 ou il subit cette attaque). 9-10 Forme malléable : peut dépenser 1 Menace en se déplaçant pour passer par des interstices étroits ; Récupération rapide 2 (retire 2 stress à la fin de chacun de ses tours ; s''il est blessé au début de son tour, peut dépenser 2 Menace pour retirer une blessure ; cesse quand il est vaincu). 11-12 Brute décérébrée : Brutal 1 (peut toujours utiliser la Force pour attaquer ou se défendre en mêlée, +1 stress en mêlée) et Décérébré (attaque l''ennemi le plus proche sauf ordre, aucune réaction, aucun stress ni blessure mentale, insensible à la raison). 13-14 Bouche sans visage : aveugle mais perçoit assez pour se déplacer ; difficulté −2 pour entendre ou sentir, perçoit ce que les humains ne peuvent pas. 15-16 Chair hideuse : remplace Coriace 1 par Coriace 2 (5 blessures) et +3 Armure. 17-18 Pas lourd et traînant : ne peut pas faire l''action majeure Charge mais ne peut pas être renversé ; ignore la qualité Lourd des armes qu''il manie. 19-20 Source de folie : toutes les créatures à portée Moyenne, sauf les fidèles du Soleil Noir, subissent 3 de stress mental Perforant 1 au début de son tour ; un lanceur de sorts à portée Moyenne qui lance un sort de Yog-Sothoth gagne +1 Pouvoir mais ne peut acheter de d20 supplémentaires qu''avec de la Menace pour ce lancer."}],"threatSpends":[{"name":"Coriace 1","cost":"3","text":"Ignore une blessure subie."},{"name":"Élu majeur","cost":"1","text":"À la première apparition des Élus dans une scène : l''un d''eux devient un Élu majeur (PNJ Lieutenant)."},{"name":"Mutation supplémentaire","cost":"1","text":"Par mutation supplémentaire d''un Élu majeur (pas deux fois la même)."}]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Die Auserwählten, les Élus (mineurs et majeurs)' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Die Toten', 'Garde du corps mort-vivant de l''Exarque', 'Garde personnelle et guerriers d''élite de Weissler, les Die Toten sont nés des rangs des morts, corps et esprits préservés par une magie perverse, le plus souvent à partir des Einsatzgruppen au service du Soleil Noir. Leur chair grise brûle à la lumière du jour, d''où leurs épais uniformes et leurs masques d''acier sans trous pour les yeux ; loyaux sans faille, seuls les porteurs du Totenkopfring peuvent les commander, et ils tuent leurs ennemis en silence avec des lames d''acier noir greffées.', '["Lieutenant","Axe"]', 'Gamemaster Guide', 192, '{"rank":"lieutenant","truths":["Garde du corps féroce","Abomination morte-vivante"],"attributes":{"agility":10,"brawn":10,"coordination":10,"insight":6,"reason":6,"will":9},"skills":[{"key":"athletics","rank":2,"focuses":[]},{"key":"fighting","rank":3,"focuses":["Armes de mêlée"]},{"key":"observation","rank":3,"focuses":[]},{"key":"resilience","rank":5,"focuses":[]},{"key":"survival","rank":3,"focuses":[]},{"key":"tactics","rank":1,"focuses":[]}],"stress":16,"injuries":2,"armour":6,"courage":7,"attacks":[{"name":"Griffes d''acier noir","focus":"Armes de mêlée","range":"contact","damage":5,"salvo":null,"qualities":"Vicieux, Faim, Parade","escalation":false}],"abilities":[{"name":"Rapidité mortelle","text":"Les Die Toten sont terriblement rapides : +1 difficulté à toutes les attaques à distance contre eux. Si une attaque à distance les rate, ils peuvent dépenser immédiatement 1 Menace pour faire une action mineure de mouvement."},{"name":"Agilité, Force, Coordination et Volonté extraordinaires (1)","text":"Ils gagnent un succès automatique à tous les tests de compétence utilisant l''Agilité, la Force, la Coordination ou la Volonté. Ils gagnent aussi +1 stress bonus aux attaques qui bénéficient de la Force ou de la Volonté, +1 Armure, +1 Courage et +1 Stress maximum, le tout déjà inclus."},{"name":"Immunisé au froid, à la maladie, à la peur, à la douleur, au poison, à la chaleur et au vide","text":"Les Die Toten sont immunisés au stress, aux complications et aux vérités qui représentent l''une de ces conditions."},{"name":"Décérébré","text":"Mus par l''instinct, ils poursuivent et attaquent l''ennemi le plus proche sauf ordre précis. Ils ne peuvent pas tenter de réactions, ne subissent ni stress ni blessures mentales et sont insensibles à la raison."},{"name":"Renaître dans les ténèbres","text":"Les Die Toten sont mortellement vulnérables au soleil. Leur uniforme les protège d''ordinaire, mais si cette protection est endommagée (par une blessure par exemple), ils subissent 4 de stress physique avec les effets Persistant 4 et Perforant 2 au début de chaque tour passé en plein soleil. À l''inverse, ils récupèrent 3 stress au début de chaque tour passé dans l''obscurité totale."}],"threatSpends":[{"name":"Rapidité mortelle","cost":"1","text":"Après une attaque à distance ratée contre eux : action mineure de mouvement."}]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Die Toten' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Reinhardt Weissler, Exarque du Soleil Noir', 'Chef immortel du Soleil Noir', 'Messie incontesté du Soleil Noir, craint jusqu''au sommet du régime, Weissler use de sa réputation de sorcier hors pair pour poursuivre sans relâche son but : libérer le soleil noir ; il ne voit dans les nazis qu''un moyen. Grâce aux secrets de Nyarlathotep, il paraît à peine cinquante ans, mais doit régulièrement subir le rituel Voler l''immortalité, pratiqué par Reiner Lang, pour que son corps ne retrouve pas son véritable état ; il n''est presque jamais seul, toujours escorté d''au moins deux Die Toten et de ses meilleurs sorciers. (VO : Reinhardt Weissler, Exarch of the Black Sun)', '["Némésis","Axe"]', 'Gamemaster Guide', 193, '{"rank":"nemesis","truths":["Chef immortel du Soleil Noir","Sorcier puissant","Restauré et revigoré"],"attributes":{"agility":9,"brawn":9,"coordination":9,"insight":10,"reason":10,"will":14},"skills":[{"key":"academia","rank":4,"focuses":["Occultisme"]},{"key":"athletics","rank":1,"focuses":[]},{"key":"fighting","rank":3,"focuses":["Armes de mêlée"]},{"key":"medicine","rank":2,"focuses":[]},{"key":"observation","rank":2,"focuses":[]},{"key":"persuasion","rank":3,"focuses":[]},{"key":"resilience","rank":2,"focuses":[]},{"key":"stealth","rank":1,"focuses":[]},{"key":"tactics","rank":2,"focuses":[]},{"key":"vehicles","rank":1,"focuses":[]}],"stress":16,"injuries":4,"armour":4,"courage":7,"attacks":[{"name":"Canne-épée du Soleil Noir","focus":"Armes de mêlée","range":"contact","damage":5,"salvo":null,"qualities":"Perforant 1, Faim, Fléau, Caché, Parade","escalation":false}],"abilities":[{"name":"Pouvoir","text":"Pouvoir : 7."},{"name":"Fanatique","text":"Les fanatiques gagnent +1 en Courage (inclus ci-dessus) et +X Moral, X étant le nombre de fanatiques de leur camp présents dans la scène (maximum +5 Moral)."},{"name":"Récupération rapide 2","text":"À la fin de chacun de ses tours, Weissler retire 2 stress. De plus, s''il est blessé au début de son tour, il peut dépenser 2 Menace pour retirer immédiatement cette blessure."},{"name":"Maître du Soleil Noir","text":"Weissler porte le Meister Totenkopfring, dont la rune lui permet de commander automatiquement tout autre porteur de Totenkopfring (comme s''il avait accompli le rituel Contraindre) sans coût, en plus des fonctions habituelles de l''anneau."},{"name":"Menaçant","text":"La présence de Weissler est de mauvais augure. Lorsqu''il apparaît pour la première fois dans une scène, générez immédiatement 2 Menace."},{"name":"Coriace 1","text":"Weissler supporte 4 blessures au lieu de 3. De plus, s''il subit une blessure, il peut dépenser 3 Menace pour l''ignorer."},{"name":"Sorts et rituels","text":"Weissler lance ses sorts avec la Volonté et est toujours considéré comme ayant un focus applicable pour lancer un sort. Il connaît tout sort des grimoires de Nyarlathotep ou de Yog-Sothoth dont le MJ a besoin, et tout rituel."}],"threatSpends":[{"name":"Récupération rapide 2","cost":"2","text":"Blessé au début de son tour : retire immédiatement cette blessure."},{"name":"Coriace 1","cost":"3","text":"Ignore une blessure subie."}]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Reinhardt Weissler, Exarque du Soleil Noir' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Albrecht Lohmann, Prieur du Soleil Noir', 'Commandant militaire du Soleil Noir', 'Commandant militaire du Soleil Noir, avec autorité sur les Chanoines et les Die Toten, Lohmann est cruel jusqu''à la moelle ; son zèle lui a valu la confiance croissante de l''Exarque. Sorcier sans doute le plus puissant de l''ordre, il mène lui-même certaines missions critiques, ce qui lui vaut la loyauté absolue des Chanoines et inquiète les autres Prieurs. Vaniteux, l''œil gris perçant et le rictus méprisant, il soigne son physique, adore l''uniforme SS et cache sous des cols hauts les cicatrices d''une varicelle d''enfance. (VO : Albrecht Lohmann, Prior of the Black Sun)', '["Némésis","Axe"]', 'Gamemaster Guide', 194, '{"rank":"nemesis","truths":["Commandant militaire du Soleil Noir","Sorcier puissant"],"attributes":{"agility":10,"brawn":9,"coordination":9,"insight":10,"reason":9,"will":11},"skills":[{"key":"academia","rank":3,"focuses":["Occultisme"]},{"key":"athletics","rank":3,"focuses":[]},{"key":"fighting","rank":3,"focuses":["Corps à corps","Armes de poing","Main nue","Armes lourdes","Armes de mêlée","Fusils","Vigilance","Exotique"]},{"key":"medicine","rank":1,"focuses":[]},{"key":"observation","rank":2,"focuses":[]},{"key":"persuasion","rank":2,"focuses":[]},{"key":"resilience","rank":3,"focuses":[]},{"key":"stealth","rank":1,"focuses":[]},{"key":"survival","rank":2,"focuses":[]},{"key":"tactics","rank":4,"focuses":["Aviation","Armée de terre","Opérations clandestines","Commandement","Marine","Projets techniques"]},{"key":"vehicles","rank":1,"focuses":[]}],"stress":14,"injuries":3,"armour":3,"courage":6,"attacks":[{"name":"Degen du Soleil Noir","focus":"Armes de mêlée","range":"contact","damage":5,"salvo":null,"qualities":"Perforant 1, Faim, Fléau, Parade","escalation":false},{"name":"Walther P Series (P38)","focus":"Armes de poing","range":"close","damage":5,"salvo":"Vicieux","qualities":"Combat rapproché, Fiable","escalation":false}],"abilities":[{"name":"Pouvoir","text":"Pouvoir : 6."},{"name":"Sorts et rituels","text":"Lohmann est un puissant lanceur de sorts qui utilise la Volonté et est toujours considéré comme ayant un focus applicable pour lancer un sort. Il connaît tout sort des grimoires de Nyarlathotep et de Yog-Sothoth dont le MJ a besoin."},{"name":"Prieur du Soleil Noir","text":"Lohmann porte un Totenkopfring de Prieur dont la rune lui permet de commander automatiquement tout autre porteur de Totenkopfring, sauf l''Exarque et les autres Prieurs (comme s''il avait accompli le rituel Contraindre), sans coût, en plus des fonctions habituelles de l''anneau."},{"name":"Fanatique","text":"Les fanatiques gagnent +1 en Courage (inclus ci-dessus) et +X Moral, X étant le nombre de fanatiques de leur camp présents dans la scène (maximum +5 Moral)."},{"name":"Premier parmi les Chanoines","text":"Lohmann est le chef vénéré des Chanoines. Tant qu''il est présent dans une scène, les Chanoines du Soleil Noir retirent 2 stress au début de chacun de ses tours et peuvent relancer un d20 sur tout test de Perception, de Raisonnement ou de Volonté."},{"name":"Menaçant","text":"La présence de Lohmann est de mauvais augure. Lorsqu''il apparaît pour la première fois dans une scène, générez immédiatement 1 Menace."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Albrecht Lohmann, Prieur du Soleil Noir' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Astrid Urner, Prieure du Soleil Noir', 'Prieure du Soleil Noir, cheffe de la section d''analyse', 'Linguiste formée à Oxford, passionnée de langues mortes et d''occultisme, Astrid Urner a prêté serment au Soleil Noir et dirige sa section d''analyse, traquant les indices de l''ère hyperboréenne. Voûtée, toussant, une canne à la main, elle a l''air d''une vieille tante en tweed plutôt que d''une magicienne noire. Elle garde en secret une relation proche avec Mina Wolff. (VO : Astrid Urner, Prior of the Black Sun)', '["Némésis","Axe"]', 'Gamemaster Guide', 195, '{"rank":"nemesis","truths":["Universitaire âgée","Sympathisante de Wolff"],"attributes":{"agility":7,"brawn":7,"coordination":7,"insight":10,"reason":11,"will":9},"skills":[{"key":"academia","rank":5,"focuses":["Tous"]},{"key":"engineering","rank":1,"focuses":[]},{"key":"fighting","rank":1,"focuses":["Armes de mêlée"]},{"key":"medicine","rank":1,"focuses":[]},{"key":"observation","rank":2,"focuses":[]},{"key":"persuasion","rank":2,"focuses":[]},{"key":"resilience","rank":2,"focuses":[]},{"key":"stealth","rank":1,"focuses":[]},{"key":"survival","rank":2,"focuses":[]},{"key":"tactics","rank":2,"focuses":[]},{"key":"vehicles","rank":1,"focuses":[]}],"stress":11,"injuries":3,"armour":0,"courage":7,"attacks":[{"name":"Canne-épée du Soleil Noir","focus":"Armes de mêlée","range":"contact","damage":4,"salvo":null,"qualities":"Perforant 1, Faim, Fléau, Caché, Parade","escalation":false}],"abilities":[{"name":"Universitaire chevronnée","text":"Urner peut relancer autant de d20 qu''elle le souhaite sur tout test d''Érudition. Son Courage est augmenté de son rang d''Érudition (déjà inclus)."},{"name":"Prieure du Soleil Noir","text":"Elle porte une Totenkopfring de Prieur dont la rune lui permet de commander automatiquement et sans coût tout autre porteur de Totenkopfring (sauf l''Exarque ou un autre Prieur), comme avec le rituel Contraindre, en plus des fonctions habituelles de l''anneau."},{"name":"Fanatique","text":"+1 en Courage (inclus) et +X en Moral, X étant le nombre de fanatiques de son camp présents dans la scène (Moral +5 au maximum)."},{"name":"Menaçante","text":"Sa présence est de mauvais augure : quand elle apparaît pour la première fois dans une scène, générez 1 point de Menace."},{"name":"Sorts et rituels","text":"Pouvoir 5. Lanceuse de sorts utilisant la Raison, toujours considérée comme ayant un focus applicable. Elle connaît tout sort ou rituel voulu par le MJ des grimoires de Nyarlathotep et de Yog-Sothoth."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Astrid Urner, Prieure du Soleil Noir' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Reiner Lang, Prieur du Soleil Noir', 'Prieur du Soleil Noir, chef de la recherche et du développement', 'Répugnant même aux yeux du Soleil Noir, Lang, scientifique et médecin fasciné par les alchimistes, a fui Munich après la disparition de plusieurs sans-abri. Il dirige la recherche du Soleil Noir, a créé les Gefallenen et pratique pour l''Exarque le rituel Voler l''immortalité. Surnommé « la Limace », chauve, moite et crasseux, il porte des uniformes trop serrés et maculés. (VO : Reiner Lang, Prior of the Black Sun)', '["Némésis","Axe"]', 'Gamemaster Guide', 195, '{"rank":"nemesis","truths":["Scientifique et sorcier répugnant"],"attributes":{"agility":8,"brawn":7,"coordination":8,"insight":8,"reason":9,"will":10},"skills":[{"key":"academia","rank":3,"focuses":["Occultisme"]},{"key":"athletics","rank":1,"focuses":[]},{"key":"engineering","rank":1,"focuses":[]},{"key":"fighting","rank":2,"focuses":["Armes de mêlée","Armes de poing"]},{"key":"medicine","rank":4,"focuses":["Chirurgie"]},{"key":"observation","rank":2,"focuses":[]},{"key":"resilience","rank":2,"focuses":[]},{"key":"survival","rank":2,"focuses":[]},{"key":"tactics","rank":2,"focuses":["Tactique du champ de bataille"]},{"key":"vehicles","rank":1,"focuses":[]}],"stress":12,"injuries":3,"armour":1,"courage":5,"attacks":[{"name":"Couteau d''acier noir","focus":"Armes de mêlée","range":"contact","damage":3,"salvo":null,"qualities":"Perforant 1, Faim, Fléau, Caché, Subtil","escalation":false},{"name":"Walther P Series (P38)","focus":"Armes de poing","range":"close","damage":3,"salvo":"Vicieux","qualities":"Combat rapproché, Caché, Fiable","escalation":false}],"abilities":[{"name":"Sorts et rituels","text":"Pouvoir 4. Lanceur de sorts utilisant la Raison, toujours considéré comme ayant un focus applicable. Il connaît tout sort voulu par le MJ des grimoires de Nyarlathotep et de Yog-Sothoth."},{"name":"Prieur du Soleil Noir","text":"Il porte une Totenkopfring de Prieur dont la rune lui permet de commander automatiquement et sans coût tout autre porteur de Totenkopfring (sauf l''Exarque ou un autre Prieur), comme avec le rituel Contraindre, en plus des fonctions habituelles de l''anneau."},{"name":"Fanatique","text":"+1 en Courage (inclus) et +X en Moral, X étant le nombre de fanatiques de son camp présents dans la scène (Moral +5 au maximum)."},{"name":"Menaçant","text":"Sa présence est de mauvais augure : quand il apparaît pour la première fois dans une scène, générez 1 point de Menace."},{"name":"Anatomiste impie","text":"Lors d''une attaque de mêlée, il peut utiliser sa compétence Médecine et son focus Chirurgie. Il peut aussi dépenser 1 Menace pour relancer autant de dés de combat qu''il veut quand il inflige du stress physique avec une attaque ou un sort."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Reiner Lang, Prieur du Soleil Noir' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Klaudia Fleischer, Prieure du Soleil Noir', 'Prieure du Soleil Noir, cheffe des rêveurs de la Norn', 'Fleischer commande les rêveurs de la Norn et travaille avec la Gestapo, ses rêveurs fouillant les esprits endormis à la recherche de traîtres. Internée pour hystérie puis libérée par Weissler, elle a tenté de mourir après avoir contemplé le soleil noir et seule la magie de l''Exarque l''a sauvée. D''une beauté glaciale, toujours en uniforme SS impeccable, elle cache ses cicatrices sous des manchettes d''argent. (VO : Klaudia Fleischer, Prior of the Black Sun)', '["Némésis","Axe"]', 'Gamemaster Guide', 196, '{"rank":"nemesis","truths":["Cheffe de la Norn","L''arme secrète de la Gestapo"],"attributes":{"agility":8,"brawn":8,"coordination":7,"insight":11,"reason":9,"will":11},"skills":[{"key":"academia","rank":3,"focuses":["Occultisme","Histoire"]},{"key":"athletics","rank":1,"focuses":[]},{"key":"engineering","rank":1,"focuses":[]},{"key":"fighting","rank":2,"focuses":["Armes de mêlée"]},{"key":"medicine","rank":1,"focuses":[]},{"key":"observation","rank":2,"focuses":[]},{"key":"persuasion","rank":3,"focuses":[]},{"key":"resilience","rank":2,"focuses":[]},{"key":"stealth","rank":1,"focuses":[]},{"key":"survival","rank":2,"focuses":[]},{"key":"tactics","rank":1,"focuses":[]},{"key":"vehicles","rank":1,"focuses":[]}],"stress":14,"injuries":3,"armour":1,"courage":5,"attacks":[{"name":"Rapière (Degen) du Soleil Noir","focus":"Armes de mêlée","range":"contact","damage":4,"salvo":null,"qualities":"Perforant 1, Faim, Fléau, Parade","escalation":false},{"name":"Walther P Series (P38)","focus":"Armes de poing","range":"close","damage":5,"salvo":"Vicieux","qualities":"Combat rapproché, Fiable","escalation":false}],"abilities":[{"name":"Prieure du Soleil Noir","text":"Elle porte une Totenkopfring de Prieur dont la rune lui permet de commander automatiquement et sans coût tout autre porteur de Totenkopfring (sauf l''Exarque ou un autre Prieur), comme avec le rituel Contraindre, en plus des fonctions habituelles de l''anneau."},{"name":"Rêveuse","text":"Les rêveurs sont redoutables dans les Contrées du Rêve : ils peuvent y substituer leur Volonté à l''Agilité, la Force ou la Coordination."},{"name":"Fanatique","text":"+1 en Courage (inclus) et +X en Moral, X étant le nombre de fanatiques de son camp présents dans la scène (Moral +5 au maximum)."},{"name":"Magie latente","text":"Quand elle assiste un rituel (au lieu de le mener), elle génère automatiquement 1 succès au lieu de lancer les dés, et apporte tout son Pouvoir au lanceur principal au lieu de la moitié."},{"name":"Menaçante","text":"Quand elle apparaît pour la première fois dans une scène, générez 1 point de Menace."},{"name":"Sens télépathiques","text":"Elle peut dépenser 1 Menace lors d''un test de Perception + Observation pour repérer des personnages hostiles, des pièges ou menaces semblables : la difficulté du test baisse alors de 2 (minimum 0)."},{"name":"Sorts et rituels","text":"Pouvoir 5. Lanceuse de sorts utilisant la Perception, toujours considérée comme ayant un focus applicable. Elle connaît tout sort voulu par le MJ des grimoires de Nyarlathotep et de Yog-Sothoth, ainsi que le rituel Visiter les Contrées du Rêve."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Klaudia Fleischer, Prieure du Soleil Noir' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Standartenführer Liesel Böhm, « la Douce »', 'Agente du Soleil Noir, colonel SS', 'Grande, une crinière rousse bouclée, « la Douce » Liesel semble sortie d''un défilé de mode parisien. Malveillante, rusée et espiègle, agente renommée du Soleil Noir, elle a mené des missions dans le monde entier et porte l''uniforme de Standartenführer SS depuis 1943. Elle se croit adepte mais ne fait que tâter de la magie, et se délecte du chaos et d''actes gratuits de cruauté ou de générosité. (VO : Standartenführer ''Sweet'' Liesel Böhm)', '["Némésis","Axe"]', 'Gamemaster Guide', 197, '{"rank":"nemesis","truths":["Belle","Espiègle","Charismatique","Dilettante de l''occulte"],"attributes":{"agility":9,"brawn":8,"coordination":9,"insight":8,"reason":8,"will":9},"skills":[{"key":"academia","rank":1,"focuses":["Occultisme"]},{"key":"athletics","rank":2,"focuses":[]},{"key":"engineering","rank":1,"focuses":[]},{"key":"fighting","rank":3,"focuses":["Fusils","Armes lourdes"]},{"key":"medicine","rank":1,"focuses":[]},{"key":"observation","rank":1,"focuses":[]},{"key":"persuasion","rank":2,"focuses":[]},{"key":"resilience","rank":2,"focuses":[]},{"key":"stealth","rank":2,"focuses":[]},{"key":"survival","rank":2,"focuses":[]},{"key":"tactics","rank":2,"focuses":["Tactique du champ de bataille"]},{"key":"vehicles","rank":1,"focuses":[]}],"stress":11,"injuries":3,"armour":2,"courage":3,"attacks":[{"name":"Sturmgewehr 44 (StG 44)","focus":"Fusils","range":"medium","damage":5,"salvo":"Étourdissant","qualities":"Peu fiable","escalation":false},{"name":"Luger P08 9 mm","focus":"Armes de poing","range":"close","damage":4,"salvo":"Vicieux","qualities":"Combat rapproché","escalation":false},{"name":"Stielhandgranate 24","focus":"Lancer","range":"close","damage":5,"salvo":null,"qualities":"Zone, Étourdissant, Munition","escalation":false},{"name":"Flammenwerfer 41 (FmW 41)","focus":"Armes lourdes","range":"close","damage":5,"salvo":"Zone","qualities":"Persistant 4, Débilitant, Escalade","escalation":true},{"name":"Maschinengewehr 42 (MG 42)","focus":"Fusils","range":"medium","damage":6,"salvo":"Zone","qualities":"Escalade, Lourd, Imprécis","escalation":true},{"name":"Panzerfaust 60","focus":"Armes lourdes","range":"long","damage":5,"salvo":null,"qualities":"Perforant 1, Vicieux, Encombrant, Escalade, Tueur de géants, Lourd, Imprécis, Munition","escalation":true}],"abilities":[{"name":"Actes de chaos gratuits","text":"Une fois par scène, Böhm peut commettre un acte de cruauté ou de générosité inexplicable, contraire à son comportement jusque-là (exécuter un subordonné sur un coup de tête, laisser filer des ennemis pour un prétexte futile). En combat, c''est une action majeure. Elle lance alors 3 dés de combat et génère immédiatement autant de Menace que le total obtenu. Si le nombre d''effets obtenus dépasse le nombre de fois où elle a utilisé cette capacité dans la scène, elle peut l''utiliser une fois de plus."},{"name":"Dilettante de l''occulte","text":"Pouvoir 2. En lançant un sort, elle peut augmenter son Pouvoir de +2, mais retire alors 1 point de Menace par effet obtenu sur ses dés de Pouvoir. Elle connaît trois sorts des grimoires de Nyarlathotep ou de Yog-Sothoth, au choix du MJ."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Standartenführer Liesel Böhm, « la Douce »' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Soldat de la Nachtwölfe (sous-officier / lieutenant)', 'Fantassin de la Nachtwölfe', 'Fantassins standard de la Nachtwölfe, rarement améliorés par la science mais entraînés au maniement de l''armement avancé tiré du Blauer Kristall. Soldats, sous-officiers et jeunes officiers espèrent faire leurs preuves sur le terrain pour devenir spécialistes, et un jour manier les plaques de force d''un Stärkemeister. (VO : Nachtwölfe Trooper / NCO / Lieutenant)', '["Troupe","Axe"]', 'Gamemaster Guide', 199, '{"rank":"trooper","truths":["Fantassin ambitieux et intelligent"],"attributes":{"agility":8,"brawn":8,"coordination":8,"insight":7,"reason":9,"will":8},"skills":[{"key":"academia","rank":1,"focuses":[]},{"key":"athletics","rank":1,"focuses":[]},{"key":"engineering","rank":1,"focuses":[]},{"key":"fighting","rank":2,"focuses":["Fusils"]},{"key":"resilience","rank":2,"focuses":[]},{"key":"stealth","rank":1,"focuses":[]},{"key":"survival","rank":1,"focuses":[]},{"key":"tactics","rank":1,"focuses":["Commandement"]}],"stress":5,"injuries":1,"armour":1,"courage":2,"attacks":[{"name":"Sturmgewehr 44 (StG 44)","focus":"Fusils","range":"medium","damage":5,"salvo":"Étourdissant","qualities":"Peu fiable","escalation":false},{"name":"Luger P08 9 mm","focus":"Armes de poing","range":"close","damage":4,"salvo":"Vicieux","qualities":"Combat rapproché","escalation":false},{"name":"Maschinengewehr 42 (MG 42)","focus":"Fusils","range":"medium","damage":6,"salvo":"Zone","qualities":"Escalade, Lourd, Imprécis","escalation":true},{"name":"Stielhandgranate 24","focus":"Lancer","range":"close","damage":5,"salvo":null,"qualities":"Zone, Étourdissant, Munition","escalation":true}],"abilities":[{"name":"Amélioré (option d''escalade)","text":"Les lieutenants peuvent porter une augmentation unique."},{"name":"Formation technique avancée","text":"Les soldats de la Nachtwölfe sont formés à toutes sortes de technologies expérimentales : la difficulté de tout test d''utilisation d''un appareil technologique baisse de 1 (minimum 1)."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Soldat de la Nachtwölfe (sous-officier / lieutenant)' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Scientifique de la Nachtwölfe', 'Chercheur de laboratoire', 'Rarement sur le terrain, trop occupés dans la sécurité relative de leurs laboratoires, les scientifiques de la Nachtwölfe se rencontrent parfois sur des sites de découvertes atlantes importantes, avec le matériel qu''exige leur tâche. Sur le terrain, ils délaissent l''uniforme pour la blouse ou l''habit civil en espérant passer inaperçus. (VO : Nachtwölfe Scientist)', '["Troupe","Axe"]', 'Gamemaster Guide', 199, '{"rank":"trooper","truths":["Expérimentateur scientifique amoral"],"attributes":{"agility":7,"brawn":8,"coordination":6,"insight":8,"reason":10,"will":9},"skills":[{"key":"academia","rank":3,"focuses":["Science"]},{"key":"engineering","rank":2,"focuses":[]},{"key":"medicine","rank":2,"focuses":[]},{"key":"observation","rank":1,"focuses":[]},{"key":"persuasion","rank":1,"focuses":[]},{"key":"vehicles","rank":1,"focuses":[]}],"stress":4,"injuries":1,"armour":1,"courage":1,"attacks":[{"name":"Luger P08 9 mm","focus":"Armes de poing","range":"close","damage":4,"salvo":"Vicieux","qualities":"Combat rapproché","escalation":false}],"abilities":[{"name":"Chercheur dévoué","text":"À portée courte d''un sujet de ses recherches, il gagne +2 en Moral, prêt à prendre de gros risques pour continuer à l''étudier."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Scientifique de la Nachtwölfe' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Chercheur de terrain de la Nachtwölfe', 'Chasseur de technologies perdues', 'Le chercheur de terrain parcourt le globe à la recherche de technologies perdues, atlantes ou autres, que les équipes scientifiques de la Nachtwölfe détourneront au service de la cause nazie. Il porte l''équipement technique et d''enquête qu''exige sa mission, reconnaissable à l''uniforme bleu-gris frappé de la patte de loup. (VO : Nachtwölfe Field Researcher)', '["Troupe","Axe"]', 'Gamemaster Guide', 200, '{"rank":"trooper","truths":["Enquêteur amoral"],"attributes":{"agility":8,"brawn":7,"coordination":8,"insight":8,"reason":9,"will":8},"skills":[{"key":"academia","rank":2,"focuses":[]},{"key":"athletics","rank":2,"focuses":[]},{"key":"engineering","rank":2,"focuses":[]},{"key":"fighting","rank":1,"focuses":["Armes de poing","Corps à corps"]},{"key":"observation","rank":1,"focuses":[]},{"key":"resilience","rank":1,"focuses":[]},{"key":"vehicles","rank":1,"focuses":[]}],"stress":5,"injuries":1,"armour":1,"courage":1,"attacks":[{"name":"Luger P08 9 mm","focus":"Armes de poing","range":"close","damage":4,"salvo":"Vicieux","qualities":"Combat rapproché","escalation":false}],"abilities":[{"name":"Chercheur dévoué","text":"À portée courte d''un sujet de ses recherches, il gagne +2 en Moral, prêt à prendre de gros risques pour continuer à l''étudier."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Chercheur de terrain de la Nachtwölfe' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Stärkemeister (Maître de force)', 'Officier d''élite manieur de plaques de force', 'Les Maîtres de force forment la caste des officiers de la Nachtwölfe, appelés sur le champ de bataille aux moments critiques. Leur entraînement porte presque exclusivement sur les plaques de force, et un nouveau Maître n''est reconnu par ses pairs qu''après avoir massacré tout un équipage de char avec ses seules plaques. Il porte deux étranges plaques de métal cloutées alimentées par une lourde batterie dorsale. (VO : Stärkemeister (Force Master))', '["Lieutenant","Axe"]', 'Gamemaster Guide', 200, '{"rank":"lieutenant","truths":["Chef de la Nachtwölfe","Fidèle convaincu"],"attributes":{"agility":8,"brawn":8,"coordination":9,"insight":8,"reason":9,"will":9},"skills":[{"key":"academia","rank":1,"focuses":[]},{"key":"athletics","rank":2,"focuses":[]},{"key":"engineering","rank":2,"focuses":["Génie de combat"]},{"key":"fighting","rank":3,"focuses":["Corps à corps"]},{"key":"resilience","rank":2,"focuses":[]},{"key":"stealth","rank":1,"focuses":[]},{"key":"survival","rank":2,"focuses":[]},{"key":"tactics","rank":2,"focuses":["Tactique du champ de bataille"]},{"key":"vehicles","rank":2,"focuses":[]}],"stress":11,"injuries":2,"armour":2,"courage":3,"attacks":[{"name":"Luger P08 9 mm","focus":"Armes de poing","range":"close","damage":4,"salvo":"Vicieux","qualities":"Combat rapproché","escalation":false},{"name":"Plaques de force atlantes","focus":"Corps à corps","range":"close","damage":5,"salvo":"Intense","qualities":"Étourdissant, Encombrant, Escalade, Tueur de géants (règles spéciales des plaques de force)","escalation":false},{"name":"Dague Eisenstachel","focus":"Armes de mêlée","range":"contact","damage":2,"salvo":null,"qualities":"Perforant 1","escalation":false}],"abilities":[{"name":"Maîtrise avancée des plaques de force","text":"En attaquant avec ses plaques de force, il peut dépenser 1 Menace pour porter la portée de l''arme à Moyenne ou ajouter l''effet Piège à l''attaque, ou 2 Menace pour les deux."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Stärkemeister (Maître de force)' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Éclaireur de la Nachtwölfe (Pathfinder)', 'Éclaireur d''infiltration et observateur d''artillerie', 'Légèrement armé et protégé, l''éclaireur est le spécialiste de l''infiltration de la Nachtwölfe, ses yeux et ses oreilles sur le champ de bataille. Optiques de jour et de nuit et radio puissante lui permettent de repérer l''ennemi, de diriger mortiers et artillerie, puis de lancer l''assaut. Sauf s''il est acculé, il évite le combat et se replie vers ses lignes. (VO : Nachtwölfe Pathfinder (Scout))', '["Lieutenant","Axe"]', 'Gamemaster Guide', 201, '{"rank":"lieutenant","truths":["Éclaireurs d''élite","Technologie de pointe"],"attributes":{"agility":8,"brawn":8,"coordination":9,"insight":9,"reason":9,"will":9},"skills":[{"key":"academia","rank":1,"focuses":[]},{"key":"athletics","rank":2,"focuses":[]},{"key":"engineering","rank":1,"focuses":[]},{"key":"fighting","rank":3,"focuses":["Armes lourdes","Fusils"]},{"key":"observation","rank":3,"focuses":["Vue"]},{"key":"resilience","rank":2,"focuses":[]},{"key":"stealth","rank":1,"focuses":[]},{"key":"survival","rank":1,"focuses":[]},{"key":"tactics","rank":2,"focuses":[]},{"key":"vehicles","rank":1,"focuses":[]}],"stress":11,"injuries":2,"armour":1,"courage":3,"attacks":[{"name":"Sturmgewehr 44 (StG 44)","focus":"Fusils","range":"medium","damage":6,"salvo":"Étourdissant","qualities":"Peu fiable","escalation":false},{"name":"Frappe antiblindage (Bombardement aérien, 2 Menace)","focus":"Armes lourdes","range":"long","damage":7,"salvo":null,"qualities":"Perforant 1, Vicieux, Encombrant, Tueur de géants","escalation":false},{"name":"Frappe antipersonnel (Bombardement aérien, 2 Menace)","focus":"Armes lourdes","range":"long","damage":7,"salvo":null,"qualities":"Zone, Étourdissant","escalation":false}],"abilities":[{"name":"Optiques avancées","text":"Il peut relancer un d20 sur tout test d''Observation utilisant son focus Vue, et ignore toute hausse de difficulté due à la faible lumière ou à l''obscurité."},{"name":"Bombardement aérien","text":"Par une action majeure et 2 Menace, l''éclaireur appelle un tir de soutien d''une artillerie lointaine ou d''un avion de passage. C''est une attaque en Raison + Combat de difficulté 2, avec l''un des deux profils Frappe antiblindage ou Frappe antipersonnel."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Éclaireur de la Nachtwölfe (Pathfinder)' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Traqueur de la Nachtwölfe (Stalker)', 'Spécialiste des armes lourdes et du soutien', 'Le Stalker appuie les troupes de première ligne de sa puissance de feu. Les candidats suivent trois mois d''entraînement intense et d''injections croissantes de Vitalität IX, qui les font grossir et gagner en force mais leur ôtent raison et sang-froid. Hauts de 2,10 m, ils portent sans peine le lourd Jagdgewehr StGw43A ; leur gabarit, leurs gantelets blindés et leur équipement donnent l''impression d''affronter une chose d''un autre monde. (VO : Nachtwölfe Stalker (Heavy Weapon / Support Specialist))', '["Lieutenant","Axe"]', 'Gamemaster Guide', 201, '{"rank":"lieutenant","truths":["Colosse du champ de bataille de la Nachtwölfe","Voit l''invisible"],"attributes":{"agility":10,"brawn":10,"coordination":13,"insight":7,"reason":6,"will":10},"skills":[{"key":"athletics","rank":3,"focuses":[]},{"key":"engineering","rank":1,"focuses":[]},{"key":"fighting","rank":4,"focuses":["Main nue","Fusils","Armes lourdes"]},{"key":"observation","rank":1,"focuses":["Vue"]},{"key":"resilience","rank":5,"focuses":[]},{"key":"stealth","rank":1,"focuses":[]},{"key":"survival","rank":1,"focuses":[]},{"key":"tactics","rank":1,"focuses":[]}],"stress":16,"injuries":3,"armour":7,"courage":7,"attacks":[{"name":"Jagdgewehr Sturmgewehr 43A","focus":"Fusils","range":"medium","damage":6,"salvo":"Vicieux","qualities":"Perforant 1, Fiable","escalation":false},{"name":"Panzerfaust intégré","focus":"Armes lourdes","range":"long","damage":5,"salvo":null,"qualities":"Perforant 1, Vicieux, Encombrant, Escalade, Tueur de géants, Imprécis, Munition","escalation":false},{"name":"Bottes et gantelets d''acier","focus":"Main nue","range":"contact","damage":6,"salvo":null,"qualities":"Étourdissant, Vicieux","escalation":false},{"name":"Maschinengewehr 131 (MG 131)","focus":"Armes lourdes","range":"medium","damage":7,"salvo":"Zone","qualities":"Escalade, Imprécis","escalation":true}],"abilities":[{"name":"Optiques avancées","text":"Il peut relancer un d20 sur tout test d''Observation utilisant son focus Vue, et ignore toute hausse de difficulté due à la faible lumière ou à l''obscurité."},{"name":"Force extraordinaire 1","text":"1 succès automatique sur tous les tests de compétence basés sur la Force ; +1 aux attaques de mêlée, +1 en Armure et en stress maximum (déjà inclus)."},{"name":"Surpuissance","text":"Il ignore la qualité Lourd de toutes les armes qu''il manie (déjà retirée de ses armes). Il génère 1 Menace chaque fois qu''il inflige une blessure."},{"name":"Taille 1","text":"Il subit une blessure à partir de 6 points de stress (après réductions) en une seule attaque, au lieu de 5. Sa taille peut rendre certaines tâches plus faciles ou plus difficiles."},{"name":"Coriace 1","text":"Il supporte une blessure de plus que la normale (incluse). Il peut aussi dépenser 3 Menace pour ignorer une blessure qui lui est infligée."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Traqueur de la Nachtwölfe (Stalker)' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Nachtjäger (tireur d''élite)', 'Tireur d''élite et assassin', 'Les Nachtjäger, « chasseurs de nuit », sont des spécialistes de l''assassinat qui visent sous-officiers et officiers pour désorganiser le commandement ennemi. Leur fusil BK-259 Feindsucher porte à 1 000 m et sa balle de Blauer Kristall traverse couvert et armure. Les plus aguerris, après deux douzaines d''officiers abattus, reçoivent le camouflage adaptatif Hüllen ; tous portent une dague relique contre les entités du Soleil Noir. (VO : Nachtjäger (Sniper))', '["Lieutenant","Axe"]', 'Gamemaster Guide', 202, '{"rank":"lieutenant","truths":["Tireur d''élite de la Nachtwölfe"],"attributes":{"agility":8,"brawn":8,"coordination":9,"insight":9,"reason":8,"will":9},"skills":[{"key":"academia","rank":1,"focuses":[]},{"key":"athletics","rank":2,"focuses":[]},{"key":"engineering","rank":1,"focuses":[]},{"key":"fighting","rank":3,"focuses":["Armes lourdes","Fusils"]},{"key":"medicine","rank":1,"focuses":[]},{"key":"observation","rank":2,"focuses":["Vue"]},{"key":"resilience","rank":1,"focuses":[]},{"key":"stealth","rank":2,"focuses":["Tous"]},{"key":"survival","rank":1,"focuses":[]},{"key":"tactics","rank":2,"focuses":[]},{"key":"vehicles","rank":1,"focuses":[]}],"stress":10,"injuries":2,"armour":1,"courage":2,"attacks":[{"name":"BK 259 Feindsucher (« Chercheur d''ennemis »)","focus":"Fusils","range":"extreme","damage":7,"salvo":"Vicieux","qualities":"Perforant 1, Précis","escalation":false},{"name":"Luger P08 9 mm","focus":"Armes de poing","range":"close","damage":5,"salvo":"Vicieux","qualities":"Combat rapproché","escalation":false}],"abilities":[{"name":"Optiques avancées","text":"Il peut relancer un d20 sur tout test d''Observation utilisant son focus Vue, et ignore toute hausse de difficulté due à la faible lumière ou à l''obscurité."},{"name":"Munitions de Blauer Kristall","text":"Il peut dépenser 1 Menace pour tirer une balle de Blauer Kristall : l''arme gagne la qualité Fléau et les attaques en salve gagnent l''effet Perforant 1."},{"name":"Camouflage Hüllen (escalade)","text":"Quand il apparaît pour la première fois dans une scène, il peut dépenser 2 Menace pour être équipé du camouflage Hüllen : il gagne la vérité « Dissimulé », qui s''applique à ses tests de Discrétion et aux tests pour le localiser dans un lieu sombre ou mal éclairé."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Nachtjäger (tireur d''élite)' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Pionier de la Nachtwölfe (génie de combat)', 'Sapeur et spécialiste de la défense', 'La Nachtwölfe dépend lourdement de sa technologie, et le Pionier est l''expert de l''entretien et de la réparation des machines atlantes et au Blauer Kristall, en plus du rôle classique de sapeur. Armé du fusil à pompe à bande Höllenfeuer, il transporte grenades, explosifs, mortiers et tourelles, et excelle à poser ou lever champs de mines, barricades et fortifications. (VO : Nachtwölfe Pionier (Combat Engineer))', '["Lieutenant","Axe"]', 'Gamemaster Guide', 203, '{"rank":"lieutenant","truths":["Spécialiste retors de la défense de la Nachtwölfe"],"attributes":{"agility":8,"brawn":7,"coordination":9,"insight":9,"reason":9,"will":9},"skills":[{"key":"academia","rank":1,"focuses":[]},{"key":"athletics","rank":2,"focuses":[]},{"key":"engineering","rank":3,"focuses":["Génie de combat","Explosifs","Génie mécanique"]},{"key":"fighting","rank":3,"focuses":["Corps à corps","Armes lourdes"]},{"key":"observation","rank":1,"focuses":[]},{"key":"resilience","rank":1,"focuses":[]},{"key":"stealth","rank":1,"focuses":[]},{"key":"survival","rank":1,"focuses":[]},{"key":"tactics","rank":2,"focuses":["Tactique du champ de bataille"]},{"key":"vehicles","rank":2,"focuses":[]}],"stress":10,"injuries":2,"armour":2,"courage":2,"attacks":[{"name":"Fusil à pompe à bande Höllenfeuer (« Feu d''enfer »)","focus":"Corps à corps","range":"close","damage":7,"salvo":"Zone","qualities":"Escalade, Imprécis","escalation":false},{"name":"Flammenwerfer 41 (FmW 41)","focus":"Armes lourdes","range":"close","damage":6,"salvo":"Zone","qualities":"Persistant 4, Débilitant, Escalade","escalation":true},{"name":"Stielhandgranate 24","focus":"Lancer","range":"close","damage":6,"salvo":null,"qualities":"Zone, Étourdissant, Munition","escalation":true}],"abilities":[{"name":"Formation technique avancée","text":"La difficulté de tout test d''utilisation d''un appareil technologique baisse de 1 (minimum 1)."},{"name":"Retranchement","text":"S''il a eu le temps de préparer ses défenses, le Pionier génère 3 Menace, à dépenser uniquement sur les options Mines et/ou Couvert."},{"name":"Mines","text":"Il peut dépenser jusqu''à 3 Menace pour semer une zone de mines antipersonnel compactes. Un personnage qui y entre lance X dés de combat (X = Menace dépensée) : s''il obtient au moins un effet, il subit 6 points de stress physique avec les effets Zone et Étourdissant. On peut tenter de repérer les mines avant d''entrer, avec une difficulté égale à la Menace dépensée. Pour 1 Élan, mines incendiaires : Persistant 4 remplace Étourdissant."},{"name":"Couvert","text":"Il peut dépenser jusqu''à 3 Menace pour fortifier une zone (barricades, terrassements, sacs de sable). Chaque point crée une fortification, qui accorde soit +4 de Couvert à un personnage à son contact, soit +2 de Couvert à deux personnages à son contact au plus, au choix à sa création."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Pionier de la Nachtwölfe (génie de combat)' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Hundemeister / Bestienmeister de la Nachtwölfe', 'Maître-chien et dresseur de bêtes augmentées', 'Ces spécialistes dressent et déploient les créatures améliorées au Blauer Kristall. Le plus courant est le Hundemeister et ses bergers allemands aux yeux et aux crocs luisant de bleu, gardiens et pisteurs redoutables pour débusquer infiltrés et évadés. Plus rares, d''autres Bestienmeister travailleraient avec aigles, ours, loups, voire aurochs. (VO : Nachtwölfe Hundemeister / Bestienmeister)', '["Lieutenant","Axe"]', 'Gamemaster Guide', 204, '{"rank":"lieutenant","truths":["Dresseur de bêtes dépravé"],"attributes":{"agility":9,"brawn":9,"coordination":8,"insight":8,"reason":9,"will":8},"skills":[{"key":"academia","rank":1,"focuses":[]},{"key":"athletics","rank":2,"focuses":[]},{"key":"engineering","rank":2,"focuses":["Génie de combat","Génie mécanique"]},{"key":"fighting","rank":3,"focuses":["Fusils","Armes lourdes"]},{"key":"medicine","rank":1,"focuses":[]},{"key":"observation","rank":1,"focuses":[]},{"key":"resilience","rank":1,"focuses":[]},{"key":"stealth","rank":1,"focuses":[]},{"key":"survival","rank":2,"focuses":[]},{"key":"tactics","rank":2,"focuses":["Tactique du champ de bataille"]},{"key":"vehicles","rank":1,"focuses":[]}],"stress":10,"injuries":2,"armour":3,"courage":1,"attacks":[{"name":"Maschinenpistole 40 (MP 40)","focus":"Corps à corps","range":"close","damage":4,"salvo":"Étourdissant","qualities":"Imprécis","escalation":false}],"abilities":[{"name":"Alliés bestiaux","text":"Intimement liés à leurs animaux, qu''ils soignent et entraînent chaque jour, ils ont un unique animal compagnon, le plus souvent un berger allemand modifié au Kristall."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Hundemeister / Bestienmeister de la Nachtwölfe' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Berger allemand modifié au Kristall', 'Chien de combat augmenté', 'Compagnon du Hundemeister, ce berger allemand a été augmenté par les traitements au Blauer Kristall : yeux et crocs d''un bleu inquiétant, sens aiguisés, loyauté jusqu''à la mort. (VO : Kristall Modified Alsatian)', '["Troupe","Axe"]', 'Gamemaster Guide', 204, '{"rank":"trooper","truths":["Chien de combat augmenté"],"attributes":{"agility":11,"brawn":9,"coordination":5,"insight":10,"reason":5,"will":9},"skills":[{"key":"athletics","rank":3,"focuses":[]},{"key":"fighting","rank":3,"focuses":["Morsure"]},{"key":"observation","rank":2,"focuses":["Odorat et goût"]},{"key":"resilience","rank":2,"focuses":[]},{"key":"survival","rank":3,"focuses":["Pistage"]}],"stress":6,"injuries":1,"armour":1,"courage":2,"attacks":[{"name":"Morsure améliorée","focus":"Main nue","range":"contact","damage":4,"salvo":null,"qualities":"Perforant 1","escalation":false}],"abilities":[{"name":"Agrippant","text":"Après une attaque réussie, dépensez 1 Menace pour ajouter l''effet Piège. Tant qu''il tient une cible prise au piège, il ne peut pas attaquer d''autres cibles en mêlée, mais la difficulté de ses attaques contre la cible piégée baisse de 1."},{"name":"Sens aiguisés (odorat)","text":"La difficulté de tout test de compétence faisant appel à l''odorat baisse de 2 (minimum 0). Il peut détecter à l''odeur des choses imperceptibles pour un humain."},{"name":"Défendre jusqu''à la mort","text":"Très loyal envers son Hundemeister, il gagne +2 en Moral en sa présence. Si le Hundemeister est vaincu, le chien se précipite à ses côtés et le défend contre tout assaillant jusqu''à sa propre mort."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Berger allemand modifié au Kristall' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Troupes d''assaut de la Nachtwölfe', 'Super-soldat cybernétique d''assaut', 'L''une des premières tentatives de la Nachtwölfe pour allier Blauer Kristall et cybernétique afin de créer un super-soldat d''assaut et de combat rapproché. Démesurément grandis, dotés de bras renforcés, d''yeux de vision nocturne, de jambes bondissantes et de modifications respiratoires leur permettant de respirer en milieu hostile ou sous l''eau, ils portent une lourde armure et sont les premiers à s''engouffrer dans la brèche, hachette Sturmbolzenaxt et grenades à la main. (VO : Nachtwölfe Stormtroops)', '["Lieutenant","Axe"]', 'Gamemaster Guide', 205, '{"rank":"lieutenant","truths":["Soldat de choc cybernétique","Peut combattre n''importe où"],"attributes":{"agility":8,"brawn":12,"coordination":8,"insight":7,"reason":7,"will":9},"skills":[{"key":"athletics","rank":2,"focuses":[]},{"key":"engineering","rank":2,"focuses":["Génie mécanique"]},{"key":"fighting","rank":4,"focuses":["Armes lourdes","Fusils","Armes de mêlée"]},{"key":"medicine","rank":1,"focuses":[]},{"key":"resilience","rank":4,"focuses":[]},{"key":"survival","rank":2,"focuses":[]},{"key":"tactics","rank":1,"focuses":[]},{"key":"vehicles","rank":1,"focuses":[]}],"stress":17,"injuries":3,"armour":7,"courage":5,"attacks":[{"name":"Sturmgewehr 44 (StG 44)","focus":"Fusils","range":"medium","damage":5,"salvo":"Étourdissant","qualities":"Peu fiable","escalation":false},{"name":"Hachette de tranchée Sturmbolzenaxt","focus":"Armes de mêlée","range":"contact","damage":8,"salvo":null,"qualities":"Étourdissant, Fiable","escalation":false},{"name":"Stielhandgranate 24","focus":"Lancer","range":"close","damage":5,"salvo":null,"qualities":"Zone, Étourdissant, Munition","escalation":false}],"abilities":[{"name":"Optiques avancées","text":"Il peut relancer un d20 sur tout test d''Observation reposant sur la vue, et ignore toute hausse de difficulté due à la faible lumière ou à l''obscurité."},{"name":"Force extraordinaire 1","text":"1 succès automatique sur tous les tests de compétence basés sur la Force ; +1 aux attaques de mêlée, +1 en Armure et en stress maximum (déjà inclus)."},{"name":"Menaçant","text":"Quand il apparaît pour la première fois dans une scène, générez 1 point de Menace."},{"name":"Taille 1","text":"Il subit une blessure à partir de 6 points de stress (après réductions) en une seule attaque, au lieu de 5. Sa taille peut rendre certaines tâches plus faciles ou plus difficiles."},{"name":"Coriace 1","text":"Il supporte une blessure de plus que la normale (incluse). Il peut aussi dépenser 3 Menace pour ignorer une blessure qui lui est infligée."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Troupes d''assaut de la Nachtwölfe' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Garde du Loup de la Nachtwölfe (Wolfesgard)', 'Garde du corps d''élite de Mina Wolff', 'Commandée par l''austère Hauptmann Gerd Schmidt, la Garde du Loup réunit la crème de la Nachtwölfe et forme la garde personnelle de Mina Wolff. Fanatiquement loyaux, ces fantassins d''élite quittent rarement le Siège de Fenrir, sauf pour escorter Wolff ou mener une mission jugée vitale, avec accès aux armes expérimentales les plus récentes. (VO : Nachtwölfe Wolf Guard (Wolfesgard))', '["Lieutenant","Axe"]', 'Gamemaster Guide', 206, '{"rank":"lieutenant","truths":["Infanterie d''élite de Wolff","Garde du corps dévoué"],"attributes":{"agility":9,"brawn":12,"coordination":10,"insight":9,"reason":9,"will":10},"skills":[{"key":"academia","rank":1,"focuses":[]},{"key":"athletics","rank":2,"focuses":[]},{"key":"engineering","rank":1,"focuses":[]},{"key":"fighting","rank":3,"focuses":["Fusils"]},{"key":"medicine","rank":1,"focuses":[]},{"key":"observation","rank":1,"focuses":[]},{"key":"resilience","rank":2,"focuses":[]},{"key":"stealth","rank":1,"focuses":[]},{"key":"survival","rank":2,"focuses":[]},{"key":"tactics","rank":2,"focuses":[]},{"key":"vehicles","rank":1,"focuses":[]}],"stress":12,"injuries":2,"armour":6,"courage":4,"attacks":[{"name":"Sturmgewehr 44 (StG 44)","focus":"Fusils","range":"medium","damage":5,"salvo":"Étourdissant","qualities":"Peu fiable","escalation":false},{"name":"Hache du loup","focus":"Armes de mêlée","range":"contact","damage":6,"salvo":null,"qualities":"Vicieux","escalation":false}],"abilities":[{"name":"Augmenté","text":"Lourdement augmentés, ils ne subissent la Fatigue que par des effets magiques et récupèrent 1 point de stress à la fin de chacun de leurs tours tant qu''ils ne sont pas vaincus."},{"name":"Fidèle jusqu''à la mort","text":"En présence de Mina Wolff, ils gagnent +2 en Moral et la défendent jusqu''à la mort. Un Garde du Loup à son contact peut, par une réaction, détourner sur lui une attaque qui la vise."},{"name":"Armure de la Nachtwölfe","text":"Le plastron en alliage de Blauer Kristall accorde +2 de Couvert et +2 en Moral contre les attaques magiques hostiles, en plus de son indice d''Armure."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Garde du Loup de la Nachtwölfe (Wolfesgard)' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Generaloberst Mina Wolff, commandante de la Nachtwölfe', 'Cheffe suprême de la Nachtwölfe', 'Cheffe incontestée de la Nachtwölfe depuis sa défection du Soleil Noir, Mina Wolff a façonné les Loups de la nuit autour d''une foi quasi fanatique dans la technologie atlante du Blauer Kristall, poursuivant des buts connus d''elle seule. Elle paraît la fin de la vingtaine mais n''a pas changé depuis vingt ans, et ceux qui s''interrogent sur son âge disparaissent. Stratège infatigable, elle ne rend de comptes qu''au Führer. (VO : Generaloberst Mina Wolff, Nachtwölfe Commander)', '["Némésis","Axe"]', 'Gamemaster Guide', 207, '{"rank":"nemesis","truths":["Commandante suprême impitoyable de la Nachtwölfe","Passé mystérieux"],"attributes":{"agility":9,"brawn":9,"coordination":9,"insight":10,"reason":8,"will":12},"skills":[{"key":"academia","rank":3,"focuses":[]},{"key":"athletics","rank":2,"focuses":[]},{"key":"engineering","rank":1,"focuses":[]},{"key":"fighting","rank":3,"focuses":["Corps à corps"]},{"key":"medicine","rank":1,"focuses":[]},{"key":"observation","rank":3,"focuses":[]},{"key":"persuasion","rank":4,"focuses":[]},{"key":"resilience","rank":3,"focuses":[]},{"key":"tactics","rank":3,"focuses":[]},{"key":"vehicles","rank":1,"focuses":[]}],"stress":14,"injuries":3,"armour":2,"courage":6,"attacks":[{"name":"Walther P Series (P38)","focus":"Armes de poing","range":"close","damage":5,"salvo":"Vicieux","qualities":"Combat rapproché, Fiable","escalation":false},{"name":"Maschinenpistole Shewolfe","focus":"Corps à corps","range":"medium","damage":6,"salvo":"Étourdissant ou Vicieux","qualities":"Perforant 1, Fiable","escalation":false},{"name":"Die Blaue Reitgerte (la Cravache bleue)","focus":"Armes de mêlée","range":"contact","damage":3,"salvo":null,"qualities":"Étourdissant, Débilitant","escalation":false}],"abilities":[{"name":"Sorts et rituels","text":"Pouvoir 4. Lanceuse de sorts utilisant la Perception. Elle connaît tout sort celtique ou runique que le MJ veut lui donner, et tous les rituels dont elle a besoin. Elle use rarement de sorcellerie, et jamais en public."},{"name":"Vigueur infinie","text":"En plus de ne jamais vieillir visiblement, elle a une endurance sans limite : elle ne subit la Fatigue que par des effets magiques (coût des sorts compris) et récupère 1 point de stress au début de chacun de ses tours tant qu''elle n''est pas vaincue."},{"name":"Menaçante 3","text":"Quand elle entre dans une scène, elle génère immédiatement 3 points de Menace qu''elle seule peut utiliser."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Generaloberst Mina Wolff, commandante de la Nachtwölfe' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Oberstleutnant Oskar Richter, commandant du bataillon Wolfszahn', 'Commandant de la force de combat d''élite de la Nachtwölfe', 'L''un des sept Obersts du Cercle intérieur, Richter mène le bataillon Wolfszahn, la force d''élite de la Nachtwölfe. Cheveux blancs, 1,80 m, physique d''athlète, seul à avoir reçu le sérum Vitalität originel, il s''entraîne avec ses hommes qui le suivraient en enfer. Il délaisse l''uniforme d''officier pour commander en première ligne, entouré de spécialistes, de Stalkers et de Maîtres de force. (VO : Oberstleutnant Oskar Richter, Commander (Wolfszahn Battalion))', '["Némésis","Axe"]', 'Gamemaster Guide', 208, '{"rank":"nemesis","truths":["Guerrier redoutable","Commandant implacable sur le champ de bataille"],"attributes":{"agility":9,"brawn":11,"coordination":9,"insight":10,"reason":8,"will":9},"skills":[{"key":"academia","rank":1,"focuses":[]},{"key":"athletics","rank":2,"focuses":[]},{"key":"engineering","rank":2,"focuses":["Génie de combat"]},{"key":"fighting","rank":3,"focuses":["Main nue","Fusils","Armes lourdes"]},{"key":"medicine","rank":1,"focuses":[]},{"key":"observation","rank":1,"focuses":[]},{"key":"resilience","rank":1,"focuses":[]},{"key":"stealth","rank":1,"focuses":[]},{"key":"survival","rank":2,"focuses":[]},{"key":"tactics","rank":2,"focuses":["Tactique du champ de bataille"]},{"key":"vehicles","rank":1,"focuses":[]}],"stress":13,"injuries":4,"armour":4,"courage":2,"attacks":[{"name":"Jagdgewehr Sturmgewehr 43A","focus":"Fusils","range":"medium","damage":8,"salvo":"Vicieux","qualities":"Perforant 1, Fiable","escalation":false},{"name":"Panzerfaust intégré","focus":"Armes lourdes","range":"long","damage":7,"salvo":null,"qualities":"Perforant 1, Vicieux, Encombrant, Escalade, Tueur de géants, Imprécis, Munition","escalation":false},{"name":"Hachette de tranchée Sturmbolzenaxt","focus":"Armes de mêlée","range":"contact","damage":7,"salvo":null,"qualities":"Étourdissant, Fiable","escalation":false}],"abilities":[{"name":"Machine à tuer efficace","text":"Chaque fois qu''il fait une attaque en salve, il lance 1 dé de combat : sur un effet, la munition n''est pas dépensée."},{"name":"Force extraordinaire 1","text":"1 succès automatique sur tous les tests de compétence basés sur la Force ; +1 aux attaques de mêlée, +1 en Armure et en stress maximum (déjà inclus)."},{"name":"Récupération rapide 2","text":"Il récupère 2 points de stress à la fin de chacun de ses tours. S''il a des blessures au début de son tour, il peut dépenser 2 Menace pour en supprimer une entièrement. Cette capacité cesse dès qu''il est vaincu."},{"name":"Menaçant","text":"Quand il entre dans une scène, générez immédiatement 1 point de Menace."},{"name":"Prototype de Stalker","text":"Sans avoir la taille des Stalkers plus récents, il manie les armes lourdes aussi bien qu''eux : il ignore la qualité Lourd de toute arme (déjà retirée de ses armes)."},{"name":"Coriace 1","text":"Il supporte une blessure de plus que la normale (incluse). Il peut aussi dépenser 3 Menace pour ignorer une blessure qui lui est infligée."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Oberstleutnant Oskar Richter, commandant du bataillon Wolfszahn' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Hauptmann Gerd Schmidt, commandant de la Garde du Loup', 'Capitaine de la garde personnelle de Mina Wolff', 'Schmidt commande la Garde du Loup chargée de la sécurité de Mina, recrutée parmi les meilleurs spécialistes, Stalkers et Maîtres de force, avec pour priorité absolue d''empêcher tout agent du Soleil Noir ou allié de l''approcher. Image de la perfection aryenne au passé aussi mystérieux que celui de sa maîtresse, il a été nommé par Mina elle-même ; son visage de pierre et ses yeux insondables font dire que le diable veille sur elle. (VO : Hauptmann Gerd Schmidt, Commander (Wolf Guard))', '["Némésis","Axe"]', 'Gamemaster Guide', 209, '{"rank":"nemesis","truths":["Loyal","Féroce","Commandant prétorien"],"attributes":{"agility":11,"brawn":9,"coordination":9,"insight":10,"reason":8,"will":11},"skills":[{"key":"academia","rank":1,"focuses":[]},{"key":"athletics","rank":1,"focuses":[]},{"key":"engineering","rank":1,"focuses":[]},{"key":"fighting","rank":4,"focuses":["Fusils"]},{"key":"observation","rank":4,"focuses":["Vue","Ouïe","Instinct"]},{"key":"resilience","rank":2,"focuses":[]},{"key":"stealth","rank":3,"focuses":[]},{"key":"survival","rank":1,"focuses":[]},{"key":"tactics","rank":3,"focuses":["Commandement"]}],"stress":13,"injuries":3,"armour":2,"courage":4,"attacks":[{"name":"Walther P Series (P38)","focus":"Armes de poing","range":"close","damage":5,"salvo":"Vicieux","qualities":"Combat rapproché, Fiable","escalation":false},{"name":"Plaques de force atlantes","focus":"Corps à corps","range":"close","damage":7,"salvo":"Intense","qualities":"Étourdissant, Encombrant, Escalade, Tueur de géants","escalation":false},{"name":"Dague Eisenstachel","focus":"Armes de mêlée","range":"contact","damage":3,"salvo":null,"qualities":"Perforant 1","escalation":false}],"abilities":[{"name":"Augmenté","text":"Comme toute la Garde du Loup, il ne subit la Fatigue que par des effets magiques et récupère 1 point de stress à la fin de chacun de ses tours tant qu''il n''est pas vaincu."},{"name":"Maître de l''Eisenstachel","text":"Il manie sa lame Eisenstachel à distance grâce à ses plaques de force : pour 1 Menace, il peut la lancer et la récupérer par une action standard. C''est une attaque avec ses plaques de force, où Perforant 2 remplace l''effet Étourdissant et qui perd les qualités Encombrant et Tueur de géants."},{"name":"L''œil aux aguets","text":"Quiconque tente en sa présence un test pour se cacher ou se faire passer pour un autre voit la difficulté augmenter de +2."},{"name":"Menaçant","text":"Sa présence est intimidante : quand il apparaît dans une scène, générez immédiatement 1 point de Menace."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Hauptmann Gerd Schmidt, commandant de la Garde du Loup' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Professeur Kraft Heimburg', 'Ingénieur en chef de la Nachtwölfe', 'Ancien chef du laboratoire n° 7 de Wewelsburg, détruit lors de la première expérience de Mina, Heimburg a quitté le Soleil Noir avec elle, convaincu que la technologie des anciens est la clé d''un Troisième Reich mondial. Homme pratique, ancien apprenti ingénieur de la Grande Guerre passé par la Société Thulé, il développe l''équipement dont Mina a besoin. Depuis peu, il rêve d''étranges machines géométriques. (VO : Professor Kraft Heimburg)', '["Némésis","Axe"]', 'Gamemaster Guide', 210, '{"rank":"nemesis","truths":["Expert scientifique ésotérique","Ses rêves ne sont pas les siens"],"attributes":{"agility":8,"brawn":8,"coordination":8,"insight":9,"reason":11,"will":9},"skills":[{"key":"academia","rank":3,"focuses":["Occultisme","Science"]},{"key":"athletics","rank":1,"focuses":[]},{"key":"engineering","rank":5,"focuses":["Génie mécanique"]},{"key":"fighting","rank":2,"focuses":[]},{"key":"medicine","rank":3,"focuses":[]},{"key":"observation","rank":3,"focuses":["Vue"]},{"key":"persuasion","rank":1,"focuses":[]},{"key":"resilience","rank":1,"focuses":[]},{"key":"vehicles","rank":1,"focuses":[]}],"stress":10,"injuries":3,"armour":1,"courage":2,"attacks":[{"name":"Walther PPK à balles de Blauer Kristall","focus":"Armes de poing","range":"close","damage":4,"salvo":"Perforant 1 et Vicieux","qualities":"Fléau, Combat rapproché, Caché, Fiable","escalation":false}],"abilities":[{"name":"Infecté par Sarthothus","text":"À son insu, il est possédé par une part importante de la conscience de Sarthothus et œuvre en secret à la restauration du dieu brisé. Tout sort hostile qui le cible voit sa difficulté augmenter de +2."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Professeur Kraft Heimburg' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Auroch', 'Bovin géant ressuscité', 'Espèce de bovin géant éteinte depuis longtemps, ramenée à la vie par les expériences génétiques et la sélection des nazis, symbole de leur héritage aryen et gibier pour Hermann Göring. Bête d''une puissance et d''une résistance formidables ; on dit que de rares spécimens améliorés accompagnent un Bestienmeister de la Nachtwölfe.', '["Lieutenant","Autres"]', 'Gamemaster Guide', 212, '{"rank":"lieutenant","truths":["Animal de troupeau massif","Belliqueux"],"attributes":{"agility":7,"brawn":14,"coordination":5,"insight":9,"reason":3,"will":6},"skills":[{"key":"athletics","rank":2,"focuses":["Course"]},{"key":"fighting","rank":1,"focuses":[]},{"key":"observation","rank":2,"focuses":["Instinct"]},{"key":"resilience","rank":3,"focuses":["Endurance"]},{"key":"survival","rank":1,"focuses":[]}],"stress":18,"injuries":3,"armour":5,"courage":0,"attacks":[{"name":"Cornes et sabots piétinants","focus":"Main nue","range":"contact","damage":8,"salvo":null,"qualities":"","escalation":false}],"abilities":[{"name":"Brutal 1","text":"La créature attaque et se défend en mêlée avec la Force au lieu de l''Agilité, et ajoute +1 à ses attaques de mêlée (inclus)."},{"name":"Force extraordinaire 1","text":"1 succès automatique sur tous les tests de Force ; +1 aux attaques de mêlée, +1 en stress maximum et en Armure (déjà inclus)."},{"name":"Charge encornante","text":"Quand l''auroch réussit une attaque de mêlée juste après s''être déplacé au contact, ajoutez l''effet Intense aux dégâts."},{"name":"Taille 2","text":"Elle subit une blessure à partir de 7 points de stress (après réductions) en une seule attaque, au lieu de 5. Sa taille peut rendre d''autres tests plus faciles ou plus difficiles."},{"name":"Coriace 1","text":"Elle supporte une blessure de plus (incluse). Elle peut aussi dépenser 3 Menace pour ignorer une blessure."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Auroch' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Ours', 'Fauve solitaire', 'Féroce quand on le provoque mais souvent placide et méfiant envers ceux qui traversent son territoire, l''ours vit dans les forêts d''Europe du Nord, de Scandinavie et d''Amérique. Résistant et extrêmement puissant, il est mortel pour qui a le malheur de l''irriter. (VO : Bear)', '["Lieutenant","Autres"]', 'Gamemaster Guide', 213, '{"rank":"lieutenant","truths":["Bête solitaire et puissante","Territorial"],"attributes":{"agility":9,"brawn":14,"coordination":5,"insight":10,"reason":4,"will":9},"skills":[{"key":"athletics","rank":3,"focuses":["Escalade","Course"]},{"key":"fighting","rank":3,"focuses":[]},{"key":"observation","rank":4,"focuses":["Odorat et goût"]},{"key":"resilience","rank":2,"focuses":[]},{"key":"stealth","rank":1,"focuses":[]},{"key":"survival","rank":2,"focuses":["Pistage"]}],"stress":16,"injuries":3,"armour":4,"courage":1,"attacks":[{"name":"Griffes","focus":"Main nue","range":"contact","damage":7,"salvo":null,"qualities":"Débilitant","escalation":false},{"name":"Rugissement (attaque mentale)","focus":null,"range":null,"damage":4,"salvo":null,"qualities":"Perforant 1","escalation":false}],"abilities":[{"name":"Brutal 1","text":"La créature attaque et se défend en mêlée avec la Force au lieu de l''Agilité, et ajoute +1 à ses attaques de mêlée (inclus)."},{"name":"Effrayant 1","text":"La créature inspire la peur. Elle peut faire des attaques mentales, avec +1 et l''effet Perforant 1 (inclus ci-dessus). La première fois qu''un personnage la voit, il doit réussir un test de Volonté + Résilience de difficulté 1 ou subir du stress comme d''une attaque mentale."},{"name":"Sens aiguisés (odorat)","text":"La difficulté de tout test de compétence lié à l''odorat baisse de 2 (minimum 0). Elle peut détecter à l''odeur des choses imperceptibles pour un humain."},{"name":"Taille 2","text":"Elle subit une blessure à partir de 6 points de stress en une seule attaque, au lieu de 5 (valeur du livre). Sa taille peut rendre d''autres tests plus faciles ou plus difficiles."},{"name":"Coriace 1","text":"Elle supporte une blessure de plus (incluse). Elle peut aussi dépenser 3 Menace pour ignorer une blessure."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Ours' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Chauve-souris', 'Petit mammifère volant', 'Presque aveugles mais guidées par un sonar très évolué, les chauves-souris vivent partout en Europe et dans le monde. Les inventeurs militaires les plus ambitieux ou les plus détraqués ont même songé à s''en servir comme messagères ou pour livrer des bombes. (VO : Bat)', '["Troupe","Autres"]', 'Gamemaster Guide', 213, '{"rank":"trooper","truths":["Minuscule mammifère volant","Nocturne"],"attributes":{"agility":12,"brawn":4,"coordination":6,"insight":12,"reason":3,"will":4},"skills":[{"key":"athletics","rank":2,"focuses":["Vol"]},{"key":"observation","rank":4,"focuses":["Ouïe"]},{"key":"stealth","rank":3,"focuses":[]},{"key":"survival","rank":2,"focuses":[]}],"stress":2,"injuries":1,"armour":0,"courage":0,"attacks":[{"name":"Morsures et griffures","focus":"Main nue","range":"contact","damage":2,"salvo":null,"qualities":"Étourdissant","escalation":false}],"abilities":[{"name":"Écholocation","text":"Elle se dirige et perçoit précisément son environnement par écholocation ; l''obscurité ou la mauvaise visibilité ne la gênent pas."},{"name":"Vol","text":"Elle se déplace librement dans les zones aériennes au-dessus du champ de bataille. Porter des objets ou des créatures en vol peut demander un test d''Athlétisme + Force."},{"name":"Sens aiguisés (ouïe)","text":"La difficulté de tout test de compétence lié à l''ouïe baisse de 2 (minimum 0). Elle entend des choses imperceptibles pour un humain."},{"name":"Taille -2","text":"Elle subit une blessure à partir de 3 points de stress (après réductions) en une seule attaque, au lieu de 5. Sa taille peut rendre d''autres actions plus faciles ou plus difficiles."},{"name":"Essaim","text":"En groupe, les chauves-souris ajoutent l''effet Zone à leur attaque de mêlée."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Chauve-souris' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Chien', 'Chien dressé', 'Le meilleur ami de l''homme est tenace et loyal, et redoutable quand on le pousse ou qu''on le dresse à l''extrême. Tous les camps de la Guerre secrète l''emploient comme gardien et pisteur, mais toujours comme fidèle compagnon. (VO : Dog)', '["Troupe","Autres"]', 'Gamemaster Guide', 214, '{"rank":"trooper","truths":["Chien dressé","Compagnon loyal"],"attributes":{"agility":11,"brawn":9,"coordination":5,"insight":10,"reason":5,"will":9},"skills":[{"key":"athletics","rank":2,"focuses":[]},{"key":"fighting","rank":2,"focuses":[]},{"key":"observation","rank":3,"focuses":["Odorat et goût"]},{"key":"resilience","rank":1,"focuses":[]},{"key":"survival","rank":2,"focuses":["Pistage"]}],"stress":5,"injuries":1,"armour":1,"courage":2,"attacks":[{"name":"Morsure","focus":"Main nue","range":"contact","damage":3,"salvo":null,"qualities":"","escalation":false}],"abilities":[{"name":"Bon chien","text":"Très loyal envers ses maîtres, dresseurs et maîtres-chiens, il gagne +2 en Courage en leur présence. Si son maître est vaincu, il se précipite à ses côtés et le défend contre quiconque s''approche. Les chiens sauvages ou errants n''en bénéficient pas, sauf s''ils ont été apprivoisés par un personnage."},{"name":"Agrippant","text":"Après une attaque réussie, dépensez 1 Menace pour ajouter l''effet Piège. Tant qu''il tient une cible prise au piège, il ne peut pas attaquer d''autres cibles en mêlée, mais la difficulté de ses attaques contre elle baisse de 1."},{"name":"Sens aiguisés (odorat)","text":"La difficulté de tout test de compétence lié à l''odorat baisse de 2 (minimum 0). Il peut détecter à l''odeur des choses imperceptibles pour un humain."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Chien' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Aigle', 'Rapace', 'Oiseau d''une grâce, d''une puissance et d''une noblesse incroyables, l''aigle parcourt le ciel sur ses ailes immenses en quête de proies, armé d''un bec cruel et de serres redoutables. Certains peuvent être dressés à attaquer. (VO : Eagle)', '["Troupe","Autres"]', 'Gamemaster Guide', 214, '{"rank":"trooper","truths":["Oiseau de proie","Piqué prédateur"],"attributes":{"agility":12,"brawn":6,"coordination":6,"insight":12,"reason":5,"will":9},"skills":[{"key":"athletics","rank":3,"focuses":["Vol"]},{"key":"fighting","rank":1,"focuses":[]},{"key":"observation","rank":3,"focuses":["Vue"]},{"key":"resilience","rank":1,"focuses":[]}],"stress":4,"injuries":1,"armour":0,"courage":1,"attacks":[{"name":"Bec et serres déchirants","focus":"Main nue","range":"contact","damage":2,"salvo":null,"qualities":"Perforant 1","escalation":false}],"abilities":[{"name":"Perception extraordinaire 1","text":"La créature ajoute 1 succès automatique à tous ses tests de Perception."},{"name":"Vol","text":"Elle se déplace librement dans les zones aériennes au-dessus du champ de bataille. Porter des objets ou des créatures en vol peut demander un test d''Athlétisme + Force."},{"name":"Agrippant","text":"Après une attaque réussie, dépensez 1 Menace pour ajouter l''effet Piège. Tant qu''il tient une cible prise au piège, l''aigle ne peut pas attaquer d''autres cibles en mêlée, mais la difficulté de ses attaques contre elle baisse de 1."},{"name":"Sens aiguisés (vue)","text":"La difficulté de tout test de compétence lié à la vue baisse de 2 (minimum 0). Il distingue des choses à des distances bien supérieures à un humain."},{"name":"Taille -1","text":"Il subit une blessure à partir de 4 points de stress (après réductions) en une seule attaque, au lieu de 5. Sa taille peut rendre d''autres actions plus faciles ou plus difficiles."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Aigle' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Cheval', 'Monture et bête de trait', 'Fort, rapide et résistant, le cheval sert de monture à l''homme depuis des millénaires et tisse avec lui un lien solide. Selon les races, il court, se monte ou tire des chariots ; beaucoup servent pendant la Seconde Guerre mondiale à transporter vivres et munitions jusqu''au front. (VO : Horse)', '["Troupe","Autres"]', 'Gamemaster Guide', 215, '{"rank":"trooper","truths":["Bête de somme fiable","Compagnon robuste"],"attributes":{"agility":9,"brawn":12,"coordination":4,"insight":9,"reason":5,"will":8},"skills":[{"key":"athletics","rank":2,"focuses":["Course"]},{"key":"observation","rank":2,"focuses":[]},{"key":"resilience","rank":3,"focuses":["Endurance"]},{"key":"survival","rank":1,"focuses":[]}],"stress":8,"injuries":1,"armour":3,"courage":0,"attacks":[{"name":"Sabots piétinants","focus":"Main nue","range":"contact","damage":6,"salvo":null,"qualities":"Étourdissant","escalation":false}],"abilities":[{"name":"Brutal 1","text":"La créature attaque et se défend en mêlée avec la Force au lieu de l''Agilité, et ajoute +1 à ses attaques de mêlée (inclus)."},{"name":"Monture","text":"Un personnage peut le monter ; le cheval assiste alors ses tests d''Athlétisme et d''Observation. Les attaques contre un cavalier sont réparties au hasard entre monture et cavalier (1d20 : 1-10 monture, 11-20 cavalier). Si la monture est mise à terre ou vaincue, le cavalier tombe et subit un coup de l''attaque de mêlée normale de la monture."},{"name":"Taille 1","text":"Il subit une blessure à partir de 6 points de stress (après réductions) en une seule attaque, au lieu de 5. Sa taille peut rendre d''autres actions plus faciles ou plus difficiles."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Cheval' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Essaim d''insectes', 'Nuée d''insectes', 'Quand les insectes se rassemblent en grand nombre, ils prennent les traits d''une seule entité vivante. Mus par un soudain dessein collectif, ils tourbillonnent, étouffant ceux qui ont le malheur de les croiser. (VO : Insect Swarm)', '["Troupe","Autres"]', 'Gamemaster Guide', 215, '{"rank":"trooper","truths":["Nuée bourdonnante de créatures"],"attributes":{"agility":10,"brawn":4,"coordination":4,"insight":8,"reason":4,"will":9},"skills":[{"key":"athletics","rank":1,"focuses":["Vol"]},{"key":"observation","rank":2,"focuses":[]},{"key":"resilience","rank":1,"focuses":[]}],"stress":3,"injuries":1,"armour":3,"courage":1,"attacks":[{"name":"Piqûres et morsures","focus":"Main nue","range":"contact","damage":2,"salvo":null,"qualities":"Zone, Vidange","escalation":false},{"name":"Répulsion (attaque mentale)","focus":null,"range":null,"damage":4,"salvo":null,"qualities":"Perforant 1, Étourdissant","escalation":false}],"abilities":[{"name":"Effrayant 1","text":"La créature inspire la peur. Elle peut faire des attaques mentales, avec +1 et l''effet Perforant 1 (inclus ci-dessus). La première fois qu''un personnage la voit, il doit réussir un test de Volonté + Résilience de difficulté 1 ou subir du stress mental comme de cette attaque mentale."},{"name":"Vol","text":"Il se déplace librement dans les zones aériennes au-dessus du champ de bataille."},{"name":"Incorporel 3","text":"Diffus et difficile à blesser, l''essaim a 3 en Armure (inclus) et traverse librement les terrains accidentés ou difficiles. Pour 1 Menace, il trouve un passage à travers une barrière solide (mur, porte). Il perd son Armure contre toute attaque à effet Zone."},{"name":"Sans esprit","text":"Mû par le seul instinct, sans ordres il poursuit et attaque l''ennemi le plus proche. Il ne peut pas faire de réactions, ne subit ni stress ni blessures mentales, et on ne peut pas raisonner avec lui."},{"name":"Taille -2","text":"Il subit une blessure à partir de 3 points de stress (après réductions) en une seule attaque, au lieu de 5. Sa taille peut rendre d''autres actions plus faciles ou plus difficiles."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Essaim d''insectes' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Loup', 'Prédateur chassant en meute', 'Hantant les forêts et les montagnes d''Europe du Nord, les loups sont de redoutables chasseurs en meute, qui usent de leur nombre et de leur intelligence pour pister leur proie et la traquer jusqu''à l''épuisement. (VO : Wolf)', '["Troupe","Autres"]', 'Gamemaster Guide', 216, '{"rank":"trooper","truths":["Prédateur rusé","Chasse en meute"],"attributes":{"agility":11,"brawn":9,"coordination":6,"insight":10,"reason":5,"will":9},"skills":[{"key":"athletics","rank":2,"focuses":[]},{"key":"fighting","rank":2,"focuses":[]},{"key":"observation","rank":3,"focuses":["Odorat et goût"]},{"key":"resilience","rank":1,"focuses":[]},{"key":"stealth","rank":2,"focuses":[]},{"key":"survival","rank":2,"focuses":["Pistage"]}],"stress":5,"injuries":1,"armour":1,"courage":1,"attacks":[{"name":"Morsure","focus":"Main nue","range":"contact","damage":3,"salvo":null,"qualities":"","escalation":false},{"name":"Hurlement du loup (attaque mentale)","focus":null,"range":null,"damage":3,"salvo":null,"qualities":"Zone, Étourdissant","escalation":false}],"abilities":[{"name":"Agrippant","text":"Après une attaque réussie, dépensez 1 Menace pour ajouter l''effet Piège. Tant qu''il tient une cible prise au piège, le loup ne peut pas attaquer d''autres cibles en mêlée, mais la difficulté de ses attaques contre elle baisse de 1."},{"name":"Sens aiguisés (odorat)","text":"La difficulté de tout test de compétence lié à l''odorat baisse de 2 (minimum 0). Il peut détecter à l''odeur des choses imperceptibles pour un humain."},{"name":"Chasseur en meute","text":"Les loups gagnent autant de Moral que de loups présents dans la scène (5 au maximum). Contre une créature déjà attaquée par un ou plusieurs loups ce round, un loup peut relancer un d20."},{"name":"Hurlement du loup","text":"Les loups peuvent faire une attaque mentale (voir ci-dessus)."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Loup' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Nuée de rats', 'Vermine en nuée', 'Porteuses de maladies, les nuées de rats qui infestent les égouts des grandes villes, les tranchées et les fortifications peuvent devenir une menace aussi inattendue qu''horrible. Excitées par la faim, ou par quelque chose de plus sinistre, elles mordent et rongent la chair. (VO : Rat Swarm)', '["Troupe","Autres"]', 'Gamemaster Guide', 216, '{"rank":"trooper","truths":["Une masse de vermine","Morsures infectées"],"attributes":{"agility":9,"brawn":6,"coordination":6,"insight":9,"reason":5,"will":8},"skills":[{"key":"observation","rank":1,"focuses":[]},{"key":"resilience","rank":2,"focuses":[]},{"key":"survival","rank":1,"focuses":[]},{"key":"stealth","rank":1,"focuses":[]}],"stress":4,"injuries":1,"armour":1,"courage":0,"attacks":[{"name":"Multitude de petites morsures","focus":"Main nue","range":"contact","damage":2,"salvo":null,"qualities":"Zone","escalation":false}],"abilities":[{"name":"Incorporel 1","text":"Diffuse et difficile à blesser, la nuée a 1 en Armure (inclus) et traverse librement les terrains accidentés ou difficiles. Pour 1 Menace, elle trouve un passage à travers une barrière solide (mur, porte). Elle perd son Armure contre toute attaque à effet Zone."},{"name":"Sens aiguisés (odorat)","text":"La difficulté de tout test de compétence lié à l''odorat baisse de 2 (minimum 0). Elle peut détecter à l''odeur des choses imperceptibles pour un humain."},{"name":"Sans esprit","text":"Mue par le seul instinct, sans ordres elle poursuit et attaque l''ennemi le plus proche. Elle ne peut pas faire de réactions, ne subit ni stress ni blessures mentales, et on ne peut pas raisonner avec elle."},{"name":"Vision nocturne","text":"Elle voit dans l''obscurité : elle ignore toute hausse de difficulté ou de plage de complication due au manque de lumière, et peut tenter des tests normalement impossibles dans le noir."},{"name":"Taille -1","text":"Elle subit une blessure à partir de 4 points de stress (après réductions) en une seule attaque, au lieu de 5. Sa taille peut rendre d''autres actions plus faciles ou plus difficiles."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Nuée de rats' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Die Draugar', 'Masse de chair nécrotique réanimée', 'Fruits de la science démente de la Nachtwölfe, les Draugar (singulier : Draugr) sont des cadavres réanimés par une formule, le plus souvent un gaz. Sur les tissus vivants, l''effet est pire encore : la peau se flétrit, les os cassent, les organes se liquéfient et la victime meurt en quelques instants avant de revenir, conscience virale et prédatrice cherchant de la chair fraîche à ajouter à sa masse impie.', '["Lieutenant","Axe"]', 'Gamemaster Guide', 217, '{"rank":"lieutenant","truths":["Masse grouillante de chair nécrotique","Infecter et dévorer"],"attributes":{"agility":7,"brawn":11,"coordination":7,"insight":6,"reason":4,"will":9},"skills":[{"key":"athletics","rank":2,"focuses":[]},{"key":"fighting","rank":3,"focuses":["Main nue"]},{"key":"observation","rank":1,"focuses":[]},{"key":"resilience","rank":2,"focuses":[]},{"key":"survival","rank":1,"focuses":[]}],"stress":13,"injuries":2,"armour":4,"courage":3,"attacks":[{"name":"Étreinte nécrotique","focus":"Main nue","range":"contact","damage":4,"salvo":null,"qualities":"Persistant 5","escalation":false},{"name":"Présence terrifiante (attaque mentale)","focus":null,"range":null,"damage":5,"salvo":null,"qualities":"Perforant 2","escalation":false}],"abilities":[{"name":"Dévorer et grossir","text":"Quand il tue une créature à son contact, il peut absorber sa masse : il soigne aussitôt une blessure subie ou, s''il n''en a pas, gagne la vérité « masse nécrotique croissante », cumulable s''il continue de tuer (voir l''encadré Croissance monstrueuse)."},{"name":"Effrayant 2","text":"La créature inspire la peur. Elle peut faire des attaques mentales, avec +2 et l''effet Perforant 2 (inclus ci-dessus). La première fois qu''un personnage la voit, il doit réussir un test de Volonté + Résilience de difficulté 1 ou subir du stress mental comme de cette attaque mentale."},{"name":"Agrippant","text":"Après une attaque réussie, dépensez 1 Menace pour ajouter l''effet Piège. Tant qu''il tient une cible prise au piège, il ne peut pas attaquer d''autres cibles en mêlée, mais la difficulté de ses attaques contre elle baisse de 1."},{"name":"Arme biologique horrible","text":"Une créature tuée par un Draugr, y compris par les dégâts persistants qu''il a infligés, se réanime en Draugr au début du round suivant si elle n''a pas été dévorée."},{"name":"Sans esprit","text":"Mû par le seul instinct, sans ordres il poursuit et attaque l''ennemi le plus proche. Il ne peut pas faire de réactions, ne subit ni stress ni blessures mentales, et on ne peut pas raisonner avec lui."},{"name":"Non-vivant","text":"La créature n''est pas vraiment vivante : elle est immunisée à l''asphyxie, au poison et à la maladie, et ne subit pas de Fatigue."},{"name":"Croissance monstrueuse (encadré, option)","text":"Version détaillée de la croissance : à chaque croissance, il gagne un niveau de l''une de ces règles ; une fois les trois à 1, il peut les porter à 2. Force extraordinaire X (X succès automatiques aux tests de Force, +X aux attaques de mêlée, +X en stress maximum et en Armure), Taille X (blessure à partir de 5+X points de stress en une attaque), Coriace X (X blessures supplémentaires, 3 Menace pour ignorer une blessure). Utilisable aussi pour des versions géantes d''autres créatures."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Die Draugar' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Die Gefallenen (les Déchus)', 'Soldat mort-vivant du Soleil Noir', 'Le Soleil Noir a toujours besoin de soldats frais, pas intelligents, juste obéissants : des corps qui encaissent les balles. Les Gefallenen (« les Déchus ») sont des cadavres animés par les sorcelleries immondes du Soleil Noir, des morts si frais qu''on les croirait vivants aux carcasses boursouflées et grouillantes d''asticots qui semblent se désagréger à chaque pas. (VO : Die Gefallenen)', '["Troupe","Axe"]', 'Gamemaster Guide', 218, '{"rank":"trooper","truths":["Soldat mort-vivant","Agressivité sans esprit"],"attributes":{"agility":8,"brawn":11,"coordination":6,"insight":6,"reason":6,"will":9},"skills":[{"key":"athletics","rank":1,"focuses":[]},{"key":"fighting","rank":3,"focuses":["Main nue"]},{"key":"observation","rank":1,"focuses":[]},{"key":"resilience","rank":2,"focuses":[]},{"key":"survival","rank":1,"focuses":[]}],"stress":7,"injuries":1,"armour":4,"courage":1,"attacks":[{"name":"Mains agrippantes","focus":"Main nue","range":"contact","damage":4,"salvo":null,"qualities":"","escalation":false},{"name":"Présence terrifiante (attaque mentale)","focus":null,"range":null,"damage":4,"salvo":null,"qualities":"Perforant 1","escalation":false}],"abilities":[{"name":"Effrayant 1","text":"La créature inspire la peur. Elle peut faire des attaques mentales, avec +1 et l''effet Perforant 1 (inclus ci-dessus). La première fois qu''un personnage la voit, il doit réussir un test de Volonté + Résilience de difficulté 1 ou subir du stress mental comme de cette attaque mentale."},{"name":"Agrippant","text":"Après une attaque réussie, dépensez 1 Menace pour ajouter l''effet Piège. Tant qu''il tient une cible prise au piège, il ne peut pas attaquer d''autres cibles en mêlée, mais la difficulté de ses attaques contre elle baisse de 1."},{"name":"Tir à la tête","text":"Un attaquant peut viser la tête pour détruire le cerveau : la difficulté de l''attaque augmente de +1, mais l''attaque ignore entièrement l''Armure de la créature."},{"name":"Sans esprit","text":"Mû par le seul instinct, sans ordres il poursuit et attaque l''ennemi le plus proche. Il ne peut pas faire de réactions, ne subit ni stress ni blessures mentales, et on ne peut pas raisonner avec lui."},{"name":"Non-vivant","text":"La créature n''est pas vraiment vivante : elle est immunisée à l''asphyxie, au poison et à la maladie, et ne subit pas de Fatigue."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Die Gefallenen (les Déchus)' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Cadavre réanimé', 'Mort ramené à la vie par la science', 'Sorcellerie noire et science pervertie se sont unies pour vaincre la mort, mais ce qui revient de l''au-delà ne ressemble guère à ce qui était : là où vivait une intelligence ne reste qu''une soif de sang et de massacre. Créés d''abord par Herbert West, dont les secrets ont été volés par les chercheurs déments de la Nachtwölfe, ces morts sont jetés au combat pour y étancher leur soif. (VO : Reanimated Corpse)', '["Troupe","Axe"]', 'Gamemaster Guide', 219, '{"rank":"trooper","truths":["Cadavre animé","Instinct meurtrier"],"attributes":{"agility":6,"brawn":10,"coordination":6,"insight":6,"reason":4,"will":9},"skills":[{"key":"athletics","rank":1,"focuses":[]},{"key":"fighting","rank":2,"focuses":["Main nue"]},{"key":"observation","rank":1,"focuses":[]},{"key":"resilience","rank":2,"focuses":[]},{"key":"survival","rank":1,"focuses":[]}],"stress":7,"injuries":1,"armour":2,"courage":1,"attacks":[{"name":"Mains agrippantes","focus":"Main nue","range":"contact","damage":4,"salvo":null,"qualities":"","escalation":false},{"name":"Présence terrifiante (attaque mentale)","focus":null,"range":null,"damage":4,"salvo":null,"qualities":"Perforant 1","escalation":false}],"abilities":[{"name":"Effrayant 1","text":"La créature inspire la peur. Elle peut faire des attaques mentales, avec +1 et l''effet Perforant 1 (inclus ci-dessus). La première fois qu''un personnage la voit, il doit réussir un test de Volonté + Résilience de difficulté 1 ou subir du stress mental comme de cette attaque mentale."},{"name":"Agrippant","text":"Après une attaque réussie, dépensez 1 Menace pour ajouter l''effet Piège. Tant qu''il tient une cible prise au piège, il ne peut pas attaquer d''autres cibles en mêlée, mais la difficulté de ses attaques contre elle baisse de 1."},{"name":"Tir à la tête","text":"Un attaquant peut viser la tête pour détruire le cerveau : la difficulté de l''attaque augmente de +1, mais l''attaque ignore entièrement l''Armure de la créature."},{"name":"Sans esprit","text":"Mû par le seul instinct, sans ordres il poursuit et attaque l''ennemi le plus proche. Il ne peut pas faire de réactions, ne subit ni stress ni blessures mentales, et on ne peut pas raisonner avec lui."},{"name":"Non-vivant","text":"La créature n''est pas vraiment vivante : elle est immunisée à l''asphyxie, au poison et à la maladie, et ne subit pas de Fatigue."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Cadavre réanimé' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Enfants du sang', 'Essaim parasite des Contrées du Rêve', 'Essaim d''insectes attiré dans le monde éveillé par le Soleil Noir, les Enfants du sang sont en vérité des habitants des Contrées du Rêve. Ils encerclent leur cible et percent sa peau d''un proboscis acéré pour la vider de son sang en quelques minutes. Gorgé, l''adulte se décompose en lambeaux de chitine qui deviennent aussitôt des larves, prochaine génération de parasites. (VO : Bloodborn)', '["Troupe","Mythe"]', 'Gamemaster Guide', 220, '{"rank":"trooper","truths":["Essaim grouillant venu d''au-delà"],"attributes":{"agility":10,"brawn":8,"coordination":12,"insight":9,"reason":8,"will":8},"skills":[{"key":"athletics","rank":3,"focuses":["Vol"]},{"key":"fighting","rank":1,"focuses":[]},{"key":"resilience","rank":2,"focuses":["Discipline"]}],"stress":5,"injuries":1,"armour":2,"courage":1,"attacks":[{"name":"Coup de proboscis","focus":"Main nue","range":"contact","damage":3,"salvo":null,"qualities":"Vidange, Persistant 3, Perforant 1","escalation":false},{"name":"Nuée bourdonnante","focus":"Main nue","range":"close","damage":3,"salvo":null,"qualities":"Zone","escalation":false},{"name":"Bourdonnement troublant (attaque mentale)","focus":null,"range":null,"damage":3,"salvo":null,"qualities":"Perforant 1","escalation":false}],"abilities":[{"name":"Effrayant 1","text":"Les Enfants du sang inspirent la peur. Ils peuvent faire des attaques mentales, avec +1 et l''effet Perforant 1 (inclus ci-dessus). La première fois qu''un personnage les voit, il doit réussir un test de Volonté + Résilience de difficulté 1 ou subir du stress mental comme de cette attaque mentale."},{"name":"Vol","text":"Ils se déplacent librement dans les zones aériennes au-dessus du champ de bataille. Porter des objets ou des créatures en vol peut demander un test d''Athlétisme + Force."},{"name":"Frai","text":"Chaque fois qu''un Enfant du sang (ou un groupe) inflige une ou plusieurs blessures physiques, il peut dépenser 1 Menace pour faire naître aussitôt un Enfant du sang de plus (qui rejoint le groupe s''il y en a un)."},{"name":"Venin des rêves","text":"Les dégâts persistants infligés par le coup de proboscis ont l''effet Étourdissant."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Enfants du sang' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Êtres du froid', 'Spectre de glace et de neige', 'Mus par une vitesse surnaturelle, chacun de leurs gestes accompagné du gémissement de la banquise sous la contrainte, les Êtres du froid sont faits de glace et de neige. Ils forment des lames de glace de n''importe quelle partie de leur corps ou arrachent la chair par des jets de cristaux. Créatures de pure sorcellerie au service des Grands Anciens, ils surgissent du blizzard, massacrent tout ce qu''ils croisent et se dissipent dans le vent. (VO : Cold Ones)', '["Lieutenant","Mythe"]', 'Gamemaster Guide', 221, '{"rank":"lieutenant","truths":["Spectres de glace et de neige"],"attributes":{"agility":11,"brawn":8,"coordination":9,"insight":10,"reason":10,"will":11},"skills":[{"key":"fighting","rank":2,"focuses":["Main nue"]},{"key":"stealth","rank":5,"focuses":["Discrétion rurale"]},{"key":"resilience","rank":2,"focuses":["Discipline"]}],"stress":13,"injuries":2,"armour":5,"courage":3,"attacks":[{"name":"Toucher glacial","focus":"Main nue","range":"contact","damage":4,"salvo":null,"qualities":"Vidange, Perforant 1, Étourdissant","escalation":false},{"name":"Plainte terrifiante (attaque mentale)","focus":null,"range":null,"damage":5,"salvo":null,"qualities":"Intense, Perforant 1, Étourdissant","escalation":false}],"abilities":[{"name":"Effrayant 1","text":"Les Êtres du froid inspirent la peur. Ils peuvent faire des attaques mentales, avec +1 et l''effet Perforant 1 (inclus ci-dessus). La première fois qu''un personnage en voit un, il doit réussir un test de Volonté + Résilience de difficulté 1 ou subir du stress mental comme de cette attaque mentale."},{"name":"Vol","text":"Ils se déplacent librement dans les zones aériennes au-dessus du champ de bataille. Porter des objets ou des créatures en vol peut demander un test d''Athlétisme + Force."},{"name":"Aura glaciale","text":"Tout personnage qui termine son tour à portée courte d''un Être du froid subit automatiquement 1 Fatigue due au froid intense. Cette Fatigue ne s''élimine qu''en se retirant au moins une heure dans un lieu chaud et abrité."},{"name":"Explosion de glace","text":"Vaincu, il explose en une bouffée de froid intense qui inflige 5 points de stress physique, avec les effets Vidange et Perforant 1, à toutes les créatures à portée courte."},{"name":"Camouflage de glace","text":"Presque invisible dans la glace et la neige, où il n''apparaît que comme une brume givrée : en conditions neigeuses ou glacées, il obtient deux succès automatiques à ses tests de Discrétion."},{"name":"Immunisé au froid, à la maladie, à la peur et au poison","text":"Il est immunisé au stress, aux vérités et aux autres effets causés par ces conditions."},{"name":"Incorporel 5","text":"Créature de glace, de neige et de malveillance gelée, intangible comme un vent glacé : 5 en Armure (inclus), déplacement libre en terrain accidenté ou difficile ; pour 1 Menace, il traverse une barrière solide (mur, porte). Il perd son Armure contre le feu et la chaleur intense."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Êtres du froid' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Couleur tombée du ciel', 'Entité lumineuse venue d''au-delà du cosmos', 'Un être presque indescriptible qui s''insinue dans l''esprit de ceux qui y sont exposés, ravage leur corps et érode leur être même. Un gaz ? Un fragment spectral de lumière venu d''un univers aux lois physiques autres ? La Nachtwölfe aurait sacrifié plus que des vies pour percer la vraie nature de ces êtres. (VO : Colour Out of Space)', '["Lieutenant","Mythe"]', 'Gamemaster Guide', 222, '{"rank":"lieutenant","truths":["Luminescence impossible venue d''au-delà du cosmos","Insubstantielle et pourtant trop réelle"],"attributes":{"agility":10,"brawn":null,"coordination":12,"insight":6,"reason":9,"will":10},"skills":[{"key":"fighting","rank":2,"focuses":[]},{"key":"observation","rank":4,"focuses":["Instinct"]},{"key":"resilience","rank":3,"focuses":["Discipline"]}],"stress":13,"injuries":2,"armour":10,"courage":5,"attacks":[{"name":"Absorption","focus":"Exotique","range":"contact","damage":5,"salvo":null,"qualities":"Vidange, Étourdissant","escalation":false},{"name":"Étreinte translucide (voir Devenir tangible)","focus":"Exotique","range":"contact","damage":4,"salvo":null,"qualities":"Piège","escalation":false},{"name":"Désintégration (voir Désintégrer)","focus":"Exotique","range":"close","damage":6,"salvo":null,"qualities":"Intense, Perforant 2","escalation":false},{"name":"Assaut mental (attaque mentale)","focus":null,"range":null,"damage":6,"salvo":null,"qualities":"Vidange, Perforant 2","escalation":false}],"abilities":[{"name":"Devenir tangible","text":"Pour 1 Menace, elle rend une partie d''elle-même tangible : cet appendice translucide saisit et manipule les objets solides comme avec une Force de 10. Tant qu''elle est partiellement tangible, elle dispose de l''attaque Étreinte translucide."},{"name":"Désintégrer","text":"Pour 2 Menace, elle se concentre et se désintègre à travers la matière solide à portée courte, avec l''attaque à distance Désintégration."},{"name":"Effrayant 2","text":"La créature inspire la peur. Elle peut faire des attaques mentales, avec +2 et l''effet Perforant 2 (inclus ci-dessus). La première fois qu''un personnage la voit, il doit réussir un test de Volonté + Résilience de difficulté 2 ou subir du stress mental comme de cette attaque mentale."},{"name":"Se nourrir de la peur","text":"Chaque fois qu''un personnage à portée moyenne subit une blessure mentale, générez 2 Menace."},{"name":"Se nourrir","text":"Quand elle inflige une blessure, elle peut dépenser 3 Menace pour gagner Taille 1 et Coriace 1, ou les augmenter de +1 si elle les a déjà. Si elle subit une blessure, elle réduit à la place Taille et Coriace de 1 chacune (supprimées à 0), si elle les a."},{"name":"Vol","text":"Elle se déplace librement dans les zones aériennes au-dessus du champ de bataille. Porter des objets ou des créatures en vol peut demander un test d''Athlétisme + Force."},{"name":"Immunisée au froid, à la maladie, à la peur, à la douleur, au poison, à la chaleur et au vide","text":"Elle est immunisée au stress, aux vérités et aux autres effets causés par ces conditions."},{"name":"Incorporel 10","text":"Sans substance corporelle telle que nous l''entendons : 10 en Armure (inclus), déplacement libre en terrain accidenté ou difficile ; pour 1 Menace, elle traverse une barrière solide (mur, porte). Elle perd son Armure contre les attaques magiques, les armes à qualité Fléau, les attaques électriques et les fortes sources magnétiques."},{"name":"Invulnérable","text":"Elle ne peut subir de blessure d''aucune attaque physique, sauf attaques magiques, armes à qualité Fléau, attaques électriques ou champs magnétiques puissants."},{"name":"Photophobe","text":"Elle fuit la lumière vive ; en pleine lumière, la difficulté de tous ses tests de compétence augmente de +1."},{"name":"Menaçante 3","text":"Quand elle apparaît pour la première fois dans une scène, elle génère 3 points de Menace qu''elle seule peut utiliser."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Couleur tombée du ciel' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Cultiste des Dieux anciens', 'Sorcier dégénéré au service des puissances anciennes', 'Les cultistes des Dieux anciens représentent des puissances antiques et mènent leurs adorateurs sur Terre, invoquant toutes sortes de créatures du Mythe. S''ils ont été humains, il n''en reste presque rien : le contact de leurs maîtres a fait de leur corps une imitation immonde de leurs divinités, chair visqueuse sous la robe, doigts grotesques serrant le bâton d''invocation, visage de tentacules autour d''un œil unique. (VO : Cultist of the Old Gods)', '["Lieutenant","Mythe"]', 'Gamemaster Guide', 222, '{"rank":"lieutenant","truths":["Serviteurs immondes des puissances anciennes","Démon sorcier dégénéré"],"attributes":{"agility":8,"brawn":12,"coordination":9,"insight":12,"reason":9,"will":12},"skills":[{"key":"academia","rank":3,"focuses":["Occultisme"]},{"key":"fighting","rank":1,"focuses":[]},{"key":"persuasion","rank":2,"focuses":["Invocation"]},{"key":"resilience","rank":3,"focuses":["Discipline"]},{"key":"survival","rank":2,"focuses":["Mysticisme"]}],"stress":15,"injuries":2,"armour":3,"courage":6,"attacks":[{"name":"Bâton du Mythe","focus":"Armes de mêlée","range":"contact","damage":7,"salvo":null,"qualities":"Étourdissant","escalation":false}],"abilities":[{"name":"Menaçant","text":"Sa simple présence est de mauvais augure : quand il apparaît pour la première fois dans une scène, générez 1 point de Menace."},{"name":"Sorts et rituels","text":"Pouvoir 6. Lanceur de sorts utilisant la Volonté ; il connaît jusqu''à trois sorts choisis par le MJ dans les traditions de Cthulhu, Nyarlathotep ou Yog-Sothoth."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Cultiste des Dieux anciens' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Choses très anciennes', 'Ancienne race de bâtisseurs et de savants', 'Jadis maîtres de la Terre, les Choses très anciennes au corps en forme de tonneau sont des savants et des explorateurs à la technologie bien supérieure à la nôtre. Beaucoup ont quitté la Terre après la grande guerre civile contre les Shoggoths, leurs anciens esclaves devenus conscients. Quelques-unes hibernent encore dans des cités cachées et s''éveillent parfois pour mener de curieuses expériences, aux buts insondables. (VO : Elder Things)', '["Lieutenant","Mythe"]', 'Gamemaster Guide', 223, '{"rank":"lieutenant","truths":["Bâtisseurs d''empire et savants vieux de plusieurs éons"],"attributes":{"agility":10,"brawn":12,"coordination":9,"insight":12,"reason":12,"will":12},"skills":[{"key":"academia","rank":3,"focuses":["Occultisme"]},{"key":"athletics","rank":1,"focuses":[]},{"key":"fighting","rank":4,"focuses":["Main nue"]},{"key":"observation","rank":2,"focuses":[]},{"key":"resilience","rank":3,"focuses":["Discipline"]},{"key":"tactics","rank":2,"focuses":[]},{"key":"vehicles","rank":1,"focuses":[]}],"stress":16,"injuries":4,"armour":9,"courage":6,"attacks":[{"name":"Tentacules fouettants","focus":"Main nue","range":"contact","damage":5,"salvo":null,"qualities":"","escalation":false},{"name":"Étreinte broyante (cibles agrippées seulement)","focus":"Main nue","range":"contact","damage":5,"salvo":null,"qualities":"Intense, Vicieux","escalation":false},{"name":"Présence troublante (attaque mentale)","focus":null,"range":null,"damage":6,"salvo":null,"qualities":"Perforant 1, Étourdissant","escalation":false}],"abilities":[{"name":"Sorts et rituels","text":"Pouvoir 7. Leur compréhension de la réalité ressemble à de la sorcellerie : elles sont traitées comme des lanceuses de sorts utilisant la Raison et connaissent jusqu''à quatre sorts de la liste PES et talents psychiques."},{"name":"Raison extraordinaire 2","text":"2 succès automatiques à tous les tests de Raison ; +2 au Pouvoir (inclus)."},{"name":"Effrayant 1","text":"La créature inspire la peur. Elle peut faire des attaques mentales, avec +1 et l''effet Perforant 1 (inclus ci-dessus). La première fois qu''un personnage la voit, il doit réussir un test de Volonté + Résilience de difficulté 1 ou subir du stress mental comme de cette attaque mentale."},{"name":"Vol","text":"Elles volent et se déplacent librement dans les zones aériennes au-dessus du champ de bataille. Porter des objets ou des créatures en vol peut demander un test d''Athlétisme + Force."},{"name":"Agrippant","text":"Après une attaque réussie, elle peut dépenser 1 Menace pour ajouter l''effet Piège. Tant qu''elle tient une cible prise au piège, elle ne peut pas attaquer d''autres cibles en mêlée, mais la difficulté de ses attaques contre elle baisse de 1."},{"name":"Immunisées au froid, à la maladie, à la douleur, au poison et au vide","text":"Elles sont immunisées au stress, aux vérités et aux autres effets causés par ces conditions."},{"name":"Coriace 2","text":"Elles supportent 2 blessures de plus (incluses) et peuvent dépenser 3 Menace pour ignorer une blessure."},{"name":"Taille 2","text":"Elles subissent une blessure à partir de 7 points de stress (après réductions) en une seule attaque, au lieu de 5. Leur taille peut rendre d''autres actions plus faciles ou plus difficiles."},{"name":"Les anciens maîtres","text":"Les annales interdites disent que les Choses très anciennes ont créé l''homme par plaisanterie, d''où une crainte atavique qui pousse à les servir. Quand un humain subit une ou plusieurs blessures mentales de leur part, la difficulté de tout test pour attaquer ou nuire à une Chose très ancienne augmente de 1 par blessure mentale subie, jusqu''à la fin de la scène."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Choses très anciennes' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Goules', 'Mangeurs de cadavres', 'Charognards vivant sur Terre comme dans les Contrées du Rêve, les goules surgissent pour se repaître des morts partout où règne la mort. On ignore si toutes étaient humaines, mais la transformation est possible et la Section M surveille ses agents qui les ont côtoyées. Peau grise et caoutchouteuse, traits de chien rabougri, elles attaquent en nombre ; elles ne sont pas sans esprit et l''on peut traiter avec elles, au prix souvent des cadavres d''anciens amis. (VO : Ghouls)', '["Troupe","Mythe"]', 'Gamemaster Guide', 224, '{"rank":"trooper","truths":["Répugnants mangeurs de cadavres"],"attributes":{"agility":9,"brawn":10,"coordination":10,"insight":7,"reason":9,"will":9},"skills":[{"key":"athletics","rank":3,"focuses":["Escalade"]},{"key":"fighting","rank":2,"focuses":["Main nue"]},{"key":"observation","rank":2,"focuses":["Odorat et goût"]},{"key":"stealth","rank":2,"focuses":[]},{"key":"resilience","rank":1,"focuses":[]}],"stress":6,"injuries":1,"armour":3,"courage":2,"attacks":[{"name":"Griffes et crocs lacérants","focus":"Main nue","range":"contact","damage":4,"salvo":null,"qualities":"","escalation":false},{"name":"Odeur de tombe (attaque mentale)","focus":null,"range":null,"damage":4,"salvo":null,"qualities":"Perforant 1, Étourdissant","escalation":false}],"abilities":[{"name":"Effrayant 1","text":"Les goules inspirent la peur. Elles peuvent faire des attaques mentales, avec +1 et l''effet Perforant 1 (inclus ci-dessus). La première fois qu''un personnage en voit une, il doit réussir un test de Volonté + Résilience de difficulté 1 ou subir du stress mental comme de cette attaque mentale."},{"name":"Agrippant","text":"Après une attaque réussie, dépensez 1 Menace pour ajouter l''effet Piège. Tant qu''elle tient une cible prise au piège, la goule ne peut pas attaquer d''autres cibles en mêlée, mais la difficulté de ses attaques contre elle baisse de 1."},{"name":"Immunisées au froid, à la maladie, à la douleur, au poison et au vide","text":"Elles sont immunisées au stress, aux vérités et aux autres effets causés par ces conditions."},{"name":"Déchirer","text":"Si une goule réussit une attaque de mêlée, elle peut dépenser 1 Menace pour ajouter l''effet Vicieux aux dégâts."},{"name":"Physiologie étrange","text":"Son Armure augmente de +2 contre les attaques à distance."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Goules' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Démon voletant', 'Horreur volante', 'Amalgame hideux et difforme de corneille, de taupe et d''autres créatures moins avouables et moins terrestres, le Démon voletant est la terreur de qui s''aventure dans les airs. Ses ailes malsaines portent un corps nauséabond qui tournoie et culbute dans l''air, déchirant et lacérant, sans autre but que la chair tendre. (VO : Fluttering Fiend)', '["Lieutenant","Mythe"]', 'Gamemaster Guide', 225, '{"rank":"lieutenant","truths":["Choses battantes contre nature","Indescriptible"],"attributes":{"agility":12,"brawn":11,"coordination":8,"insight":4,"reason":6,"will":6},"skills":[{"key":"athletics","rank":2,"focuses":["Vol"]},{"key":"fighting","rank":1,"focuses":[]},{"key":"observation","rank":3,"focuses":["Ouïe"]},{"key":"resilience","rank":2,"focuses":[]}],"stress":13,"injuries":2,"armour":4,"courage":2,"attacks":[{"name":"Coup de griffe maladroit","focus":"Main nue","range":"contact","damage":4,"salvo":null,"qualities":"","escalation":false},{"name":"Morsure cruelle (voir Morsure vampirique)","focus":"Main nue","range":"contact","damage":4,"salvo":null,"qualities":"Piège","escalation":false},{"name":"Forme hideuse (attaque mentale)","focus":null,"range":null,"damage":3,"salvo":null,"qualities":"Perforant 1","escalation":false}],"abilities":[{"name":"Anatomie bizarre","text":"L''étrange agencement de sa chair et de ses membres fait qu''il ne peut jamais être mis à terre."},{"name":"Effrayant 1","text":"La créature inspire la peur. Elle peut faire des attaques mentales, avec +1 et l''effet Perforant 1 (inclus ci-dessus). La première fois qu''un personnage la voit, il doit réussir un test de Volonté + Résilience de difficulté 1 ou subir du stress mental comme de cette attaque mentale."},{"name":"Vol","text":"Il se déplace librement dans les zones aériennes au-dessus du champ de bataille. Porter des objets ou des créatures en vol peut demander un test d''Athlétisme + Force."},{"name":"Taille 1","text":"Il subit une blessure à partir de 6 points de stress (après réductions) en une seule attaque, au lieu de 5. Sa taille peut rendre d''autres actions plus faciles ou plus difficiles."},{"name":"Morsure vampirique","text":"Contre une créature qu''il tient prise au piège, sa morsure gagne les effets Vidange et Perforant 1."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Démon voletant' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Grande Race de Yith', 'Collectionneurs de savoir voyageant par l''esprit', 'Capables de projeter leur esprit à travers le temps et l''espace en déplaçant la conscience d''autres êtres, les Yithiens sont décrits comme de grands cônes rugueux à tentacules préhensiles terminés par des pinces. Ils accumulent le savoir dans des bibliothèques cachées et manient des armes capables de réduire un ennemi en atomes. Leur guerre éternelle contre les Polypes volants a parfois débordé sur la Guerre secrète, laissant des agents de la Section M ne plus savoir parler ni se nommer. (VO : Great Race of Yith)', '["Lieutenant","Mythe"]', 'Gamemaster Guide', 225, '{"rank":"lieutenant","truths":["Mystérieux collectionneurs de savoir"],"attributes":{"agility":6,"brawn":14,"coordination":10,"insight":16,"reason":14,"will":12},"skills":[{"key":"academia","rank":5,"focuses":[]},{"key":"fighting","rank":2,"focuses":["Exotique"]},{"key":"observation","rank":3,"focuses":[]},{"key":"resilience","rank":3,"focuses":["Discipline"]},{"key":"tactics","rank":2,"focuses":[]}],"stress":17,"injuries":3,"armour":4,"courage":5,"attacks":[{"name":"Pince préhensile","focus":"Main nue","range":"contact","damage":6,"salvo":null,"qualities":"Perforant 1","escalation":false},{"name":"Arme à disruption électrique","focus":"Exotique","range":"medium","damage":9,"salvo":"Vicieux","qualities":"Intense","escalation":false},{"name":"Présence surnaturelle (attaque mentale)","focus":null,"range":null,"damage":6,"salvo":null,"qualities":"Perforant 1","escalation":false}],"abilities":[{"name":"Raison extraordinaire 2","text":"La créature ajoute 2 succès automatiques à tous ses tests de Raison."},{"name":"Effrayant 1","text":"La Grande Race inspire la peur. Elle peut faire des attaques mentales, avec +1 et l''effet Perforant 1 (inclus ci-dessus). La première fois qu''un personnage en voit un, il doit réussir un test de Volonté + Résilience de difficulté 1 ou subir du stress mental comme de cette attaque mentale."},{"name":"Échange d''esprit","text":"Par leur science avancée, ils échangent leur conscience avec un sujet humain à travers le temps et l''espace, comme le rituel Échange d''esprit, qu''ils accomplissent comme des lanceurs de sorts utilisant la Raison avec un Pouvoir de 8. L''échange est permanent tant que le lanceur n''y met pas fin."},{"name":"Taille 3","text":"Elle subit une blessure à partir de 8 points de stress (après réductions) en une seule attaque, au lieu de 5. Sa taille peut rendre d''autres actions plus faciles ou plus difficiles."},{"name":"Coriace 1","text":"Elle supporte une blessure de plus (incluse) et peut dépenser 3 Menace pour ignorer une blessure."},{"name":"Savoir immense","text":"Le MJ peut accorder aux membres de la Grande Race tous les focus d''Érudition qu''il souhaite. Ils peuvent aussi relancer un d20 sur tout test d''Érudition."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Grande Race de Yith' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Halja', 'Esprit arctique du blizzard', 'Étranges esprits arctiques surgis des blizzards, les Halja sont appelées « filles du vent » ou « épouses du Wendigo ». Ceux qui les ont vues dans la tempête leur prêtent une silhouette féminine aux longs cheveux soyeux et aux robes vaporeuses, mais on ne les voit souvent qu''à l''instant où elles frappent. Le Soleil Noir les a parfois invoquées comme troupes de choc quasi invisibles, surtout dans les climats les plus froids.', '["Lieutenant","Mythe"]', 'Gamemaster Guide', 226, '{"rank":"lieutenant","truths":["Épouses gelées du Wendigo","Le blizzard cruel fait chair"],"attributes":{"agility":12,"brawn":9,"coordination":11,"insight":9,"reason":6,"will":11},"skills":[{"key":"fighting","rank":3,"focuses":["Main nue"]},{"key":"stealth","rank":5,"focuses":["Discrétion rurale"]},{"key":"resilience","rank":2,"focuses":[]}],"stress":13,"injuries":2,"armour":7,"courage":4,"attacks":[{"name":"Serres déchirantes","focus":"Main nue","range":"contact","damage":5,"salvo":null,"qualities":"Vidange","escalation":false},{"name":"Horrifique (attaque mentale)","focus":null,"range":null,"damage":5,"salvo":null,"qualities":"Perforant 1","escalation":false}],"abilities":[{"name":"Coalescence","text":"La Halja ne prend brièvement forme physique qu''au moment d''attaquer. Si un ennemi remporte un test opposé contre son attaque de mêlée, les dégâts qu''il inflige peuvent ignorer sa règle Incorporel (et les 4 points d''Armure qu''elle accorde, selon le livre)."},{"name":"Rapidité mortelle","text":"Terriblement rapide, elle ajoute +1 à la difficulté de toutes les attaques à distance contre elle. Si une attaque à distance la rate, elle peut aussitôt dépenser 1 Menace pour faire une action mineure de mouvement."},{"name":"Agilité extraordinaire 1","text":"La créature ajoute 1 succès automatique à tous ses tests d''Agilité."},{"name":"Effrayant 1","text":"La Halja inspire la peur. Elle peut faire des attaques mentales, avec +1 et l''effet Perforant 1 (inclus ci-dessus). La première fois qu''un personnage la voit, il doit réussir un test de Volonté + Résilience de difficulté 1 ou subir du stress mental comme de cette attaque mentale."},{"name":"Immunisée au froid, à la maladie, à la peur et au poison","text":"Elle est immunisée au stress, aux vérités et aux autres effets causés par ces conditions."},{"name":"Incorporel 6","text":"Faite de brume glaciale : 6 en Armure (inclus, selon le livre), déplacement libre en terrain accidenté ou difficile ; pour 1 Menace, elle traverse une barrière solide (mur, porte). Elle perd son Armure contre les attaques magiques et contre le feu ou la chaleur extrême."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Halja' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Maigres bêtes de la nuit', 'Horreur sans visage des Contrées du Rêve', 'Visage lisse et sans traits tendu d''une peau de cuir, cornes au front, ailes de chauve-souris portant un corps allongé, les Maigres bêtes de la nuit sont des monstruosités du monde des Rêves. Créatures capricieuses au service des étranges divinités d''au-delà, leurs longues serres chatouillent ou déchiquettent les mortels selon le bon vouloir de leurs maîtres ; on peut aussi les apprivoiser comme montures pour parcourir le cosmos. (VO : Night Gaunts)', '["Lieutenant","Mythe"]', 'Gamemaster Guide', 227, '{"rank":"lieutenant","truths":["Horreurs sans visage du royaume des Rêves"],"attributes":{"agility":13,"brawn":9,"coordination":12,"insight":9,"reason":7,"will":9},"skills":[{"key":"athletics","rank":2,"focuses":["Vol"]},{"key":"fighting","rank":3,"focuses":["Main nue"]},{"key":"observation","rank":2,"focuses":[]},{"key":"persuasion","rank":3,"focuses":["Intimidation"]},{"key":"resilience","rank":2,"focuses":["Discipline"]},{"key":"stealth","rank":5,"focuses":["Discrétion rurale"]}],"stress":11,"injuries":2,"armour":3,"courage":3,"attacks":[{"name":"Serres effilées","focus":"Main nue","range":"contact","damage":4,"salvo":null,"qualities":"Perforant 1","escalation":false},{"name":"Menace cauchemardesque (attaque mentale)","focus":null,"range":null,"damage":4,"salvo":null,"qualities":"Perforant 1, Étourdissant","escalation":false}],"abilities":[{"name":"Effrayant 1","text":"La créature inspire la peur. Elle peut faire des attaques mentales, avec +1 et l''effet Perforant 1 (inclus ci-dessus). La première fois qu''un personnage la voit, il doit réussir un test de Volonté + Résilience de difficulté 1 ou subir du stress mental comme de cette attaque mentale."},{"name":"Se nourrir de la peur","text":"Chaque fois qu''un personnage à portée moyenne subit une blessure mentale, générez 2 Menace."},{"name":"Vol","text":"Elle se déplace librement dans les zones aériennes au-dessus du champ de bataille. Porter des objets ou des créatures en vol peut demander un test d''Athlétisme + Force, plutôt facile car elles ont l''habitude de servir de montures."},{"name":"Agrippant","text":"Après une attaque réussie, dépensez 1 Menace pour ajouter l''effet Piège. Tant qu''elle tient une cible prise au piège, elle ne peut pas attaquer d''autres cibles en mêlée, mais la difficulté de ses attaques contre elle baisse de 1."},{"name":"Immunisée au froid, à la maladie, à la peur, au poison et au vide","text":"Elle est immunisée au stress, aux vérités et aux autres effets causés par ces conditions."},{"name":"Vision nocturne","text":"Elle voit dans l''obscurité : elle ignore toute hausse de difficulté ou de plage de complication due au manque de lumière, et peut tenter des tests normalement impossibles dans le noir."},{"name":"Taille 1","text":"Elle subit une blessure à partir de 6 points de stress (après réductions) en une seule attaque, au lieu de 5. Sa taille peut rendre d''autres actions plus faciles ou plus difficiles."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Maigres bêtes de la nuit' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Suzerain de Nyarlathotep', 'Commandant du Mythe allié au Soleil Noir', 'Fruits du pacte impie entre le Soleil Noir et le Chaos rampant, ces commandants du Mythe ont été vus sur le champ de bataille, renforçant les formations des troupes de Reinhardt Weissler. Leur visage se réduit à un tentacule unique qui se tord et s''étire, cherchant une saveur ou une fréquence qu''eux seuls perçoivent. La Section M pense qu''ils exercent une puissante force psychique pour contrôler les serviteurs qui les accompagnent. (VO : Overlords of Nyarlathotep)', '["Lieutenant","Mythe"]', 'Gamemaster Guide', 228, '{"rank":"lieutenant","truths":["Commandants grotesques et grouillants du champ de bataille","Lieutenants du Chaos rampant"],"attributes":{"agility":11,"brawn":13,"coordination":9,"insight":13,"reason":13,"will":13},"skills":[{"key":"academia","rank":3,"focuses":["Occultisme"]},{"key":"fighting","rank":4,"focuses":["Main nue"]},{"key":"persuasion","rank":4,"focuses":["Intimidation"]},{"key":"resilience","rank":2,"focuses":[]},{"key":"tactics","rank":3,"focuses":["Tactique du champ de bataille"]}],"stress":16,"injuries":3,"armour":6,"courage":5,"attacks":[{"name":"Tentacule fouettant","focus":"Main nue","range":"contact","damage":7,"salvo":null,"qualities":"Piège","escalation":false},{"name":"Rapière (Degen) du Soleil Noir","focus":"Armes de mêlée","range":"contact","damage":9,"salvo":null,"qualities":"Perforant 1, Faim, Fléau, Parade","escalation":false},{"name":"Pistolet-mitrailleur MP 40","focus":"Corps à corps","range":"close","damage":7,"salvo":"Étourdissant","qualities":"Imprécis","escalation":false},{"name":"Présence surnaturelle (attaque mentale)","focus":null,"range":null,"damage":7,"salvo":null,"qualities":"Perforant 2","escalation":false}],"abilities":[{"name":"Brutal 1","text":"Il attaque et se défend en mêlée avec la Force au lieu de l''Agilité, et ajoute +1 à ses attaques de mêlée (inclus)."},{"name":"Nuage suffocant","text":"Pour 2 Menace, au début de son tour, il libère un nuage de spores qui crée la vérité « Nuage occultant » dans sa zone, gênant la vue et les attaques. Toute créature autre qu''un Suzerain ou un Serviteur présente dans la zone à ce moment subit aussitôt 1 Fatigue en toussant et suffoquant."},{"name":"Force extraordinaire 1","text":"1 succès automatique à tous les tests de Force ; +1 aux attaques de mêlée, +1 en stress maximum et en Armure (déjà inclus)."},{"name":"Effrayant 2","text":"La créature inspire la peur. Elle peut faire des attaques mentales, avec +2 et l''effet Perforant 2 (inclus ci-dessus). La première fois qu''un personnage la voit, il doit réussir un test de Volonté + Résilience de difficulté 2 ou subir du stress mental comme de cette attaque mentale."},{"name":"Nuage hypnotique","text":"Au début de son tour, il peut libérer un nuage de spores en dépensant 1 Menace ou plus par créature visée. Chaque cible fait un test de Volonté + Résilience de difficulté égale à la Menace dépensée pour elle ; en cas d''échec, elle subit l''attaque mentale Présence surnaturelle. Toute créature qui en reçoit une blessure mentale ou plus passe sous son contrôle et obéit pour le reste de la scène."},{"name":"Immunisé au froid, à la maladie, à la peur, à la douleur, au poison et au vide","text":"Il est immunisé au stress, aux vérités et aux autres effets causés par ces conditions."},{"name":"Volonté impérieuse","text":"Les PNJ mineurs qui lui sont subordonnés gagnent +2 en Moral et peuvent relancer un d20 quand ils attaquent. Il communique par télépathie avec les PNJ sous son autorité."},{"name":"Infection","text":"Contre une cible entravée et sans défense, il peut implanter une spore pour 4 Menace : la cible fait un test de Volonté + Résilience de difficulté 3. En cas d''échec, elle est infectée et deviendra un Serviteur de Nyarlathotep (un PJ ou un PNJ Némésis devient un Suzerain). Des moyens magiques ou chirurgicaux peuvent l''éviter, au gré du MJ, mais c''est extrêmement difficile et risqué."},{"name":"Vision nocturne","text":"Il voit dans l''obscurité : il ignore toute hausse de difficulté ou de plage de complication due au manque de lumière, et peut tenter des tests normalement impossibles dans le noir."},{"name":"Lanceur de sorts","text":"Pouvoir 6. Il lance ses sorts avec la Volonté et connaît Les Brumes sans nom, Bénédiction du Soleil Noir et La Forme de la haine."},{"name":"Coriace 1","text":"Il supporte une blessure de plus (incluse) et peut dépenser 3 Menace pour ignorer une blessure."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Suzerain de Nyarlathotep' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Rejeton de Yog-Sothoth', 'Enfant hideux d''un dieu extérieur', 'Conçus lors de rituels terribles et de marchés étranges, les enfants de Yog-Sothoth naissent sous diverses formes, classées en mineures et majeures. Les formes mineures peuvent passer pour à peu près humaines, malgré d''étranges affections de la peau, des tentacules, des écailles ou des griffes ; les formes majeures varient à l''infini et défient toute classification. Ce profil représente une forme de base, simple. (VO : Scion of Yog-Sothoth)', '["Némésis","Mythe"]', 'Gamemaster Guide', 229, '{"rank":"nemesis","truths":["Rejeton hideux de l''au-delà"],"attributes":{"agility":9,"brawn":12,"coordination":10,"insight":11,"reason":13,"will":11},"skills":[{"key":"academia","rank":3,"focuses":["Linguistique","Occultisme"]},{"key":"athletics","rank":2,"focuses":[]},{"key":"fighting","rank":3,"focuses":[]},{"key":"observation","rank":4,"focuses":["Instinct"]},{"key":"persuasion","rank":1,"focuses":[]},{"key":"resilience","rank":3,"focuses":[]},{"key":"stealth","rank":3,"focuses":[]}],"stress":15,"injuries":3,"armour":4,"courage":5,"attacks":[{"name":"Coup à mains nues","focus":"Main nue","range":"contact","damage":5,"salvo":null,"qualities":"Étourdissant","escalation":false},{"name":"Revolver","focus":"Armes de poing","range":"close","damage":6,"salvo":"Vicieux","qualities":"Combat rapproché, Fiable","escalation":false},{"name":"Forme hideuse (attaque mentale)","focus":null,"range":null,"damage":5,"salvo":null,"qualities":"Perforant 1","escalation":false}],"abilities":[{"name":"Effrayant 1","text":"Les Rejetons inspirent la peur. Ils peuvent faire des attaques mentales, avec +1 et l''effet Perforant 1 (inclus ci-dessus). La première fois qu''un personnage en voit un, il doit réussir un test de Volonté + Résilience de difficulté 1 ou subir du stress mental comme de cette attaque mentale."},{"name":"Se nourrir de la peur","text":"Chaque fois qu''un personnage à portée moyenne subit une blessure mentale, générez 2 Menace."},{"name":"Menaçant","text":"Sa simple présence est de mauvais augure : quand il apparaît pour la première fois dans une scène, générez 1 point de Menace."},{"name":"Apparence mortelle","text":"Les Rejetons mineurs passent souvent pour humains s''ils sont assez couverts. Il peut renoncer à Effrayant 1 en cachant sa forme sous ses vêtements : son attaque mentale perd 1 point de dégâts et l''effet Perforant 1, mais il circule sans semer la terreur. S''il révèle sa nature dans la scène, il retrouve aussitôt Effrayant."},{"name":"Taille 1","text":"Il subit une blessure à partir de 6 points de stress (après réductions) en une seule attaque, au lieu de 5. Sa taille peut rendre d''autres actions plus faciles ou plus difficiles."},{"name":"Sorts et rituels","text":"Pouvoir 5. Lanceur de sorts utilisant la Volonté ; il connaît La Voie du Gardien de la porte, Sphères de Yog-Sothoth, Toucher fétide d''Aforgomon, Lien répugnant d''Umr at-Tawil, Entrave de Yog-Sothoth et Regard du multivers."},{"name":"Mutations nombreuses et variées (options)","text":"Capacités supplémentaires suggérées. Invisible : pour une action mineure et 2 Menace, il gagne la vérité « invisible » ; attaques et tests reposant sur la vue pour le détecter ou l''affecter échouent automatiquement, mais les autres ne subissent plus son Effrayant ; l''invisibilité cesse après une attaque physique ou sur complication, au gré du MJ. Griffes lacérantes : ses attaques à mains nues gagnent Persistant 3 et Vicieux et perdent Étourdissant. Invulnérable : il ne subit de blessure que des attaques magiques ou des armes à qualité Fléau ; une attaque qui l''aurait blessé lui fait perdre ses actions au tour suivant (non cumulatif). Taille géante : sa Taille peut varier au gré du MJ."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Rejeton de Yog-Sothoth' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Homme-serpent', 'Ophidien humanoïde', 'Les anciens Ophidiens régnaient jadis sur la Terre depuis leur capitale Valusia, adorant le Grand Serpent Yig. Réduits par un cataclysme, ils ont survécu dans des catacombes souterraines et s''infiltrent aujourd''hui dans les institutions humaines grâce à une sorcellerie innée qui masque leur vraie nature. (VO : Serpent People)', '["Lieutenant","Mythe"]', 'Gamemaster Guide', 230, '{"rank":"lieutenant","truths":["Ophidien humanoïde","Souple et subtil"],"attributes":{"agility":11,"brawn":9,"coordination":10,"insight":11,"reason":13,"will":11},"skills":[{"key":"academia","rank":3,"focuses":["Science","Occultisme"]},{"key":"fighting","rank":2,"focuses":[]},{"key":"observation","rank":2,"focuses":[]},{"key":"persuasion","rank":4,"focuses":["Tromperie","Intimidation"]},{"key":"resilience","rank":2,"focuses":[]},{"key":"stealth","rank":3,"focuses":[]}],"stress":13,"injuries":2,"armour":2,"courage":4,"attacks":[{"name":"Frappe à mains nues","focus":"Main nue","range":"contact","damage":3,"salvo":null,"qualities":"Étourdissant","escalation":false},{"name":"Morsure serpentine","focus":"Main nue","range":"contact","damage":4,"salvo":null,"qualities":"Persistant 4","escalation":false},{"name":"Répulsion atavique","focus":"Intimidation","range":null,"damage":5,"salvo":null,"qualities":"Attaque mentale (Volonté + Persuasion) ; Perforant 1","escalation":false}],"abilities":[{"name":"Insaisissable","text":"Souples et vifs, les hommes-serpents esquivent facilement : la difficulté des attaques à distance contre eux augmente de +1."},{"name":"Effroyable 1","text":"L''homme-serpent inspire la peur. Peut faire des attaques mentales, avec +1 et l''effet Perforant 1 (inclus ci-dessus). De plus, la première fois qu''un personnage voit cette créature, il doit aussitôt réussir un test de Volonté + Résilience de difficulté 1 ou subir un stress mental comme s''il était victime de cette attaque mentale."},{"name":"Agrippant","text":"Après une attaque réussie, dépensez 1 Menace pour ajouter l''effet Piège à l''attaque. Tant qu''elle tient une cible piégée, la créature ne peut pas faire d''attaque de mêlée contre d''autres cibles, mais la difficulté de ses attaques contre la cible piégée baisse de 1."},{"name":"Déguisement illusoire","text":"Les hommes-serpents peuvent circuler parmi les humains, dissimulés par une illusion. Ainsi déguisés, ils ne bénéficient pas de leur capacité Effroyable et ne peuvent pas utiliser leur morsure serpentine sans se révéler. Une personne soupçonneuse peut tenter un test de Perception + Observation en opposition au test de Volonté + Persuasion de l''homme-serpent (difficulté 1 des deux côtés) pour percer l''illusion ; elle est alors affectée par sa capacité Effroyable."},{"name":"Immunité (poison)","text":"Immunisé contre le stress, les vérités et autres effets causés par : poison."},{"name":"Morsure venimeuse","text":"Les attaques de Morsure venimeuse d''un ophidien ont +2 en difficulté, sauf si la cible est piégée ou agrippée. Toute créature affectée par l''effet Persistant de la Morsure serpentine d''un ophidien reçoit aussitôt la vérité Empoisonné. Tant qu''elle dure, la créature subit les dégâts persistants à chaque tour, avec en plus les effets Intense et Perforant 2. Retirer cette vérité demande des soins (Perception + Médecine, difficulté 2) ou un traitement équivalent contre le poison."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Homme-serpent' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Sorcier homme-serpent', 'Sorcier ophidien', 'L''empire ophidien reposait sur ses sorciers, versés dans l''étrange sorcellerie des ténèbres extérieures et dans les voies de dieux dont l''existence effiloche la réalité. Puissants, impitoyables et obstinés, ce sont des ennemis terribles. (VO : Serpent Person Sorcerer)', '["Némésis","Mythe"]', 'Gamemaster Guide', 231, '{"rank":"nemesis","truths":["Ophidien humanoïde","Sorcier","Conjurateur de sorts sombres et subtils"],"attributes":{"agility":11,"brawn":9,"coordination":10,"insight":11,"reason":13,"will":12},"skills":[{"key":"academia","rank":5,"focuses":["Science","Occultisme"]},{"key":"fighting","rank":2,"focuses":[]},{"key":"observation","rank":3,"focuses":["Instinct"]},{"key":"persuasion","rank":4,"focuses":["Tromperie","Intimidation"]},{"key":"resilience","rank":3,"focuses":["Discipline"]},{"key":"stealth","rank":3,"focuses":[]}],"stress":15,"injuries":3,"armour":2,"courage":6,"attacks":[{"name":"Frappe à mains nues","focus":"Main nue","range":"contact","damage":3,"salvo":null,"qualities":"Étourdissant","escalation":false},{"name":"Morsure serpentine","focus":"Main nue","range":"contact","damage":4,"salvo":null,"qualities":"Persistant 4","escalation":false},{"name":"Répulsion atavique","focus":"Intimidation","range":null,"damage":6,"salvo":null,"qualities":"Attaque mentale (Volonté + Persuasion) ; Perforant 1","escalation":false}],"abilities":[{"name":"Insaisissable","text":"Souples et vifs, les hommes-serpents esquivent facilement : la difficulté des attaques à distance contre eux augmente de +1."},{"name":"Effroyable 1","text":"L''homme-serpent inspire la peur. Peut faire des attaques mentales, avec +1 et l''effet Perforant 1 (inclus ci-dessus). De plus, la première fois qu''un personnage voit cette créature, il doit aussitôt réussir un test de Volonté + Résilience de difficulté 1 ou subir un stress mental comme s''il était victime de cette attaque mentale."},{"name":"Agrippant","text":"Après une attaque réussie, dépensez 1 Menace pour ajouter l''effet Piège à l''attaque. Tant qu''elle tient une cible piégée, la créature ne peut pas faire d''attaque de mêlée contre d''autres cibles, mais la difficulté de ses attaques contre la cible piégée baisse de 1."},{"name":"Déguisement illusoire","text":"Les hommes-serpents peuvent circuler parmi les humains, dissimulés par une illusion. Ainsi déguisés, ils ne bénéficient pas de leur capacité Effroyable et ne peuvent pas utiliser leur morsure serpentine sans se révéler. Une personne soupçonneuse peut tenter un test de Perception + Observation en opposition au test de Volonté + Persuasion de l''homme-serpent (difficulté 1 des deux côtés) pour percer l''illusion ; elle est alors affectée par sa capacité Effroyable."},{"name":"Immunité (poison)","text":"Immunisé contre le stress, les vérités et autres effets causés par : poison."},{"name":"Morsure venimeuse","text":"Les attaques de Morsure venimeuse d''un ophidien ont +2 en difficulté, sauf si la cible est piégée ou agrippée. Toute créature affectée par l''effet Persistant de la Morsure serpentine d''un ophidien reçoit aussitôt la vérité Empoisonné. Tant qu''elle dure, la créature subit les dégâts persistants à chaque tour, avec en plus les effets Intense et Perforant 2. Retirer cette vérité demande des soins (Perception + Médecine, difficulté 2) ou un traitement équivalent contre le poison."},{"name":"Sorts et rituels","text":"Puissance 5. Lance ses sorts avec le Raisonnement et connaît : Folie du Pharaon noir, Masque du Sphinx sans visage, Pluie noire mineure, Voie du Gardien de la porte et Toucher fétide d''Aforgomon."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Sorcier homme-serpent' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Serviteur de Nyarlathotep', 'Troupe de choc du Mythe', 'Nés d''un pacte entre le Soleil noir et le Chaos rampant, les Serviteurs sont des troupes de choc féroces lancées contre l''infanterie alliée. Griffes sauvages, force berserk et apparence de langue gigantesque de bête baveuse en font l''une des forces les plus redoutées de la Guerre secrète. (VO : Servitor of Nyarlathotep)', '["Troupe","Mythe"]', 'Gamemaster Guide', 232, '{"rank":"trooper","truths":["Grotesques et grouillants","Troupes de choc"],"attributes":{"agility":9,"brawn":11,"coordination":7,"insight":11,"reason":11,"will":11},"skills":[{"key":"fighting","rank":3,"focuses":["Main nue"]},{"key":"persuasion","rank":3,"focuses":["Intimidation"]},{"key":"resilience","rank":2,"focuses":[]},{"key":"tactics","rank":2,"focuses":[]}],"stress":7,"injuries":2,"armour":4,"courage":4,"attacks":[{"name":"Tentacule fouettant","focus":"Main nue","range":"contact","damage":4,"salvo":null,"qualities":"Étourdissant","escalation":false},{"name":"Griffes tranchantes","focus":"Main nue","range":"contact","damage":4,"salvo":null,"qualities":"Vicieux","escalation":false},{"name":"Présence surnaturelle","focus":"Attaque mentale","range":null,"damage":5,"salvo":null,"qualities":"Perforant 1","escalation":false}],"abilities":[{"name":"Effroyable 1","text":"Le Serviteur inspire la peur. Peut faire des attaques mentales, avec +1 et l''effet Perforant 1 (inclus ci-dessus). De plus, la première fois qu''un personnage voit cette créature, il doit aussitôt réussir un test de Volonté + Résilience de difficulté 1 ou subir un stress mental comme s''il était victime de cette attaque mentale."},{"name":"Immunité (froid, maladie, peur, douleur, poison, vide)","text":"Immunisé contre le stress, les vérités et autres effets causés par : froid, maladie, peur, douleur, poison, vide."},{"name":"Vision nocturne","text":"Voit dans l''obscurité : ignore toute hausse de difficulté ou de plage de complication due au manque de lumière, et peut tenter des tests normalement impossibles dans le noir."},{"name":"Coriace 1","text":"Peut encaisser 1 blessure supplémentaire (incluse ci-dessus). Peut aussi dépenser 3 Menace pour ignorer une blessure."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Serviteur de Nyarlathotep' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Serviteur des Dieux extérieurs', 'Héraut amorphe d''Azathoth', 'Azathoth est maintenu endormi par la musique de serviteurs titanesques qui entourent la folie nucléaire au cœur de toute chose. Vaguement éléphantins et de taille colossale, ils semblent obéir à une intelligence bien supérieure à la leur ; rarement agressifs, ils peuvent être poussés à une destruction féroce. (VO : Servitor of the Outer Gods)', '["Lieutenant","Mythe"]', 'Gamemaster Guide', 232, '{"rank":"lieutenant","truths":["Amorphe","Hérauts de la musique profane","Apaisent l''esprit des dieux du chaos"],"attributes":{"agility":7,"brawn":11,"coordination":9,"insight":13,"reason":13,"will":13},"skills":[{"key":"academia","rank":3,"focuses":["Occultisme"]},{"key":"fighting","rank":2,"focuses":["Main nue"]},{"key":"persuasion","rank":4,"focuses":["Intimidation","Invocation"]},{"key":"resilience","rank":2,"focuses":[]}],"stress":15,"injuries":3,"armour":2,"courage":5,"attacks":[{"name":"Masse de tentacules","focus":"Main nue","range":"contact","damage":4,"salvo":null,"qualities":"Zone","escalation":false},{"name":"Forme abjecte","focus":"Attaque mentale","range":null,"damage":6,"salvo":null,"qualities":"Perforant 1","escalation":false}],"abilities":[{"name":"Récupération rapide 3","text":"Retire 3 stress à la fin de chacun de ses tours. Si elle a des blessures au début de son tour, elle peut dépenser 2 Menace pour en retirer une complètement. Cesse de fonctionner quand la créature est vaincue."},{"name":"Effroyable 1","text":"Le Serviteur inspire la peur. Peut faire des attaques mentales, avec +1 et l''effet Perforant 1 (inclus ci-dessus). De plus, la première fois qu''un personnage voit cette créature, il doit aussitôt réussir un test de Volonté + Résilience de difficulté 1 ou subir un stress mental comme s''il était victime de cette attaque mentale."},{"name":"Immunité (froid, maladie, peur, douleur, poison, vide)","text":"Immunisé contre le stress, les vérités et autres effets causés par : froid, maladie, peur, douleur, poison, vide."},{"name":"Coriace 1","text":"Peut encaisser 1 blessure supplémentaire (incluse ci-dessus). Peut aussi dépenser 3 Menace pour ignorer une blessure."},{"name":"Invulnérable","text":"Ne peut subir de blessure d''aucune attaque physique, hormis les attaques magiques ou les armes à la qualité Fléau. Si une attaque contre laquelle il est immunisé devait lui infliger une blessure, il perd à la place la possibilité d''agir à son prochain tour (non cumulatif)."},{"name":"Vision nocturne","text":"Voit dans l''obscurité : ignore toute hausse de difficulté ou de plage de complication due au manque de lumière, et peut tenter des tests normalement impossibles dans le noir."},{"name":"Taille 2","text":"Subit une blessure après avoir subi 7 stress (après réductions) d''une seule attaque, au lieu de 5. D''autres actions peuvent être plus faciles ou plus difficiles selon sa taille."},{"name":"Sorts et rituels","text":"Puissance 6. Lance ses sorts avec la Volonté et connaît : Voie du Gardien de la porte, Regard du multivers et Lien de Yog-Sothoth."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Serviteur des Dieux extérieurs' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Sheehad', 'Horreur fouisseuse télépathe', 'Colonne de graisse et de muscle suppurants surmontée de tentacules, le Sheehad jaillit du sol pour déchirer ses ennemis dans un silence féroce. Télépathe, il lit les plans de ses ennemis dans leur esprit et peut se déplacer caché sous terre ou percer le béton pour atteindre sa proie.', '["Lieutenant","Mythe"]', 'Gamemaster Guide', 233, '{"rank":"lieutenant","truths":["Horreur native des profondeurs de la terre"],"attributes":{"agility":12,"brawn":12,"coordination":10,"insight":6,"reason":6,"will":10},"skills":[{"key":"athletics","rank":3,"focuses":["Fouissement"]},{"key":"fighting","rank":4,"focuses":["Main nue"]},{"key":"observation","rank":3,"focuses":["Ouïe"]},{"key":"resilience","rank":3,"focuses":["Endurance","Assaut mental"]}],"stress":16,"injuries":3,"armour":5,"courage":6,"attacks":[{"name":"Tentacules fouettants","focus":"Main nue","range":"contact","damage":6,"salvo":null,"qualities":"Vidange, Piège","escalation":false},{"name":"Coup massif","focus":"Main nue","range":"contact","damage":6,"salvo":null,"qualities":"Zone","escalation":false},{"name":"Influence télépathique","focus":"Attaque mentale","range":null,"damage":6,"salvo":null,"qualities":"Perforant 2","escalation":false}],"abilities":[{"name":"Éruption","text":"Le Sheehad traverse roche et pierre avec aisance et attaque par en dessous. S''il entre dans une scène en jaillissant du sol, il ajoute +2 à son attaque Coup massif [et à] son attaque mentale jusqu''à la fin de son premier tour."},{"name":"Brutal 1","text":"Fait et défend ses attaques de mêlée avec la Force au lieu de l''Agilité. Ajoute +1 à ses attaques de mêlée (inclus ci-dessus)."},{"name":"Fouisseur","text":"Le Sheehad creuse la terre, la boue, l''argile et la roche comme un couteau chaud dans du beurre. Il ne respire pas et se déplace librement sous les zones qui représentent le sol (comme s''il existait des zones « souterraines » inaccessibles aux personnages normaux)."},{"name":"Force extraordinaire 1","text":"Ajoute 1 succès automatique à tous ses tests de Force. Ajoute aussi +1 à ses attaques de mêlée, à son stress maximum et à son Armure (inclus ci-dessus)."},{"name":"Récupération rapide 4","text":"Retire 4 stress à la fin de chacun de ses tours. Si elle a des blessures au début de son tour, elle peut dépenser 2 Menace pour en retirer une complètement. Cesse de fonctionner quand la créature est vaincue."},{"name":"Effroyable 2","text":"Le Sheehad inspire la peur. Peut faire des attaques mentales, avec +2 et l''effet Perforant 2 (inclus ci-dessus). De plus, la première fois qu''un personnage voit cette créature, il doit aussitôt réussir un test de Volonté + Résilience de difficulté 2 ou subir un stress mental comme s''il était victime de cette attaque mentale."},{"name":"Hydrophobe","text":"Le Sheehad subit aussitôt 5 stress physique, avec les effets Intense et Perforant 2, chaque fois qu''il entre en contact avec de l''eau."},{"name":"Immunité (peur, chaleur extrême)","text":"Immunisé contre le stress, les vérités et autres effets causés par : peur, chaleur extrême."},{"name":"Sens aiguisés (ouïe)","text":"Réduit de 2 la difficulté de tous les tests liés à l''ouïe (minimum 0). Il perçoit à l''oreille des choses que les humains ne peuvent pas entendre."},{"name":"Taille 1","text":"Subit une blessure après avoir subi 6 stress (après réductions) d''une seule attaque, au lieu de 5. D''autres actions peuvent être plus faciles ou plus difficiles selon sa taille."},{"name":"Influence télépathique","text":"Le Sheehad communique par télépathie avec ses semblables à n''importe quelle distance. S''il inflige une ou plusieurs blessures à un humain avec son attaque mentale (et non avec Effroyable), il peut le lier. Un humain lié ne peut s''éloigner à plus d''un mile (environ 1,6 km) du lieu où il a été lié, et tout Sheehad peut communiquer avec lui. Un Sheehad peut tenter un test de Volonté + Résilience de difficulté 1 (augmentée par la distance, à la discrétion du MJ) pour forcer l''humain à accomplir une tâche précise."},{"name":"Coriace 1","text":"Peut encaisser 1 blessure supplémentaire (incluse ci-dessus). Peut aussi dépenser 3 Menace pour ignorer une blessure."},{"name":"Sheehad supérieur (variante)","text":"Les Sheehad les plus courants sont des juvéniles, à peine plus grands qu''un humain, mais ils grandissent toute leur très longue vie. Pour un spécimen plus ancien, augmentez Brutal 1, Coriace 1 et Taille 1 (de préférence tous les trois de 1 avant d''aller plus loin) ; les plus grands peuvent être des PNJ Némésis. Les Sheehad colossaux, annoncés par des séismes, tiennent plus de la catastrophe naturelle que de l''adversaire."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Sheehad' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Shoggoth', 'Protoplasme serviteur révolté', 'Créés comme esclaves par les Choses très anciennes, les shoggoths sont des masses de protoplasme visqueux infiniment malléables, capables de se changer en yeux ou en appendices lumineux en un instant. D''une force immense et implacables, certains ont développé une intelligence rusée et malveillante et forment désormais une espèce autonome.', '["Némésis","Mythe"]', 'Gamemaster Guide', 234, '{"rank":"nemesis","truths":["Protoplasme fétide et visqueux","Serviteurs belliqueux","Serviteurs rebelles"],"attributes":{"agility":5,"brawn":14,"coordination":7,"insight":9,"reason":6,"will":11},"skills":[{"key":"fighting","rank":5,"focuses":["Main nue"]},{"key":"observation","rank":4,"focuses":[]},{"key":"resilience","rank":5,"focuses":[]}],"stress":21,"injuries":6,"armour":12,"courage":7,"attacks":[{"name":"Masse de tentacules et de pseudopodes","focus":"Main nue","range":"contact","damage":10,"salvo":null,"qualities":"Zone","escalation":false},{"name":"Déferlement irrésistible","focus":"Main nue","range":"contact","damage":10,"salvo":null,"qualities":"Vicieux","escalation":false},{"name":"Horreur indescriptible","focus":"Attaque mentale","range":null,"damage":6,"salvo":null,"qualities":"Perforant 2, Étourdissant","escalation":false}],"abilities":[{"name":"Masse amorphe","text":"Énorme et informe, le shoggoth ondule pour prendre à chaque instant la forme dont il a besoin. Il peut traiter tous les ennemis à portée courte comme s''ils étaient à son contact."},{"name":"Brutal 2","text":"Fait et défend ses attaques de mêlée avec la Force au lieu de l''Agilité. Ajoute +2 à ses attaques de mêlée (inclus ci-dessus)."},{"name":"Engloutir","text":"Les créatures agrippées par un shoggoth (voir Agrippant) peuvent être aspirées dans sa forme instable. Si une ou plusieurs créatures sont agrippées au début de l''un de ses tours, il peut dépenser 2 Menace pour en aspirer une. Une créature engloutie subit 6 stress physique avec les effets Vidange et Intense, comprimée et écartelée. Si le shoggoth est vaincu, les créatures englouties sont expulsées."},{"name":"Force extraordinaire 2","text":"Ajoute 2 succès automatiques à tous ses tests de Force. Ajoute aussi +2 à ses attaques de mêlée, à son stress maximum et à son Armure (inclus ci-dessus)."},{"name":"Récupération rapide 1","text":"Retire 1 stress à la fin de chacun de ses tours. Si elle a des blessures au début de son tour, elle peut dépenser 2 Menace pour en retirer une complètement. Cesse de fonctionner quand la créature est vaincue."},{"name":"Effroyable 2","text":"La créature inspire la peur. Peut faire des attaques mentales, avec +2 et l''effet Perforant 2 (inclus ci-dessus). De plus, la première fois qu''un personnage voit cette créature, il doit aussitôt réussir un test de Volonté + Résilience de difficulté 2 ou subir un stress mental comme s''il était victime de cette attaque mentale."},{"name":"Agrippant","text":"Après une attaque réussie, dépensez 1 Menace pour ajouter l''effet Piège à l''attaque. Tant qu''elle tient une cible piégée, la créature ne peut pas faire d''attaque de mêlée contre d''autres cibles, mais la difficulté de ses attaques contre la cible piégée baisse de 1."},{"name":"Immunité (froid, maladie, peur, douleur, poison, vide)","text":"Immunisé contre le stress, les vérités et autres effets causés par : froid, maladie, peur, douleur, poison, vide."},{"name":"Incorporel 6","text":"Masse visqueuse de protoplasme, le shoggoth s''écoule autour de tout obstacle. Il gagne +6 Armure (inclus ci-dessus) et se déplace librement en terrain difficile. En dépensant 1 Menace, il trouve un chemin à travers une barrière solide (mur, porte) en s''insinuant dans les interstices. Il perd cette armure contre les attaques magiques."},{"name":"Menaçant","text":"Sa seule présence est de mauvais augure : quand la créature apparaît pour la première fois dans une scène, générez 1 Menace."},{"name":"Vision nocturne","text":"Voit dans l''obscurité : ignore toute hausse de difficulté ou de plage de complication due au manque de lumière, et peut tenter des tests normalement impossibles dans le noir."},{"name":"Déguisement parfait","text":"En sommeil, un shoggoth peut prendre exactement les dimensions et l''apparence de son environnement. Le remarquer demande un test de Perception + Observation de difficulté 4."},{"name":"Taille 8","text":"Subit une blessure après avoir subi 13 stress (après réductions) d''une seule attaque, au lieu de 5. D''autres actions peuvent être plus faciles ou plus difficiles selon sa taille."},{"name":"Inquiétant 3","text":"Quand la créature apparaît pour la première fois dans une scène, elle génère 3 Menace qu''elle seule peut utiliser."},{"name":"Coriace 4","text":"Peut encaisser 4 blessures supplémentaires (incluses ci-dessus). Peut aussi dépenser 3 Menace pour ignorer une blessure."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Shoggoth' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Rejeton stellaire de Cthulhu', 'Vassal de Cthulhu', 'Octopodes faits d''une substance qui n''est pas tout à fait de la matière, les rejetons stellaires sont les enfants de Cthulhu, venus avec lui sur Terre comme soldats et colons. Quand R''lyeh a sombré, certains sont partis, d''autres veillent leur maître ou se cachent ; prédateurs rusés et télépathes, ils sont aussi capables d''une dévastation physique féroce. (VO : Stellar Spawn of Cthulhu)', '["Némésis","Mythe"]', 'Gamemaster Guide', 236, '{"rank":"nemesis","truths":["Vassaux monstrueux du terrible Cthulhu","Satrapes du Dormeur"],"attributes":{"agility":9,"brawn":14,"coordination":8,"insight":12,"reason":12,"will":14},"skills":[{"key":"academia","rank":3,"focuses":["Occultisme"]},{"key":"athletics","rank":4,"focuses":["Natation"]},{"key":"fighting","rank":3,"focuses":["Main nue"]},{"key":"observation","rank":4,"focuses":["Instinct"]},{"key":"resilience","rank":4,"focuses":["Endurance","Discipline"]},{"key":"survival","rank":3,"focuses":[]}],"stress":20,"injuries":4,"armour":10,"courage":9,"attacks":[{"name":"Griffes massives","focus":"Main nue","range":"contact","damage":9,"salvo":null,"qualities":"Vicieux 1","escalation":false},{"name":"Tentacules fouettants","focus":"Main nue","range":"contact","damage":6,"salvo":null,"qualities":"Zone","escalation":false},{"name":"Visage monstrueux","focus":"Attaque mentale","range":null,"damage":10,"salvo":null,"qualities":"Étourdissant, Perforant 3","escalation":false}],"abilities":[{"name":"Brutal 1","text":"Fait et défend ses attaques de mêlée avec la Force au lieu de l''Agilité. Ajoute +1 à ses attaques de mêlée (inclus ci-dessus)."},{"name":"Force extraordinaire 2","text":"Ajoute 2 succès automatiques à tous ses tests de Force. Ajoute aussi +2 à ses attaques de mêlée, à son stress maximum et à son Armure (inclus ci-dessus)."},{"name":"Perception extraordinaire 1","text":"Ajoute 1 succès automatique à ses tests de Perception."},{"name":"Raisonnement extraordinaire 1","text":"Ajoute 1 succès automatique à ses tests de Raisonnement."},{"name":"Volonté extraordinaire 1","text":"Ajoute 1 succès automatique à tous ses tests de Volonté. Gagne aussi +1 Puissance, +1 aux attaques mentales, +1 Courage et +1 stress maximum (inclus)."},{"name":"Récupération rapide 3","text":"Retire 3 stress à la fin de chacun de ses tours. Si elle a des blessures au début de son tour, elle peut dépenser 2 Menace pour en retirer une complètement. Cesse de fonctionner quand la créature est vaincue."},{"name":"Effroyable 3","text":"La créature inspire la terreur. Peut faire des attaques mentales, avec +3 et l''effet Perforant 3 (inclus ci-dessus). De plus, la première fois qu''un personnage voit cette créature, il doit aussitôt réussir un test de Volonté + Résilience de difficulté 3 ou subir un stress mental comme s''il était victime de cette attaque mentale."},{"name":"Se repaître de la peur","text":"Chaque fois qu''un personnage à portée moyenne de la créature subit une blessure mentale, générez 2 Menace."},{"name":"Immunité (froid, maladie, peur, douleur, poison, chaleur, vide)","text":"Immunisé contre le stress, les vérités et autres effets causés par : froid, maladie, peur, douleur, poison, chaleur, vide."},{"name":"Menaçant","text":"Sa seule présence est de mauvais augure : quand la créature apparaît pour la première fois dans une scène, générez 1 Menace."},{"name":"Taille 5","text":"Subit une blessure après avoir subi 10 stress (après réductions) d''une seule attaque, au lieu de 5. D''autres actions peuvent être plus faciles ou plus difficiles selon sa taille."},{"name":"Inquiétant 3","text":"Quand la créature apparaît pour la première fois dans une scène, elle génère 3 Menace qu''elle seule peut utiliser."},{"name":"Coriace 1","text":"Peut encaisser 1 blessure supplémentaire (incluse ci-dessus). Peut aussi dépenser 3 Menace pour ignorer une blessure."},{"name":"Sorts et rituels","text":"Puissance 8. Lance ses sorts avec la Volonté et connaît : Appel des profondeurs, Malédiction de Cthulhu, Bassin de félicité limpide, Écho de l''océan, Tempête de vagues, Nageur du courant ancien et Appel de l''abîme."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Rejeton stellaire de Cthulhu' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Teufelshund', 'Chasseur interdimensionnel', 'Connu sous bien des noms (Bête du vide, Chien de l''enfer, Démon des portails), le Teufelshund est un chasseur interdimensionnel implacable dont les proies sont ceux qui ont trop sondé les mystères de l''univers. Il traque à travers le temps et l''espace, et seule une magie de dissimulation très puissante peut protéger sa victime.', '["Lieutenant","Mythe"]', 'Gamemaster Guide', 236, '{"rank":"lieutenant","truths":["Chasseur inexorable","Arpenteur des géométries non euclidiennes"],"attributes":{"agility":9,"brawn":11,"coordination":5,"insight":11,"reason":10,"will":13},"skills":[{"key":"athletics","rank":1,"focuses":[]},{"key":"fighting","rank":5,"focuses":["Main nue"]},{"key":"observation","rank":5,"focuses":["Vue","Instinct"]},{"key":"survival","rank":5,"focuses":["Pistage"]},{"key":"resilience","rank":2,"focuses":[]}],"stress":15,"injuries":2,"armour":4,"courage":5,"attacks":[{"name":"Pattes ruisselantes d''ichor","focus":"Main nue","range":"contact","damage":4,"salvo":null,"qualities":"Persistant 4","escalation":false},{"name":"Langue barbelée","focus":"Main nue","range":"contact","damage":4,"salvo":null,"qualities":"Vidange, Perforant 2","escalation":false},{"name":"Géométrie effroyable","focus":"Attaque mentale","range":null,"damage":7,"salvo":null,"qualities":"Persistant 3, Perforant 2","escalation":false}],"abilities":[{"name":"Créature des portails","text":"Quand il cherche à repérer sa proie, le Teufelshund peut, par une action mineure et 2 Menace, émerger de l''espace interdimensionnel, d''abord sous forme d''un mur de fumée puante d''où il se matérialise. Il peut quitter une scène de la même façon pour 2 Menace, et risque de réapparaître par un autre portail."},{"name":"Miasme impossible","text":"Une puanteur âcre de mort et d''anomalie imprègne les lieux où il se manifeste : les créatures à portée moyenne d''un ou plusieurs Teufelshund augmentent de 1 la plage de complication de tous leurs tests."},{"name":"Incorporel","text":"N''occupe pas l''espace physique de façon naturelle : +2 Armure (inclus ci-dessus), déplacement libre en terrain difficile ; pour 1 Menace, il franchit une barrière solide (mur, porte). Il perd cette armure contre les attaques magiques."},{"name":"Invulnérable","text":"Ne peut subir de blessure d''aucune attaque physique, hormis les attaques magiques, les armes à la qualité Fléau, les attaques électriques ou de puissants champs magnétiques. Si une attaque contre laquelle il est immunisé devait lui infliger une blessure, il perd à la place la possibilité d''agir à son prochain tour (non cumulatif)."},{"name":"Sens aiguisés (vue)","text":"Réduit de 2 la difficulté de tous les tests liés à la vue (minimum 0). Il voit à des distances bien supérieures à celles d''un humain."},{"name":"Menaçant","text":"Sa seule présence est de mauvais augure : quand la créature apparaît pour la première fois dans une scène, générez 1 Menace."},{"name":"Taille 2","text":"Subit une blessure après avoir subi 7 stress (après réductions) d''une seule attaque, au lieu de 5. D''autres actions peuvent être plus faciles ou plus difficiles selon sa taille."},{"name":"Perception extraordinaire 1","text":"Ajoute 1 succès automatique à ses tests de Perception."},{"name":"Récupération rapide 4","text":"Retire 4 stress à la fin de chacun de ses tours. Si elle a des blessures au début de son tour, elle peut dépenser 2 Menace pour en retirer une complètement. Cesse de fonctionner quand la créature est vaincue."},{"name":"Effroyable 2","text":"Le Teufelshund inspire la peur. Peut faire des attaques mentales, avec +2 et l''effet Perforant 2 (inclus ci-dessus). De plus, la première fois qu''un personnage voit cette créature, il doit aussitôt réussir un test de Volonté + Résilience de difficulté 2 ou subir un stress mental comme s''il était victime de cette attaque mentale."},{"name":"Immunité (froid, maladie, peur, douleur, poison, vide)","text":"Immunisé contre le stress, les vérités et autres effets causés par : froid, maladie, peur, douleur, poison, vide."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Teufelshund' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Hybride des Profonds', 'Rejeton humain des Profonds', 'Yeux globuleux et chair à l''odeur de poisson, les hybrides sont les rejetons d''humains et de vrais Profonds. En vieillissant, ils prennent de plus en plus les traits ichtyens de leurs géniteurs jusqu''à devenir de vrais enfants du Père Dagon ; avant cela, ils peuvent passer pour humains. (VO : Deep One Hybrid)', '["Troupe","Mythe"]', 'Gamemaster Guide', 238, '{"rank":"trooper","truths":["Rejeton caché des Profonds","Ça sent le poisson","Amphibie"],"attributes":{"agility":8,"brawn":10,"coordination":7,"insight":8,"reason":9,"will":8},"skills":[{"key":"academia","rank":1,"focuses":[]},{"key":"athletics","rank":2,"focuses":["Natation"]},{"key":"fighting","rank":2,"focuses":["Armes de mêlée"]},{"key":"observation","rank":2,"focuses":[]},{"key":"resilience","rank":3,"focuses":[]},{"key":"stealth","rank":3,"focuses":["Déguisement"]},{"key":"survival","rank":1,"focuses":[]},{"key":"tactics","rank":1,"focuses":[]}],"stress":7,"injuries":1,"armour":2,"courage":0,"attacks":[{"name":"Couperet","focus":"Armes de mêlée","range":"contact","damage":5,"salvo":null,"qualities":null,"escalation":false},{"name":"Revolver","focus":"Armes de poing","range":"close","damage":4,"salvo":"Vicieux","qualities":"Combat rapproché, Fiable","escalation":false},{"name":"Fusil à pompe","focus":"Corps à corps","range":"close","damage":5,"salvo":"Vicieux","qualities":"Imprécis, Fiable","escalation":false}],"abilities":[{"name":"Appel des Profonds","text":"Un hybride peut appeler à l''aide des Profonds PNJ Troupiers. Chaque Profond appelé ainsi coûte 2 Menace (ou 2 Menace par membre si c''est un groupe) et arrive au début du round suivant."},{"name":"Nauséabond","text":"Vu de près, quand son odeur n''est pas masquée, un hybride donne la nausée. La première fois de la scène qu''un personnage voit, et sent, un hybride non déguisé, il doit réussir un test de Volonté + Résilience de difficulté 2 ; en cas d''échec, le dégoût augmente de 1 sa plage de complication pour tous ses tests jusqu''à la fin de la scène."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Hybride des Profonds' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Éclaireur des Profonds', 'Éclaireur amphibie', 'La peau caoutchouteuse enduite d''un onguent qui l''empêche de sécher et masque son odeur, l''éclaireur est les yeux de ses frères sous-marins sur la terre ferme. Légèrement protégé, rapide et discret, il annonce à coup sûr qu''un désastre venu des eaux est imminent. (VO : Deep One Scout)', '["Troupe","Mythe"]', 'Gamemaster Guide', 239, '{"rank":"trooper","truths":["Éclaireur des Profonds","Rapide","Rusé","Furtif","Amphibie"],"attributes":{"agility":9,"brawn":11,"coordination":8,"insight":9,"reason":10,"will":9},"skills":[{"key":"athletics","rank":3,"focuses":["Natation"]},{"key":"fighting","rank":2,"focuses":["Exotique","Main nue"]},{"key":"observation","rank":2,"focuses":[]},{"key":"resilience","rank":3,"focuses":[]},{"key":"stealth","rank":3,"focuses":["Discrétion rurale"]},{"key":"survival","rank":1,"focuses":[]},{"key":"tactics","rank":2,"focuses":["Opérations clandestines"]}],"stress":7,"injuries":1,"armour":4,"courage":4,"attacks":[{"name":"Griffes sauvages","focus":"Main nue","range":"contact","damage":4,"salvo":null,"qualities":"Perforant 1","escalation":false},{"name":"Sarbacane","focus":"Exotique","range":null,"damage":3,"salvo":"Vicieux","qualities":"Persistant 4 ; Précis, Subtil","escalation":false},{"name":"Horrifique","focus":"Attaque mentale","range":null,"damage":4,"salvo":null,"qualities":"Perforant 1, Étourdissant","escalation":false}],"abilities":[{"name":"Effroyable 1","text":"La créature inspire la peur. Peut faire des attaques mentales, avec +1 et l''effet Perforant 1 (inclus ci-dessus). De plus, la première fois qu''un personnage voit cette créature, il doit aussitôt réussir un test de Volonté + Résilience de difficulté 1 ou subir un stress mental comme s''il était victime de cette attaque mentale."},{"name":"Caché dans les profondeurs","text":"Les éclaireurs se dissimulent vite et bien derrière presque n''importe quel couvert. Faire agir un éclaireur en premier au premier round d''un combat ne coûte jamais de Menace au MJ."},{"name":"Immunité (froid extrême)","text":"Immunisé contre le stress, les vérités et autres effets causés par : froid extrême."},{"name":"Vision nocturne","text":"Voit dans l''obscurité : ignore toute hausse de difficulté ou de plage de complication due au manque de lumière, et peut tenter des tests normalement impossibles dans le noir."},{"name":"Taille 1","text":"Subit une blessure après avoir subi 6 stress (après réductions) d''une seule attaque, au lieu de 5. D''autres actions peuvent être plus faciles ou plus difficiles selon sa taille."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Éclaireur des Profonds' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Esclavagiste des Profonds', 'Ravisseur amphibie', 'Les Profonds propagent parfois leur race par des pactes avec des humains désespérés ou avides, payés en trésors engloutis, en bijoux troublants ou en une forme d''immortalité. Pour ceux qui refusent, il y a les esclavagistes : armés de menottes en carapaces et de fouets d''algues, ils traînent leurs victimes vers les profondeurs. (VO : Deep One Slaver)', '["Troupe","Mythe"]', 'Gamemaster Guide', 239, '{"rank":"trooper","truths":["Esclavagiste des Profonds","Les prendre vivants","Amphibie"],"attributes":{"agility":9,"brawn":11,"coordination":8,"insight":9,"reason":10,"will":9},"skills":[{"key":"athletics","rank":3,"focuses":["Natation","Lancer"]},{"key":"fighting","rank":3,"focuses":["Main nue","Armes de mêlée"]},{"key":"observation","rank":2,"focuses":[]},{"key":"resilience","rank":3,"focuses":[]},{"key":"stealth","rank":2,"focuses":[]},{"key":"survival","rank":1,"focuses":[]},{"key":"tactics","rank":1,"focuses":[]}],"stress":7,"injuries":1,"armour":4,"courage":4,"attacks":[{"name":"Griffes sauvages","focus":"Main nue","range":"contact","damage":4,"salvo":null,"qualities":"Perforant 1","escalation":false},{"name":"Fouet de varech","focus":"Armes de mêlée","range":"contact","damage":3,"salvo":null,"qualities":"Piège, Étourdissant","escalation":false},{"name":"Filet d''algues","focus":"Lancer","range":null,"damage":4,"salvo":null,"qualities":"Piège ; Imprécis, Munition","escalation":false},{"name":"Horrifique","focus":"Attaque mentale","range":null,"damage":4,"salvo":null,"qualities":"Perforant 1, Étourdissant","escalation":false}],"abilities":[{"name":"Ligoter et emporter","text":"Dès qu''un esclavagiste a piégé un adversaire avec son fouet ou son filet, il tente de s''emparer de sa proie : à son tour, pour 2 Menace, il peut tenter cette action contre une créature piégée à son contact. C''est un test de Force + Combat de difficulté 1 ; en cas de réussite, la cible est aussitôt vaincue, inconsciente, prête à être ligotée et emportée vers un sort indicible."},{"name":"Effroyable 1","text":"La créature inspire la peur. Peut faire des attaques mentales, avec +1 et l''effet Perforant 1 (inclus ci-dessus). De plus, la première fois qu''un personnage voit cette créature, il doit aussitôt réussir un test de Volonté + Résilience de difficulté 1 ou subir un stress mental comme s''il était victime de cette attaque mentale."},{"name":"Immunité (froid extrême)","text":"Immunisé contre le stress, les vérités et autres effets causés par : froid extrême."},{"name":"Vision nocturne","text":"Voit dans l''obscurité : ignore toute hausse de difficulté ou de plage de complication due au manque de lumière, et peut tenter des tests normalement impossibles dans le noir."},{"name":"Taille 1","text":"Subit une blessure après avoir subi 6 stress (après réductions) d''une seule attaque, au lieu de 5. D''autres actions peuvent être plus faciles ou plus difficiles selon sa taille."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Esclavagiste des Profonds' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Guerrier des Profonds', 'Guerrier amphibie', 'Quand les Profonds sortent des abysses pour razzier les villages côtiers, le gros de leurs forces est fait de ces choses mi-poisson mi-grenouille que la Section M appelle « guerriers ». Peau épaisse, ouïes profondes et griffes palmées : un seul guerrier peut mettre un humain en pièces. (VO : Deep One Warrior)', '["Troupe","Mythe"]', 'Gamemaster Guide', 240, '{"rank":"trooper","truths":["Guerrier des Profonds","Massif et monstrueux","Amphibie"],"attributes":{"agility":8,"brawn":12,"coordination":9,"insight":9,"reason":8,"will":11},"skills":[{"key":"athletics","rank":3,"focuses":["Natation"]},{"key":"fighting","rank":4,"focuses":["Main nue","Armes de mêlée"]},{"key":"observation","rank":2,"focuses":[]},{"key":"resilience","rank":4,"focuses":[]},{"key":"stealth","rank":2,"focuses":[]},{"key":"survival","rank":1,"focuses":[]},{"key":"tactics","rank":2,"focuses":[]}],"stress":8,"injuries":2,"armour":4,"courage":6,"attacks":[{"name":"Griffes sauvages","focus":"Main nue","range":"contact","damage":6,"salvo":null,"qualities":"Perforant 1","escalation":false},{"name":"Horrifique","focus":"Attaque mentale","range":null,"damage":5,"salvo":null,"qualities":"Perforant 1, Étourdissant","escalation":false},{"name":"Lance empaleuse","focus":"Armes de mêlée","range":"contact","damage":8,"salvo":null,"qualities":"Intense, Perforant 1","escalation":true}],"abilities":[{"name":"Brutal 1","text":"Fait et défend ses attaques de mêlée avec la Force au lieu de l''Agilité. Ajoute +1 à ses attaques de mêlée (inclus ci-dessus)."},{"name":"Effroyable 1","text":"La créature inspire la peur. Peut faire des attaques mentales, avec +1 et l''effet Perforant 1 (inclus ci-dessus). De plus, la première fois qu''un personnage voit cette créature, il doit aussitôt réussir un test de Volonté + Résilience de difficulté 1 ou subir un stress mental comme s''il était victime de cette attaque mentale."},{"name":"Immunité (froid extrême)","text":"Immunisé contre le stress, les vérités et autres effets causés par : froid extrême."},{"name":"Vision nocturne","text":"Voit dans l''obscurité : ignore toute hausse de difficulté ou de plage de complication due au manque de lumière, et peut tenter des tests normalement impossibles dans le noir."},{"name":"Taille 1","text":"Subit une blessure après avoir subi 6 stress (après réductions) d''une seule attaque, au lieu de 5. D''autres actions peuvent être plus faciles ou plus difficiles selon sa taille."},{"name":"Coriace 1","text":"Peut encaisser 1 blessure supplémentaire (incluse ci-dessus). Peut aussi dépenser 3 Menace pour ignorer une blessure."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Guerrier des Profonds' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Ingénieur des Profonds', 'Bâtisseur amphibie', 'Les cités de corail des Profonds, cachées dans les abysses glacés, sont d''une beauté à couper le souffle. Quand les Profonds visitent la surface, leurs bâtisseurs, que la Section M appelle « ingénieurs », les accompagnent, en soutien au combat et pour observer le monde qu''ils refaçonneront quand les océans reprendront la terre. (VO : Deep One Engineer)', '["Lieutenant","Mythe"]', 'Gamemaster Guide', 241, '{"rank":"lieutenant","truths":["Ingénieur des Profonds","Ruse atavique","Amphibie"],"attributes":{"agility":8,"brawn":10,"coordination":11,"insight":10,"reason":11,"will":9},"skills":[{"key":"athletics","rank":3,"focuses":["Natation"]},{"key":"engineering","rank":4,"focuses":["Génie de combat","Explosifs"]},{"key":"fighting","rank":2,"focuses":["Main nue","Armes lourdes"]},{"key":"observation","rank":3,"focuses":["Instinct"]},{"key":"resilience","rank":3,"focuses":[]},{"key":"stealth","rank":2,"focuses":["Discrétion rurale"]},{"key":"survival","rank":2,"focuses":[]},{"key":"tactics","rank":1,"focuses":[]}],"stress":13,"injuries":2,"armour":4,"courage":4,"attacks":[{"name":"Griffes sauvages","focus":"Main nue","range":"contact","damage":4,"salvo":null,"qualities":"Perforant 1","escalation":false},{"name":"Horrifique","focus":"Attaque mentale","range":null,"damage":4,"salvo":null,"qualities":"Perforant 1, Étourdissant","escalation":false},{"name":"Projecteur des Profonds (grenades-poissons-globes)","focus":"Armes lourdes","range":"long","damage":7,"salvo":"Étourdissant","qualities":"Zone ; Indirect, Peu fiable","escalation":true},{"name":"Bombe foreuse","focus":"Lancer","range":null,"damage":5,"salvo":null,"qualities":"Intense ; Imprécis, Indirect, Munition","escalation":true},{"name":"Mine mollusque","focus":"Explosifs","range":null,"damage":10,"salvo":null,"qualities":"Vicieux ; Munition","escalation":true}],"abilities":[{"name":"L''œil de l''ingénieur","text":"L''ingénieur tire parti du terrain : si lui ou sa cible est au contact d''un couvert, il peut dépenser 1 Menace pour ajouter l''effet Vicieux à sa prochaine attaque."},{"name":"Effroyable 1","text":"La créature inspire la peur. Peut faire des attaques mentales, avec +1 et l''effet Perforant 1 (inclus ci-dessus). De plus, la première fois qu''un personnage voit cette créature, il doit aussitôt réussir un test de Volonté + Résilience de difficulté 1 ou subir un stress mental comme s''il était victime de cette attaque mentale."},{"name":"Immunité (froid extrême)","text":"Immunisé contre le stress, les vérités et autres effets causés par : froid extrême."},{"name":"Vision nocturne","text":"Voit dans l''obscurité : ignore toute hausse de difficulté ou de plage de complication due au manque de lumière, et peut tenter des tests normalement impossibles dans le noir."},{"name":"Taille 1","text":"Subit une blessure après avoir subi 6 stress (après réductions) d''une seule attaque, au lieu de 5. D''autres actions peuvent être plus faciles ou plus difficiles selon sa taille."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Ingénieur des Profonds' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Brise-récif des Profonds', 'Champion et chef des Profonds', 'Bêtes massives et brutales même selon les critères de leur espèce, les brise-récifs sont plus grands, plus rapides et plus vicieux que leurs suivants : ce sont les chefs et champions de leur race. Couverts de bijoux étranges et armés de leurs armes barbares, ils laissent rarement des survivants pour raconter la rencontre. (VO : Deep One Reefbreaker)', '["Lieutenant","Mythe"]', 'Gamemaster Guide', 241, '{"rank":"lieutenant","truths":["Champion et chef des Profonds","Puissant par la vitesse et la stature","Amphibie"],"attributes":{"agility":10,"brawn":13,"coordination":10,"insight":10,"reason":9,"will":11},"skills":[{"key":"athletics","rank":4,"focuses":["Natation"]},{"key":"fighting","rank":5,"focuses":["Main nue","Armes de mêlée"]},{"key":"observation","rank":3,"focuses":[]},{"key":"persuasion","rank":2,"focuses":[]},{"key":"resilience","rank":4,"focuses":["Endurance"]},{"key":"survival","rank":2,"focuses":[]},{"key":"tactics","rank":3,"focuses":["Commandement"]}],"stress":17,"injuries":3,"armour":6,"courage":6,"attacks":[{"name":"Griffes sauvages","focus":"Main nue","range":"contact","damage":6,"salvo":null,"qualities":"Perforant 1","escalation":false},{"name":"Coup brutal","focus":"Main nue","range":"contact","damage":6,"salvo":null,"qualities":"Étourdissant","escalation":false},{"name":"Grenades-poissons-globes","focus":"Lancer","range":"close","damage":7,"salvo":null,"qualities":"Zone, Étourdissant ; Imprécis, Munition","escalation":false},{"name":"Horrifique","focus":"Attaque mentale","range":null,"damage":6,"salvo":null,"qualities":"Perforant 2, Étourdissant","escalation":false},{"name":"Lance empaleuse","focus":"Armes de mêlée","range":"contact","damage":8,"salvo":null,"qualities":"Intense, Perforant 1","escalation":true}],"abilities":[{"name":"Armure de brume (option d''escalade)","text":"Cette armure gélatineuse ajoute +2 à l''Armure de son porteur, et la brume qu''elle exhale lui donne la vérité Dissimulé."},{"name":"Brutal 1","text":"Fait et défend ses attaques de mêlée avec la Force au lieu de l''Agilité. Ajoute +1 à ses attaques de mêlée (inclus ci-dessus)."},{"name":"Effroyable 2","text":"La créature inspire la peur. Peut faire des attaques mentales, avec +2 et l''effet Perforant 2 (inclus ci-dessus). De plus, la première fois qu''un personnage voit cette créature, il doit aussitôt réussir un test de Volonté + Résilience de difficulté 2 ou subir un stress mental comme s''il était victime de cette attaque mentale."},{"name":"Immunité (froid extrême)","text":"Immunisé contre le stress, les vérités et autres effets causés par : froid extrême."},{"name":"Mener depuis les profondeurs","text":"Tant qu''un brise-récif est présent dans la scène, tous les guerriers des Profonds peuvent relancer 2 dés de combat quand ils infligent du stress, et réduisent de 1 (minimum 1) la difficulté de tout test utilisant la Volonté."},{"name":"Menaçant","text":"Sa seule présence est de mauvais augure : quand la créature apparaît pour la première fois dans une scène, générez 1 Menace."},{"name":"Vision nocturne","text":"Voit dans l''obscurité : ignore toute hausse de difficulté ou de plage de complication due au manque de lumière, et peut tenter des tests normalement impossibles dans le noir."},{"name":"Taille 2","text":"Subit une blessure après avoir subi 7 stress (après réductions) d''une seule attaque, au lieu de 5. D''autres actions peuvent être plus faciles ou plus difficiles selon sa taille."},{"name":"Coriace 1","text":"Peut encaisser 1 blessure supplémentaire (incluse ci-dessus). Peut aussi dépenser 3 Menace pour ignorer une blessure."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Brise-récif des Profonds' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Ancien des Profonds', 'Chef secret des Profonds', 'Rarement vus, même par les habitants des abysses, les anciens sont les chefs secrets de la race. C''est un ancien, escorté de brise-récifs, qui vient sceller les rares marchés avec la surface, et qui guide parfois les Profonds à la guerre, inspiré par la sagesse du Père Dagon, de la Mère Hydra ou du grand Cthulhu lui-même. (VO : Deep One Elder)', '["Némésis","Mythe"]', 'Gamemaster Guide', 242, '{"rank":"nemesis","truths":["Ancien chef des Profonds","Inspiration divine","Amphibie"],"attributes":{"agility":8,"brawn":9,"coordination":9,"insight":12,"reason":11,"will":13},"skills":[{"key":"academia","rank":4,"focuses":["Occultisme"]},{"key":"athletics","rank":3,"focuses":["Natation"]},{"key":"fighting","rank":1,"focuses":[]},{"key":"observation","rank":5,"focuses":["Instinct"]},{"key":"resilience","rank":3,"focuses":["Discipline"]},{"key":"survival","rank":2,"focuses":[]},{"key":"tactics","rank":3,"focuses":["Tactiques du champ de bataille"]}],"stress":16,"injuries":3,"armour":2,"courage":6,"attacks":[{"name":"Griffes sauvages","focus":"Main nue","range":"contact","damage":3,"salvo":null,"qualities":"Perforant 1","escalation":false},{"name":"Horrifique","focus":"Attaque mentale","range":null,"damage":7,"salvo":null,"qualities":"Perforant 2, Étourdissant","escalation":false}],"abilities":[{"name":"Armure de brume (option d''escalade)","text":"Cette armure gélatineuse ajoute +2 à l''Armure de son porteur, et la brume qu''elle exhale lui donne la vérité Dissimulé."},{"name":"Sagesse ancestrale","text":"Les anciens connaissent intimement l''histoire et les comportements de leur race : chaque fois qu''un autre Profond à portée courte dépense de la Menace, lancez 1 dé de combat par point dépensé ; chaque effet obtenu rend 1 point de Menace à la réserve."},{"name":"Effroyable 2","text":"La créature inspire la peur. Peut faire des attaques mentales, avec +2 et l''effet Perforant 2 (inclus ci-dessus). De plus, la première fois qu''un personnage voit cette créature, il doit aussitôt réussir un test de Volonté + Résilience de difficulté 2 ou subir un stress mental comme s''il était victime de cette attaque mentale."},{"name":"Immunité (froid extrême)","text":"Immunisé contre le stress, les vérités et autres effets causés par : froid extrême."},{"name":"Vision nocturne","text":"Voit dans l''obscurité : ignore toute hausse de difficulté ou de plage de complication due au manque de lumière, et peut tenter des tests normalement impossibles dans le noir."},{"name":"Inquiétant 5","text":"Quand la créature apparaît pour la première fois dans une scène, elle génère 5 Menace qu''elle seule peut utiliser."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Ancien des Profonds' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Chaman des Profonds', 'Prêtre des Dieux très anciens', 'Le culte du Père Dagon, de la Mère Hydra et, au-delà, de Cthulhu rythme la vie des Profonds, et ses rites blasphèmes sont menés par des chamans, êtres étranges et ratatinés. Enveloppés de robes épaisses, parfois porteurs d''un totem de métal étrange, ils invoquent en plein combat, d''une voix rauque, des êtres qu''il vaut mieux ne pas nommer. (VO : Deep One Shaman)', '["Némésis","Mythe"]', 'Gamemaster Guide', 243, '{"rank":"nemesis","truths":["Prêtre profond des Dieux très anciens","Inspiration divine","Amphibie"],"attributes":{"agility":8,"brawn":11,"coordination":9,"insight":12,"reason":11,"will":13},"skills":[{"key":"academia","rank":4,"focuses":["Occultisme"]},{"key":"athletics","rank":3,"focuses":["Natation"]},{"key":"fighting","rank":1,"focuses":[]},{"key":"observation","rank":5,"focuses":["Instinct"]},{"key":"persuasion","rank":3,"focuses":["Invocation"]},{"key":"resilience","rank":3,"focuses":["Discipline"]},{"key":"survival","rank":2,"focuses":[]},{"key":"tactics","rank":1,"focuses":[]}],"stress":16,"injuries":3,"armour":3,"courage":6,"attacks":[{"name":"Griffes sauvages","focus":"Main nue","range":"contact","damage":4,"salvo":null,"qualities":"Perforant 1","escalation":false},{"name":"Horrifique","focus":"Attaque mentale","range":null,"damage":7,"salvo":null,"qualities":"Perforant 2, Étourdissant","escalation":false},{"name":"Bâton totémique","focus":"Armes de mêlée","range":"contact","damage":5,"salvo":null,"qualities":"Vidange, Étourdissant","escalation":true}],"abilities":[{"name":"Prêcheur des ténèbres","text":"Le chaman prie les Dieux très anciens en des mots qui ne devraient jamais être entendus. Quand il fait une attaque mentale, il peut dépenser 3 Menace pour lui ajouter les effets Zone et Vidange."},{"name":"Effroyable 2","text":"La créature inspire la peur. Peut faire des attaques mentales, avec +2 et l''effet Perforant 2 (inclus ci-dessus). De plus, la première fois qu''un personnage voit cette créature, il doit aussitôt réussir un test de Volonté + Résilience de difficulté 2 ou subir un stress mental comme s''il était victime de cette attaque mentale."},{"name":"Immunité (froid extrême)","text":"Immunisé contre le stress, les vérités et autres effets causés par : froid extrême."},{"name":"Vision nocturne","text":"Voit dans l''obscurité : ignore toute hausse de difficulté ou de plage de complication due au manque de lumière, et peut tenter des tests normalement impossibles dans le noir."},{"name":"Lanceur de sorts","text":"Peut lancer les sorts Appel des profondeurs et Malédiction de Cthulhu. Il les lance avec la Perception, avec une Puissance de 5."},{"name":"Inquiétant 3","text":"Quand la créature apparaît pour la première fois dans une scène, elle génère 3 Menace qu''elle seule peut utiliser."},{"name":"Sorts et rituels","text":"Puissance 5. Lance ses sorts avec la Perception et connaît des sorts du grimoire de Cthulhu : en général Appel des profondeurs, Malédiction de Cthulhu et Écho de l''océan, ainsi que le rituel Communion avec la divinité ; le MJ peut en choisir d''autres."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Chaman des Profonds' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Adepte des Profonds', 'Guérisseur des Profonds', 'La médecine des Profonds mêle science avancée et remèdes océaniques enseignés à une époque oubliée : des mots gutturaux prononcés sur les plaies, puis des cataplasmes d''étoiles de mer. On aperçoit parfois des adeptes sur les champs de bataille de la Guerre secrète, soignant les Profonds tombés. (VO : Deep One Adept)', '["Lieutenant","Mythe"]', 'Gamemaster Guide', 243, '{"rank":"lieutenant","truths":["Guérisseur des Profonds","Rites anciens et science impossible","Amphibie"],"attributes":{"agility":8,"brawn":11,"coordination":12,"insight":9,"reason":10,"will":10},"skills":[{"key":"athletics","rank":3,"focuses":["Natation"]},{"key":"fighting","rank":2,"focuses":["Main nue"]},{"key":"medicine","rank":4,"focuses":["Médecine de combat"]},{"key":"observation","rank":3,"focuses":["Instinct"]},{"key":"resilience","rank":3,"focuses":[]},{"key":"stealth","rank":2,"focuses":["Discrétion rurale"]},{"key":"survival","rank":2,"focuses":[]},{"key":"tactics","rank":1,"focuses":[]}],"stress":14,"injuries":2,"armour":4,"courage":5,"attacks":[{"name":"Griffes sauvages","focus":"Main nue","range":"contact","damage":4,"salvo":null,"qualities":"Perforant 1","escalation":false},{"name":"Horrifique","focus":"Attaque mentale","range":null,"damage":4,"salvo":null,"qualities":"Perforant 1, Étourdissant","escalation":false}],"abilities":[{"name":"Effroyable 1","text":"La créature inspire la peur. Peut faire des attaques mentales, avec +1 et l''effet Perforant 1 (inclus ci-dessus). De plus, la première fois qu''un personnage voit cette créature, il doit aussitôt réussir un test de Volonté + Résilience de difficulté 1 ou subir un stress mental comme s''il était victime de cette attaque mentale."},{"name":"Rites de guérison","text":"L''adepte peut tenter un test de Coordination + Médecine de difficulté 2 sur un Profond vaincu. En cas de réussite, celui-ci n''est plus vaincu et récupère la moitié de son stress ; jusqu''à la fin de la scène, il peut ignorer les effets de ses blessures."},{"name":"Immunité (froid extrême)","text":"Immunisé contre le stress, les vérités et autres effets causés par : froid extrême."},{"name":"Vision nocturne","text":"Voit dans l''obscurité : ignore toute hausse de difficulté ou de plage de complication due au manque de lumière, et peut tenter des tests normalement impossibles dans le noir."},{"name":"Taille 1","text":"Subit une blessure après avoir subi 6 stress (après réductions) d''une seule attaque, au lieu de 5. D''autres actions peuvent être plus faciles ou plus difficiles selon sa taille."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Adepte des Profonds' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Envoûteur des Profonds', 'Disciple des Dieux très anciens', 'Rompu à la magie, l''envoûteur manie les rituels cachés de la sorcellerie de Cthulhu, puisant dans la puissance élémentaire des abysses et dans les rêves du dieu pour plier le monde à sa volonté. Il est prêt à payer un prix hideux pour atteindre ses buts innommables. (VO : Deep One Warlock)', '["Némésis","Mythe"]', 'Gamemaster Guide', 244, '{"rank":"nemesis","truths":["Disciple profond des Dieux très anciens","Pouvoir maudit","Amphibie"],"attributes":{"agility":8,"brawn":11,"coordination":9,"insight":12,"reason":11,"will":13},"skills":[{"key":"academia","rank":4,"focuses":["Occultisme"]},{"key":"athletics","rank":3,"focuses":["Natation"]},{"key":"fighting","rank":1,"focuses":[]},{"key":"observation","rank":5,"focuses":["Instinct"]},{"key":"resilience","rank":3,"focuses":["Discipline"]},{"key":"survival","rank":2,"focuses":["Mysticisme"]},{"key":"tactics","rank":1,"focuses":[]}],"stress":16,"injuries":3,"armour":2,"courage":6,"attacks":[{"name":"Griffes sauvages","focus":"Main nue","range":"contact","damage":4,"salvo":null,"qualities":"Perforant 1","escalation":false},{"name":"Horrifique","focus":"Attaque mentale","range":null,"damage":7,"salvo":null,"qualities":"Perforant 2, Étourdissant","escalation":false}],"abilities":[{"name":"Effroyable 2","text":"La créature inspire la peur. Peut faire des attaques mentales, avec +2 et l''effet Perforant 2 (inclus ci-dessus). De plus, la première fois qu''un personnage voit cette créature, il doit aussitôt réussir un test de Volonté + Résilience de difficulté 2 ou subir un stress mental comme s''il était victime de cette attaque mentale."},{"name":"Immunité (froid extrême)","text":"Immunisé contre le stress, les vérités et autres effets causés par : froid extrême."},{"name":"Menaçant","text":"Sa seule présence est de mauvais augure : quand la créature apparaît pour la première fois dans une scène, générez 1 Menace."},{"name":"Vision nocturne","text":"Voit dans l''obscurité : ignore toute hausse de difficulté ou de plage de complication due au manque de lumière, et peut tenter des tests normalement impossibles dans le noir."},{"name":"Payer le prix de bon gré","text":"L''envoûteur ajoute +1 à sa Puissance pour chaque blessure qu''il subit. Il ignore les effets des blessures sur ses tests quand il lance des sorts."},{"name":"Inquiétant 3","text":"Quand la créature apparaît pour la première fois dans une scène, elle génère 3 Menace qu''elle seule peut utiliser."},{"name":"Sorts et rituels","text":"Puissance 5. Lance ses sorts avec la Perception et connaît des sorts du grimoire de Cthulhu : en général Malédiction de Cthulhu, Tempête de vagues et Nageur du courant ancien ; le MJ peut en choisir d''autres."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Envoûteur des Profonds' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Aquamancien des Profonds', 'Sorcier des océans', 'Puisant à la fois dans la magie élémentaire et dans les ténèbres d''entre les étoiles, les aquamanciens sont parmi les sorciers les plus redoutables de la Guerre secrète. Les survivants de leurs assauts gardent une hydrophobie sévère, racontant la sueur de leur front qui s''enfonce dans leur crâne ou le contenu de leur gourde qui tente de les noyer. (VO : Deep One Aquamancer)', '["Némésis","Mythe"]', 'Gamemaster Guide', 244, '{"rank":"nemesis","truths":["Sorcier des Profonds","Parle à l''océan","Amphibie"],"attributes":{"agility":8,"brawn":11,"coordination":9,"insight":12,"reason":11,"will":13},"skills":[{"key":"academia","rank":3,"focuses":["Occultisme"]},{"key":"athletics","rank":3,"focuses":["Natation"]},{"key":"fighting","rank":1,"focuses":[]},{"key":"observation","rank":5,"focuses":["Instinct"]},{"key":"resilience","rank":3,"focuses":["Discipline"]},{"key":"survival","rank":4,"focuses":["Mysticisme"]},{"key":"tactics","rank":1,"focuses":[]}],"stress":17,"injuries":3,"armour":4,"courage":6,"attacks":[{"name":"Griffes sauvages","focus":"Main nue","range":"contact","damage":4,"salvo":null,"qualities":"Perforant 1","escalation":false},{"name":"Horrifique","focus":"Attaque mentale","range":null,"damage":7,"salvo":null,"qualities":"Perforant 2, Étourdissant","escalation":false}],"abilities":[{"name":"Armure de brume (option d''escalade)","text":"Cette armure gélatineuse ajoute +2 à l''Armure de son porteur, et la brume qu''elle exhale lui donne la vérité Dissimulé."},{"name":"Effroyable 2","text":"La créature inspire la peur. Peut faire des attaques mentales, avec +2 et l''effet Perforant 2 (inclus ci-dessus). De plus, la première fois qu''un personnage voit cette créature, il doit aussitôt réussir un test de Volonté + Résilience de difficulté 2 ou subir un stress mental comme s''il était victime de cette attaque mentale."},{"name":"Immunité (froid extrême)","text":"Immunisé contre le stress, les vérités et autres effets causés par : froid extrême."},{"name":"Vision nocturne","text":"Voit dans l''obscurité : ignore toute hausse de difficulté ou de plage de complication due au manque de lumière, et peut tenter des tests normalement impossibles dans le noir."},{"name":"Lanceur de sorts","text":"Peut lancer Bassin de félicité limpide, Écho de l''océan, Tempête de vagues et Appel de l''abîme (le MJ peut en choisir d''autres). Il les lance avec la Perception, avec une Puissance de 5."},{"name":"Inquiétant 4","text":"Quand la créature apparaît pour la première fois dans une scène, elle génère 4 Menace qu''elle seule peut utiliser."},{"name":"Sorts et rituels","text":"Puissance 5. Lance ses sorts avec la Perception et connaît en général, du grimoire de Cthulhu, Bassin de félicité limpide, Tempête de vagues et Appel de l''abîme, ainsi qu''un sort unique, Tombe aquatique ; le MJ peut en choisir d''autres."},{"name":"Tombe aquatique (sort)","text":"Perception + Survie, difficulté 2, coût : 5 Vidange, Perforant 1 [sic]. Vise un ennemi à portée courte d''une étendue d''eau. En cas de réussite, la cible subit 6 stress physique avec l''effet Piège. Si elle était déjà immergée ou couverte d''eau, ajoutez les effets Intense et Perforant 2."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Aquamancien des Profonds' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Grand Aquamage des Profonds', 'Archisorcier des océans', 'Aussi terrifiant que soit l''aquamancien, il n''est rien face au Grand Aquamage déchaîné, qui a voué son immortalité à communier avec les eaux noires de l''infini. Une seule observation est confirmée par la Section M : quelques minutes de radio délirante qui ont rendu fous les deux hommes qui l''ont reçue, désormais classées au-delà du Très secret. (VO : Deep One High Aquamage)', '["Némésis","Mythe"]', 'Gamemaster Guide', 245, '{"rank":"nemesis","truths":["Archisorcier des Profonds","Commande à l''océan","Amphibie"],"attributes":{"agility":8,"brawn":11,"coordination":9,"insight":12,"reason":11,"will":13},"skills":[{"key":"academia","rank":4,"focuses":["Occultisme"]},{"key":"athletics","rank":3,"focuses":["Natation"]},{"key":"fighting","rank":1,"focuses":[]},{"key":"observation","rank":5,"focuses":["Instinct"]},{"key":"persuasion","rank":3,"focuses":["Invocation"]},{"key":"resilience","rank":3,"focuses":["Discipline"]},{"key":"survival","rank":5,"focuses":["Mysticisme"]},{"key":"tactics","rank":1,"focuses":[]}],"stress":17,"injuries":4,"armour":4,"courage":7,"attacks":[{"name":"Griffes sauvages","focus":"Main nue","range":"contact","damage":4,"salvo":null,"qualities":"Perforant 1","escalation":false},{"name":"Horrifique","focus":"Attaque mentale","range":null,"damage":9,"salvo":null,"qualities":"Perforant 3, Étourdissant","escalation":false}],"abilities":[{"name":"Armure de brume (option d''escalade)","text":"Cette armure gélatineuse ajoute +2 à l''Armure de son porteur, et la brume qu''elle exhale lui donne la vérité Dissimulé."},{"name":"Commander les marées","text":"Au début de chaque tour du Grand Aquamage, l''un des effets des Marées contre nature prend effet, dans l''ordre : marée basse, marée montante, marée haute, reflux, puis la liste recommence. Les effets cessent aussitôt quand il est vaincu ou quitte la scène. Marée basse : les attaques contre un Profond à couvert ont +1 en difficulté. Marée montante : l''eau monte et jaillit du sol ou des égouts ; pour chaque Menace dépensée, il choisit une zone à portée longue qui reçoit la vérité Eaux montantes. Marée haute : toute attaque d''un Profond contre une créature immergée, ou dans une zone contenant de l''eau (dont Eaux montantes), gagne l''effet Vicieux ; les lanceurs de sorts profonds ont +1 Puissance. Reflux : retirez autant de vérités Eaux montantes (ou autres étendues d''eau, inondations) que voulu à portée longue, et gagnez 1 Menace par vérité retirée."},{"name":"Volonté extraordinaire 1","text":"Ajoute 1 succès automatique à tous ses tests de Volonté. Gagne aussi +1 Puissance, +1 aux attaques mentales, +1 Courage et +1 stress maximum (inclus)."},{"name":"Effroyable 3","text":"La créature inspire la terreur. Peut faire des attaques mentales, avec +3 et l''effet Perforant 3 (inclus ci-dessus). De plus, la première fois qu''un personnage voit cette créature, il doit aussitôt réussir un test de Volonté + Résilience de difficulté 1 ou subir un stress mental comme s''il était victime de cette attaque mentale."},{"name":"Immunité (froid extrême)","text":"Immunisé contre le stress, les vérités et autres effets causés par : froid extrême."},{"name":"Menaçant","text":"Sa seule présence est de mauvais augure : quand la créature apparaît pour la première fois dans une scène, générez 1 Menace."},{"name":"Vision nocturne","text":"Voit dans l''obscurité : ignore toute hausse de difficulté ou de plage de complication due au manque de lumière, et peut tenter des tests normalement impossibles dans le noir."},{"name":"Renouvelé par la marée","text":"S''il est au moins en partie immergé à la fin de son tour, il retire 5 stress. S''il commence son tour immergé, il peut dépenser 2 Menace pour retirer une de ses blessures."},{"name":"Taille 1","text":"Subit une blessure après avoir subi 6 stress (après réductions) d''une seule attaque, au lieu de 5. D''autres actions peuvent être plus faciles ou plus difficiles selon sa taille."},{"name":"Inquiétant 5","text":"Quand la créature apparaît pour la première fois dans une scène, elle génère 5 Menace qu''elle seule peut utiliser."},{"name":"Coriace 1","text":"Peut encaisser 1 blessure supplémentaire (incluse ci-dessus). Peut aussi dépenser 3 Menace pour ignorer une blessure."},{"name":"Sorts et rituels","text":"Puissance 7. Lance ses sorts avec la Volonté et connaît tous les sorts du grimoire de Cthulhu."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Grand Aquamage des Profonds' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Drone mi-go', 'Serviteur mi-go', 'Créatures hideuses mêlant champignon et chair, entre crabe et scorpion, avec deux ailes atrophiées : le drone est la forme de mi-go la plus courante sur Terre. Presque sans esprit, il obéit aux castes supérieures, mais reste un serviteur fiable et résistant, capable de manier la technologie extraterrestre des mi-go. (VO : Mi-Go Drone)', '["Troupe","Mythe"]', 'Gamemaster Guide', 247, '{"rank":"trooper","truths":["Fungi de Yuggoth"],"attributes":{"agility":8,"brawn":12,"coordination":8,"insight":9,"reason":9,"will":9},"skills":[{"key":"athletics","rank":1,"focuses":[]},{"key":"fighting","rank":3,"focuses":[]},{"key":"observation","rank":1,"focuses":[]},{"key":"resilience","rank":1,"focuses":[]}],"stress":4,"injuries":1,"armour":5,"courage":2,"attacks":[{"name":"Pinces","focus":"Main nue","range":"contact","damage":5,"salvo":null,"qualities":"Piège","escalation":false},{"name":"Surnaturel","focus":"Attaque mentale","range":null,"damage":4,"salvo":null,"qualities":"Perforant 1","escalation":false}],"abilities":[{"name":"Effroyable 1","text":"Le drone inspire la peur. Peut faire des attaques mentales, avec +1 et l''effet Perforant 1 (inclus ci-dessus). De plus, la première fois qu''un personnage voit cette créature, il doit aussitôt réussir un test de Volonté + Résilience de difficulté 1 ou subir un stress mental comme s''il était victime de cette attaque mentale."},{"name":"Vol","text":"Se déplace librement dans les zones aériennes au-dessus du champ de bataille. Porter des objets ou des créatures en vol peut demander un test d''Athlétisme + Force."},{"name":"Immunité (froid, vide)","text":"Immunisé contre le stress, les vérités et autres effets causés par : froid, vide."},{"name":"Sans esprit","text":"Entièrement mû par l''instinct, sans ordres il poursuit et attaque l''ennemi le plus proche. Il ne peut pas tenter de réaction, ne peut subir ni stress ni blessure mentale, et on ne peut pas le raisonner."},{"name":"Vision nocturne","text":"Voit dans l''obscurité : ignore toute hausse de difficulté ou de plage de complication due au manque de lumière, et peut tenter des tests normalement impossibles dans le noir."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Drone mi-go' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Mi-go augmenté', 'Soldat mi-go modifié', 'Ingénieurs géniaux, les mi-go modifient aussi leurs propres tissus fongiques : carapaces élargies, chitine renforcée, nouvelles armes greffées sur les pinces ou les mandibules. Les augmentés sont parmi leurs soldats les plus redoutables ; on dit que les Nachtwölfe ont capturé des drones pour leur faire subir un « perfectionnement » semblable. (VO : Augmented Mi-Go)', '["Lieutenant","Mythe"]', 'Gamemaster Guide', 247, '{"rank":"lieutenant","truths":["Fungi de Yuggoth","Conçu pour la guerre"],"attributes":{"agility":9,"brawn":12,"coordination":9,"insight":12,"reason":11,"will":11},"skills":[{"key":"athletics","rank":1,"focuses":[]},{"key":"fighting","rank":3,"focuses":["Exotique","Armes lourdes"]},{"key":"observation","rank":1,"focuses":[]},{"key":"resilience","rank":2,"focuses":["Endurance","Discipline"]}],"stress":14,"injuries":2,"armour":7,"courage":4,"attacks":[{"name":"Pinces","focus":"Main nue","range":"contact","damage":5,"salvo":null,"qualities":"Piège","escalation":false},{"name":"Désintégrateur","focus":"Armes lourdes","range":"long","damage":10,"salvo":"Vicieux","qualities":"Intense ; Fléau, Encombrant, Escalade, Tueur de géants, Fiable","escalation":false},{"name":"Surnaturel","focus":"Attaque mentale","range":null,"damage":5,"salvo":null,"qualities":"Perforant 1","escalation":false}],"abilities":[{"name":"Effroyable 1","text":"Le mi-go augmenté inspire la peur. Peut faire des attaques mentales, avec +1 et l''effet Perforant 1 (inclus ci-dessus). De plus, la première fois qu''un personnage voit cette créature, il doit aussitôt réussir un test de Volonté + Résilience de difficulté 1 ou subir un stress mental comme s''il était victime de cette attaque mentale."},{"name":"Vol","text":"Se déplace librement dans les zones aériennes au-dessus du champ de bataille. Porter des objets ou des créatures en vol peut demander un test d''Athlétisme + Force."},{"name":"Immunité (froid, peur, douleur, vide)","text":"Immunisé contre le stress, les vérités et autres effets causés par : froid, peur, douleur, vide."},{"name":"Vision nocturne","text":"Voit dans l''obscurité : ignore toute hausse de difficulté ou de plage de complication due au manque de lumière, et peut tenter des tests normalement impossibles dans le noir."},{"name":"Bénédiction de Yog-Sothoth","text":"Les mi-go, favoris de Yog-Sothoth, détournent une partie de la magie en invoquant son nom. Attaqué par un sort ou une autre attaque magique, un mi-go peut tenter une réaction pour se protéger : la difficulté du test du sort ou de l''attaque magique augmente de +1."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Mi-go augmenté' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Scientifique mi-go', 'Savant mi-go', 'Les mi-go fonctionnent en esprit de ruche, et les drones sont les plus souvent observés. Plus rares, les scientifiques dirigent leurs frères inférieurs par contrôle mental et phéromones ; très intelligents, ils se reconnaissent à leur boîte crânienne plus grosse, à leurs mandibules raffinées pour goûter les échantillons et à leurs grandes antennes. (VO : Mi-Go Scientist)', '["Lieutenant","Mythe"]', 'Gamemaster Guide', 248, '{"rank":"lieutenant","truths":["Fungi de Yuggoth","Science extraterrestre impossible"],"attributes":{"agility":9,"brawn":12,"coordination":9,"insight":13,"reason":12,"will":11},"skills":[{"key":"academia","rank":4,"focuses":["Science","Occultisme"]},{"key":"athletics","rank":1,"focuses":[]},{"key":"engineering","rank":3,"focuses":["Électronique"]},{"key":"fighting","rank":3,"focuses":["Exotique"]},{"key":"medicine","rank":3,"focuses":[]},{"key":"observation","rank":1,"focuses":[]},{"key":"resilience","rank":2,"focuses":["Discipline"]}],"stress":14,"injuries":2,"armour":5,"courage":4,"attacks":[{"name":"Pinces","focus":"Main nue","range":"contact","damage":5,"salvo":null,"qualities":"Piège","escalation":false},{"name":"Fusil électrique","focus":"Exotique","range":"long","damage":8,"salvo":"Vicieux","qualities":"Étourdissant ; Fléau, Encombrant, Escalade","escalation":false},{"name":"Surnaturel","focus":"Intimidation","range":null,"damage":5,"salvo":null,"qualities":"Attaque mentale (Volonté + Résilience [sic]) ; Perforant 1","escalation":false}],"abilities":[{"name":"Effroyable 1","text":"Le scientifique mi-go inspire la peur. Peut faire des attaques mentales, avec +1 et l''effet Perforant 1 (inclus ci-dessus). De plus, la première fois qu''un personnage voit cette créature, il doit aussitôt réussir un test de Volonté + Résilience de difficulté 1 ou subir un stress mental comme s''il était victime de cette attaque mentale."},{"name":"Vol","text":"Se déplace librement dans les zones aériennes au-dessus du champ de bataille. Porter des objets ou des créatures en vol peut demander un test d''Athlétisme + Force."},{"name":"Immunité (froid, peur, douleur, vide)","text":"Immunisé contre le stress, les vérités et autres effets causés par : froid, peur, douleur, vide."},{"name":"Vision nocturne","text":"Voit dans l''obscurité : ignore toute hausse de difficulté ou de plage de complication due au manque de lumière, et peut tenter des tests normalement impossibles dans le noir."},{"name":"Science suffisamment avancée","text":"Une fois par scène, le scientifique peut dépenser 2 Menace pour tenter un test de Volonté + Ingénierie de difficulté 2. En cas de réussite, toute technologie non mi-go à portée moyenne cesse de fonctionner ; portée longue s''il dépense 2 Menace de plus."},{"name":"Bénédiction de Yog-Sothoth","text":"Les mi-go, favoris de Yog-Sothoth, détournent une partie de la magie en invoquant son nom. Attaqué par un sort ou une autre attaque magique, un mi-go peut tenter une réaction pour se protéger : la difficulté du test du sort ou de l''attaque magique augmente de +1."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Scientifique mi-go' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Centurion mi-go', 'Brute de guerre mi-go', 'Quand la ruche est menacée, le centurion répond à l''appel. Six pattes, ailes atrophiées, armure de chitine épaisse, pinces et mandibules pour le corps à corps et une paire de griffes plus agiles pour ses armes soniques : il a peu de points faibles, hormis la gorge et les articulations des pattes où ses parties fongiques sont exposées. (VO : Mi-Go Centurion)', '["Lieutenant","Mythe"]', 'Gamemaster Guide', 249, '{"rank":"lieutenant","truths":["Fungi de Yuggoth","Troupe de choc cuirassée de chitine"],"attributes":{"agility":9,"brawn":13,"coordination":10,"insight":12,"reason":11,"will":11},"skills":[{"key":"athletics","rank":2,"focuses":[]},{"key":"fighting","rank":4,"focuses":["Exotique","Main nue","Armes lourdes"]},{"key":"observation","rank":1,"focuses":[]},{"key":"resilience","rank":4,"focuses":["Endurance","Discipline"]}],"stress":17,"injuries":3,"armour":8,"courage":6,"attacks":[{"name":"Pinces","focus":"Main nue","range":"contact","damage":6,"salvo":null,"qualities":"Vicieux","escalation":false},{"name":"Désintégrateur","focus":"Armes lourdes","range":"long","damage":10,"salvo":"Vicieux","qualities":"Intense ; Fléau, Encombrant, Escalade, Tueur de géants, Fiable","escalation":false},{"name":"Surnaturel","focus":"Attaque mentale","range":null,"damage":5,"salvo":null,"qualities":"Perforant 1","escalation":false}],"abilities":[{"name":"Brutal 1","text":"Fait et défend ses attaques de mêlée avec la Force au lieu de l''Agilité. Ajoute +1 à ses attaques de mêlée (inclus ci-dessus)."},{"name":"Effroyable 1","text":"Le centurion inspire la peur. Peut faire des attaques mentales, avec +1 et l''effet Perforant 1 (inclus ci-dessus). De plus, la première fois qu''un personnage voit cette créature, il doit aussitôt réussir un test de Volonté + Résilience de difficulté 1 ou subir un stress mental comme s''il était victime de cette attaque mentale."},{"name":"Immunité (froid, peur, douleur, vide)","text":"Immunisé contre le stress, les vérités et autres effets causés par : froid, peur, douleur, vide."},{"name":"Vision nocturne","text":"Voit dans l''obscurité : ignore toute hausse de difficulté ou de plage de complication due au manque de lumière, et peut tenter des tests normalement impossibles dans le noir."},{"name":"Taille 1","text":"Subit une blessure après avoir subi 6 stress (après réductions) d''une seule attaque, au lieu de 5. D''autres actions peuvent être plus faciles ou plus difficiles selon sa taille."},{"name":"Coriace 1","text":"Peut encaisser 1 blessure supplémentaire (incluse ci-dessus). Peut aussi dépenser 3 Menace pour ignorer une blessure."},{"name":"Rage irrésistible","text":"Quand le centurion se déplace au contact d''un adversaire puis fait une attaque de mêlée, l''attaque le renverse au sol et inflige +2 dés de stress. S''il charge ainsi, il gagne +2 de couverture jusqu''au début de son prochain tour."},{"name":"Bénédiction de Yog-Sothoth","text":"Les mi-go, favoris de Yog-Sothoth, détournent une partie de la magie en invoquant son nom. Attaqué par un sort ou une autre attaque magique, un mi-go peut tenter une réaction pour se protéger : la difficulté du test du sort ou de l''attaque magique augmente de +1."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Centurion mi-go' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Princesse mi-go', 'Commandante psionique', 'Bien loin des contes de fées, la princesse est une sœur stérile de la Reine émergente, présence géante et dominatrice quand elle paraît sur un champ de bataille. Armée jusqu''aux mandibules d''armes soniques, elle use aussi de pouvoirs psioniques pour coordonner les mi-go ou dévaster ceux qui la menacent. (VO : Mi-Go Princess)', '["Némésis","Mythe"]', 'Gamemaster Guide', 249, '{"rank":"nemesis","truths":["Fungi de Yuggoth","Commandante psionique"],"attributes":{"agility":9,"brawn":11,"coordination":11,"insight":13,"reason":11,"will":11},"skills":[{"key":"academia","rank":3,"focuses":["Science","Occultisme"]},{"key":"athletics","rank":1,"focuses":[]},{"key":"fighting","rank":3,"focuses":["Exotique"]},{"key":"observation","rank":3,"focuses":["Instinct"]},{"key":"resilience","rank":2,"focuses":["Discipline"]},{"key":"tactics","rank":3,"focuses":["Tactiques du champ de bataille"]}],"stress":13,"injuries":3,"armour":8,"courage":4,"attacks":[{"name":"Pinces","focus":"Main nue","range":"contact","damage":4,"salvo":null,"qualities":"Piège","escalation":false},{"name":"Disrupteurs soniques","focus":"Exotique","range":"long","damage":9,"salvo":"Zone","qualities":"Étourdissant ; Fiable","escalation":false},{"name":"Présence psychique","focus":"Attaque mentale","range":null,"damage":6,"salvo":null,"qualities":"Vidange, Perforant 2","escalation":false}],"abilities":[{"name":"Effroyable 2","text":"La princesse inspire la peur. Peut faire des attaques mentales, avec +2 et l''effet Perforant 2 (inclus ci-dessus). De plus, la première fois qu''un personnage voit cette créature, il doit aussitôt réussir un test de Volonté + Résilience de difficulté 2 ou subir un stress mental comme s''il était victime de cette attaque mentale."},{"name":"Vol","text":"Se déplace librement dans les zones aériennes au-dessus du champ de bataille. Porter des objets ou des créatures en vol peut demander un test d''Athlétisme + Force."},{"name":"Immunité (froid, peur, douleur, vide)","text":"Immunisé contre le stress, les vérités et autres effets causés par : froid, peur, douleur, vide."},{"name":"Vision nocturne","text":"Voit dans l''obscurité : ignore toute hausse de difficulté ou de plage de complication due au manque de lumière, et peut tenter des tests normalement impossibles dans le noir."},{"name":"Protégez la princesse !","text":"Les autres mi-go ne laisseront rien lui arriver : les mi-go à portée courte de la princesse gagnent une réaction ; quand elle est visée par une attaque, le mi-go qui réagit en devient la cible à sa place."},{"name":"Commandement psychique","text":"Au début de son tour, la princesse choisit une zone qu''elle voit ; jusqu''au début de son prochain tour, tous les mi-go PNJ Troupiers et Lieutenants de cette zone peuvent relancer un d20 lors d''une attaque ou d''un test."},{"name":"Taille 2","text":"Subit une blessure après avoir subi 7 stress (après réductions) d''une seule attaque, au lieu de 5. D''autres actions peuvent être plus faciles ou plus difficiles selon sa taille."},{"name":"Inquiétant 3","text":"Quand la créature apparaît pour la première fois dans une scène, elle génère 3 Menace qu''elle seule peut utiliser."},{"name":"Bénédiction de Yog-Sothoth","text":"Les mi-go, favoris de Yog-Sothoth, détournent une partie de la magie en invoquant son nom. Attaqué par un sort ou une autre attaque magique, un mi-go peut tenter une réaction pour se protéger : la difficulté du test du sort ou de l''attaque magique augmente de +1."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Princesse mi-go' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Reine émergente mi-go', 'Génitrice de colonie', 'Comme les abeilles, les reines émergentes quittent Yuggoth pour fonder de nouvelles colonies, et certaines viennent pondre sur Terre. Entièrement fongique, physiquement vulnérable mais d''une grande puissance psionique, elle est toujours entourée d''une cour de guerriers, de scientifiques et de drones, au fond de vastes repaires souterrains. (VO : Mi-Go Emerging Queen)', '["Némésis","Mythe"]', 'Gamemaster Guide', 251, '{"rank":"nemesis","truths":["Fungi de Yuggoth","Génitrice naissante"],"attributes":{"agility":7,"brawn":7,"coordination":12,"insight":13,"reason":11,"will":13},"skills":[{"key":"academia","rank":2,"focuses":["Science"]},{"key":"observation","rank":3,"focuses":[]},{"key":"persuasion","rank":4,"focuses":["Intimidation"]},{"key":"resilience","rank":4,"focuses":["Discipline"]}],"stress":17,"injuries":3,"armour":0,"courage":7,"attacks":[{"name":"Pinces","focus":"Main nue","range":"contact","damage":2,"salvo":null,"qualities":"Piège","escalation":false},{"name":"Puissance psychique","focus":"Attaque mentale","range":null,"damage":8,"salvo":null,"qualities":"Vidange, Perforant 3","escalation":false}],"abilities":[{"name":"Effroyable 3","text":"La reine inspire la terreur. Peut faire des attaques mentales, avec +3 et l''effet Perforant 3 (inclus ci-dessus). De plus, la première fois qu''un personnage voit cette créature, il doit aussitôt réussir un test de Volonté + Résilience de difficulté 3 ou subir un stress mental comme s''il était victime de cette attaque mentale."},{"name":"Vol","text":"Se déplace librement dans les zones aériennes au-dessus du champ de bataille. Porter des objets ou des créatures en vol peut demander un test d''Athlétisme + Force."},{"name":"Immunité (froid, peur, douleur, vide)","text":"Immunisé contre le stress, les vérités et autres effets causés par : froid, peur, douleur, vide."},{"name":"Longue vie à la reine !","text":"La reine est vitale pour la survie d''une colonie : les mi-go à portée courte gagnent une réaction ; quand elle est visée par une attaque, le mi-go qui réagit en devient la cible à sa place."},{"name":"Vision nocturne","text":"Voit dans l''obscurité : ignore toute hausse de difficulté ou de plage de complication due au manque de lumière, et peut tenter des tests normalement impossibles dans le noir."},{"name":"Décret psychique","text":"La reine peut choisir une zone qu''elle voit, plus une zone par Menace dépensée. Tous les mi-go de ces zones peuvent relancer un d20 à tous leurs tests et attaques, et gagnent +2 de couverture."},{"name":"Taille 1","text":"Subit une blessure après avoir subi 6 stress (après réductions) d''une seule attaque, au lieu de 5. D''autres actions peuvent être plus faciles ou plus difficiles selon sa taille."},{"name":"Inquiétant 3 [sic]","text":"Quand la créature apparaît pour la première fois dans une scène, elle génère 5 Menace qu''elle seule peut utiliser (le titre dit 3, le texte dit 5)."},{"name":"Bénédiction de Yog-Sothoth","text":"Les mi-go, favoris de Yog-Sothoth, détournent une partie de la magie en invoquant son nom. Attaqué par un sort ou une autre attaque magique, un mi-go peut tenter une réaction pour se protéger : la difficulté du test du sort ou de l''attaque magique augmente de +1."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Reine émergente mi-go' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Azathoth', 'Dieu idiot aveugle, Dieu extérieur', 'Le chaos nucléaire, cœur hideux et palpitant de l''univers : le dieu idiot aveugle, apaisé par la mince musique des sphères, d''où toute chose serait issue et où tout retournera. Beaucoup cherchent à invoquer sa puissance pour la maîtriser, et l''ont payé de leur esprit et de leur corps.', '["Némésis","Mythe"]', 'Gamemaster Guide', 252, '{"rank":"nemesis","truths":["Chaos nucléaire bouillonnant","Brûle au cœur de la création","Fureur aveugle"],"attributes":{"agility":null,"brawn":20,"coordination":null,"insight":null,"reason":null,"will":20},"skills":[{"key":"resilience","rank":5,"focuses":[]}],"stress":30,"injuries":5,"armour":5,"courage":10,"attacks":[{"name":"Pseudopode fouettant","focus":null,"range":null,"damage":8,"salvo":null,"qualities":"Vidange, Perforant 1","escalation":false},{"name":"Présence dévastatrice","focus":"Attaque mentale","range":null,"damage":11,"salvo":null,"qualities":"Intense, Persistant 6, Perforant 4","escalation":false}],"abilities":[{"name":"Attaques","text":"Azathoth peut faire autant d''attaques de pseudopode et de présence qu''il veut à chacun de ses tours, sans test : il dépense une ou plusieurs Menace pour attaquer une créature à portée moyenne. La créature peut éviter l''attaque par un test d''Agilité + Athlétisme (attaque physique) ou de Volonté + Résilience (attaque mentale) de difficulté égale à la Menace dépensée."},{"name":"Volonté extraordinaire 5","text":"Ajoute 5 succès automatiques à tous ses tests de Volonté. Gagne aussi +5 aux attaques mentales, +5 Courage et +5 stress maximum (inclus)."},{"name":"Effroyable 4","text":"Azathoth inspire une terreur abjecte et indescriptible. Peut faire des attaques mentales, avec +4 et l''effet Perforant 4 (inclus ci-dessus). De plus, la première fois qu''un personnage voit cette créature, il doit aussitôt réussir un test de Volonté + Résilience de difficulté 4 ou subir un stress mental comme s''il était victime de cette attaque mentale."},{"name":"Cœur de l''univers","text":"Contempler sa forme brute, c''est fixer la création elle-même : au début de chacun de ses tours, Azathoth inflige 3 dés de dégâts physiques avec Vidange et Perforant 1 à toutes les créatures, personnages et objets à portée moyenne de sa forme physique invoquée. La zone devient de plus en plus calcinée et inhospitalière."},{"name":"Immunité (froid, maladie, peur, douleur, poison, chaleur, vide)","text":"Immunisé contre le stress, les vérités et autres effets causés par : froid, maladie, peur, douleur, poison, chaleur, vide."},{"name":"Invulnérable","text":"Ne peut subir de blessure d''aucune attaque physique ou mentale, hormis les attaques magiques. Si une attaque contre laquelle il est immunisé devait lui infliger une blessure, il perd à la place la possibilité d''agir à son prochain tour (non cumulatif) et 2 points sont aussitôt ajoutés à la Menace. Vaincu, il est seulement banni."},{"name":"Taille X","text":"Azathoth apparaît à la Taille 0. Au début de chacun de ses tours, il peut dépenser 2 Menace pour gagner +1 Taille. Au-delà de 5, il remplit sa zone et toutes ses capacités portent à portée longue au lieu de moyenne ; la suite est laissée au MJ. Il ne subit une blessure qu''après 5+X stress (après réductions) d''une seule attaque."},{"name":"Inquiétant 12","text":"Quand la créature apparaît pour la première fois dans une scène, elle génère 12 Menace qu''elle seule peut utiliser."},{"name":"Coriace 2","text":"Peut encaisser 2 blessures supplémentaires (incluses ci-dessus). Peut aussi dépenser 3 Menace pour ignorer une blessure."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Azathoth' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Cthulhu', 'Grand Ancien, seigneur de R''lyeh', 'Le grand dieu de R''lyeh attend en rêvant, mais son influence se fait sentir partout, dans les songes des esprits sensibles du monde entier. La guerre du Pacifique a troublé son sommeil, son culte est plus actif que jamais et a noué des pactes avec le Soleil noir et les Nachtwölfe ; il guide ses fidèles en attendant que les étoiles soient propices.', '["Némésis","Mythe"]', 'Gamemaster Guide', 253, '{"rank":"nemesis","truths":["En sa demeure de R''lyeh","Le défunt Cthulhu attend en rêvant","D''une stature de montagne","S''éveillera quand les étoiles seront propices"],"attributes":{"agility":9,"brawn":20,"coordination":10,"insight":15,"reason":15,"will":20},"skills":[{"key":"academia","rank":5,"focuses":["Occultisme"]},{"key":"athletics","rank":4,"focuses":["Natation"]},{"key":"fighting","rank":3,"focuses":["Main nue"]},{"key":"persuasion","rank":3,"focuses":["Invocation"]},{"key":"observation","rank":4,"focuses":["Instinct"]},{"key":"resilience","rank":5,"focuses":["Endurance","Discipline"]},{"key":"survival","rank":5,"focuses":["Mysticisme"]}],"stress":30,"injuries":5,"armour":12,"courage":12,"attacks":[{"name":"Griffes agrippantes","focus":"Main nue","range":"contact","damage":7,"salvo":null,"qualities":"Piège","escalation":false},{"name":"Rêves du terrible Cthulhu","focus":"Attaque mentale","range":null,"damage":11,"salvo":null,"qualities":"Étourdissant, Perforant 4","escalation":false}],"abilities":[{"name":"Une montagne marche","text":"Cthulhu domine tout champ de bataille : il peut faire des attaques de mêlée contre tout ennemi à portée courte, pas seulement au contact. À la fin de chacun de ses déplacements, lancez 1 dé de combat pour chaque créature ou objet destructible (véhicule...) à portée courte ; sur un effet, la cible est piétinée ou écrasée et subit 7 stress physique avec les effets Intense, Étourdissant et Vicieux."},{"name":"Force extraordinaire 3","text":"Ajoute 3 succès automatiques à tous ses tests de Force. Ajoute aussi +3 à ses attaques de mêlée, à son stress maximum et à son Armure (inclus ci-dessus)."},{"name":"Perception extraordinaire 2","text":"Ajoute 2 succès automatiques à ses tests de Perception."},{"name":"Raisonnement extraordinaire 2","text":"Ajoute 2 succès automatiques à ses tests de Raisonnement."},{"name":"Volonté extraordinaire 2","text":"Ajoute 2 succès automatiques à tous ses tests de Volonté. Gagne aussi +2 Puissance, +2 aux attaques mentales, +2 Courage et +2 stress maximum (inclus)."},{"name":"Récupération rapide 3","text":"Retire 3 stress à la fin de chacun de ses tours. Si elle a des blessures au début de son tour, elle peut dépenser 2 Menace pour en retirer une complètement. Cesse de fonctionner quand la créature est vaincue."},{"name":"Effroyable 4","text":"Cthulhu inspire une terreur abjecte et indescriptible. Peut faire des attaques mentales, avec +4 et l''effet Perforant 4 (inclus ci-dessus). De plus, la première fois qu''un personnage voit cette créature, il doit aussitôt réussir un test de Volonté + Résilience de difficulté 4 ou subir un stress mental comme s''il était victime de cette attaque mentale."},{"name":"Se repaître de la peur","text":"Chaque fois qu''un personnage à portée moyenne de la créature subit une blessure mentale, générez 2 Menace."},{"name":"Vol","text":"Se déplace librement dans les zones aériennes au-dessus du champ de bataille. Porter des objets ou des créatures en vol peut demander un test d''Athlétisme + Force."},{"name":"Immunité (froid, maladie, peur, douleur, poison, chaleur, vide)","text":"Immunisé contre le stress, les vérités et autres effets causés par : froid, maladie, peur, douleur, poison, chaleur, vide."},{"name":"Rêves insidieux","text":"Toutes les créatures ayant subi une ou plusieurs blessures mentales de Cthulhu pendant la scène sont affectées par ses rêves. Au début de son tour, une créature affectée peut retirer aussitôt toutes ses blessures mentales si elle laisse le MJ choisir ses actions pour ce tour."},{"name":"Menaçant","text":"Sa seule présence est de mauvais augure : quand la créature apparaît pour la première fois dans une scène, générez 1 Menace."},{"name":"Taille 10","text":"Subit une blessure après avoir subi 15 stress (après réductions) d''une seule attaque, au lieu de 5. D''autres actions peuvent être plus faciles ou plus difficiles selon sa taille."},{"name":"Avaler tout rond","text":"Si Cthulhu a saisi une créature de Taille 1 ou moins avec ses Griffes agrippantes (effet Piège), il peut utiliser son action pour la jeter dans sa gueule monstrueuse. La créature avalée est aussitôt vaincue et considérée comme mourante ; si Cthulhu est vaincu avant sa mort (voir N''est pas mort ce qui à jamais dort), elle peut être sauvée."},{"name":"N''est pas mort ce qui à jamais dort","text":"Vaincu, Cthulhu éclate et se dissout en un brouillard vert maladif qui plane sur le champ de bataille ; les personnages saisis ou avalés sont aussitôt relâchés. Il garde un tour dans cet état mais ne peut pas agir : lancez 1 dé de combat, plus 1 par tour consécutif passé sous cette forme incorporelle ; chaque effet soigne une de ses blessures. Une fois toutes ses blessures soignées, il récupère tout son stress, retire les vérités que lui ont infligées ses ennemis ou des incidents, et reprend forme solide."},{"name":"Inquiétant 12","text":"Quand la créature apparaît pour la première fois dans une scène, elle génère 12 Menace qu''elle seule peut utiliser."},{"name":"Coriace 2","text":"Peut encaisser 2 blessures supplémentaires (incluses ci-dessus). Peut aussi dépenser 3 Menace pour ignorer une blessure."},{"name":"Sorts et rituels","text":"Puissance 10. Lance ses sorts avec la Volonté et connaît tous les sorts et rituels que le MJ souhaite."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Cthulhu' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Père Dagon et Mère Hydra', 'Souverains des Profonds', 'Enfants de Cthulhu, fragments de sa chair immortelle détachés il y a des éons pour engendrer la race des Profonds et la gouverner jusqu''au réveil du dieu. Idoles déchues de civilisations oubliées, ils reçoivent au fond des océans les cérémonies immondes de leurs descendants. Un même profil sert pour l''un ou l''autre. (VO : Father Dagon and Mother Hydra)', '["Némésis","Mythe"]', 'Gamemaster Guide', 254, '{"rank":"nemesis","truths":["Souverains des Profonds","Grands serviteurs de Cthulhu"],"attributes":{"agility":11,"brawn":18,"coordination":11,"insight":18,"reason":10,"will":17},"skills":[{"key":"academia","rank":4,"focuses":["Occultisme"]},{"key":"athletics","rank":4,"focuses":["Natation"]},{"key":"fighting","rank":5,"focuses":["Main nue"]},{"key":"observation","rank":3,"focuses":[]},{"key":"persuasion","rank":3,"focuses":["Invocation"]},{"key":"resilience","rank":4,"focuses":["Endurance"]},{"key":"survival","rank":4,"focuses":["Mysticisme"]},{"key":"tactics","rank":4,"focuses":["Commandement"]}],"stress":24,"injuries":4,"armour":9,"courage":10,"attacks":[{"name":"Griffes sauvages","focus":"Main nue","range":"contact","damage":10,"salvo":null,"qualities":"Perforant 1","escalation":false},{"name":"Coup brutal","focus":"Main nue","range":"contact","damage":10,"salvo":null,"qualities":"Étourdissant","escalation":false},{"name":"Horrifique","focus":"Attaque mentale","range":null,"damage":11,"salvo":null,"qualities":"Perforant 3, Étourdissant","escalation":false}],"abilities":[{"name":"Sagesse ancestrale","text":"Souverains antiques des Profonds, Dagon et Hydra les commandent d''une main de fer : chaque fois qu''un Profond à portée moyenne de l''un d''eux dépense de la Menace, lancez 1 dé de combat par point dépensé ; chaque effet rend 1 point de Menace à la réserve."},{"name":"Brutal 2","text":"Fait et défend ses attaques de mêlée avec la Force au lieu de l''Agilité. Ajoute +2 à ses attaques de mêlée (inclus ci-dessus)."},{"name":"Force extraordinaire 1","text":"Ajoute 1 succès automatique à tous ses tests de Force. Ajoute aussi +1 à ses attaques de mêlée, à son stress maximum et à son Armure (inclus ci-dessus)."},{"name":"Volonté extraordinaire 1","text":"Ajoute 1 succès automatique à tous ses tests de Volonté. Gagne aussi +1 Puissance, +1 aux attaques mentales, +1 Courage et +1 stress maximum (inclus)."},{"name":"Effroyable 3","text":"La créature inspire la terreur. Peut faire des attaques mentales, avec +3 et l''effet Perforant 3 (inclus ci-dessus). De plus, la première fois qu''un personnage voit cette créature, il doit aussitôt réussir un test de Volonté + Résilience de difficulté 3 ou subir un stress mental comme s''il était victime de cette attaque mentale."},{"name":"Immunité (froid extrême, peur, poison)","text":"Immunisé contre le stress, les vérités et autres effets causés par : froid extrême, peur, poison."},{"name":"Menaçant","text":"Sa seule présence est de mauvais augure : quand la créature apparaît pour la première fois dans une scène, générez 1 Menace."},{"name":"Vision nocturne","text":"Voit dans l''obscurité : ignore toute hausse de difficulté ou de plage de complication due au manque de lumière, et peut tenter des tests normalement impossibles dans le noir."},{"name":"Taille 4","text":"Subit une blessure après avoir subi 9 stress (après réductions) d''une seule attaque, au lieu de 5. D''autres actions peuvent être plus faciles ou plus difficiles selon sa taille."},{"name":"Inquiétant 9","text":"Quand la créature apparaît pour la première fois dans une scène, elle génère 9 Menace qu''elle seule peut utiliser."},{"name":"Coriace 1","text":"Peut encaisser 1 blessure supplémentaire (incluse ci-dessus). Peut aussi dépenser 3 Menace pour ignorer une blessure."},{"name":"Sorts et rituels","text":"Puissance 9. Tous deux lancent leurs sorts avec la Volonté et connaissent tous les sorts du grimoire de Cthulhu, ainsi que tout rituel que le MJ juge approprié."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Père Dagon et Mère Hydra' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Hastur, le Roi en jaune', 'Grand Ancien, l''Innommable', 'Prononcer le vrai nom d''Hastur, c''est inviter folie, maladie et décrépitude ; de lui, on ne sait guère que le nom de Carcosa. Quand les étoiles s''alignent, il envoie son émissaire, le Roi en jaune, figure masquée en robe jaune dont l''appel passe par une pièce de théâtre ou une chanson grésillant à la radio. Insensible à toute manipulation, il est une terreur pour tous les camps de la Guerre secrète. (VO : Hastur, the King in Yellow)', '["Némésis","Mythe"]', 'Gamemaster Guide', 255, '{"rank":"nemesis","truths":["L''Indicible","Celui qui ne doit pas être nommé","Lié à la lumière stellaire d''Aldébaran"],"attributes":{"agility":9,"brawn":14,"coordination":11,"insight":18,"reason":11,"will":17},"skills":[{"key":"academia","rank":5,"focuses":["Occultisme"]},{"key":"fighting","rank":5,"focuses":["Main nue"]},{"key":"observation","rank":3,"focuses":[]},{"key":"persuasion","rank":3,"focuses":[]},{"key":"resilience","rank":3,"focuses":[]}],"stress":22,"injuries":5,"armour":8,"courage":9,"attacks":[{"name":"Tentacule mortel","focus":"Spécial","range":null,"damage":7,"salvo":null,"qualities":"Intense, Piège, Vicieux","escalation":false},{"name":"Présence indicible","focus":"Attaque mentale","range":null,"damage":10,"salvo":null,"qualities":"Perforant 4, Étourdissant","escalation":false}],"abilities":[{"name":"Force extraordinaire 1","text":"Ajoute 1 succès automatique à tous ses tests de Force. Ajoute aussi +1 à ses attaques de mêlée, à son stress maximum et à son Armure (inclus ci-dessus)."},{"name":"Volonté extraordinaire 1","text":"Ajoute 1 succès automatique à tous ses tests de Volonté. Gagne aussi +1 Puissance, +1 aux attaques mentales, +1 Courage et +1 stress maximum (inclus)."},{"name":"Effroyable 4","text":"Hastur inspire une terreur abjecte et indescriptible. Peut faire des attaques mentales, avec +4 et l''effet Perforant 4 (inclus ci-dessus). De plus, la première fois qu''un personnage voit cette créature, il doit aussitôt réussir un test de Volonté + Résilience de difficulté 4 ou subir un stress mental comme s''il était victime de cette attaque mentale."},{"name":"Vol","text":"Se déplace librement dans les zones aériennes au-dessus du champ de bataille. Porter des objets ou des créatures en vol peut demander un test d''Athlétisme + Force."},{"name":"Immunité (froid, maladie, peur, poison, chaleur, vide)","text":"Immunisé contre le stress, les vérités et autres effets causés par : froid, maladie, peur, poison, chaleur, vide."},{"name":"Menaçant","text":"Sa seule présence est de mauvais augure : quand la créature apparaît pour la première fois dans une scène, générez 1 Menace."},{"name":"Vision nocturne","text":"Voit dans l''obscurité : ignore toute hausse de difficulté ou de plage de complication due au manque de lumière, et peut tenter des tests normalement impossibles dans le noir."},{"name":"Taille 4","text":"Subit une blessure après avoir subi 9 stress (après réductions) d''une seule attaque, au lieu de 5. D''autres actions peuvent être plus faciles ou plus difficiles selon sa taille."},{"name":"Inquiétant 6","text":"Quand la créature apparaît pour la première fois dans une scène, elle génère 6 Menace qu''elle seule peut utiliser."},{"name":"Coriace 2","text":"Peut encaisser 2 blessures supplémentaires (incluses ci-dessus). Peut aussi dépenser 3 Menace pour ignorer une blessure."},{"name":"Tentacules ondoyants","text":"À chacun de ses tours, Hastur peut attaquer jusqu''à trois créatures à son contact avec son Tentacule mortel. Chaque attaque coûte une ou plusieurs Menace, et la cible doit réussir un test d''Agilité + Combat de difficulté égale à la Menace dépensée pour l''éviter. Il ne peut pas attaquer normalement avec ses tentacules."},{"name":"Sorts et rituels","text":"Puissance 9. Lance ses sorts avec la Volonté et connaît tous les sorts que le MJ choisit."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Hastur, le Roi en jaune' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Nyarlathotep', 'Messager des Dieux extérieurs (forme humaine)', 'Le Chaos rampant, le Pharaon noir, le Dieu sans visage : messager des Dieux extérieurs, il est peut-être le seul à comprendre les humains qu''il manipule, dieu noir des sorcières, savant énigmatique ou figure offrant le pouvoir au Soleil noir. Ce profil représente son apparence humaine ordinaire ; ses vrais desseins restent impénétrables.', '["Némésis","Mythe"]', 'Gamemaster Guide', 256, '{"rank":"nemesis","truths":["Messager des Dieux extérieurs","Une apparence anodine cache une malveillance sans fond"],"attributes":{"agility":9,"brawn":11,"coordination":10,"insight":18,"reason":14,"will":14},"skills":[{"key":"academia","rank":5,"focuses":["Occultisme"]},{"key":"fighting","rank":2,"focuses":[]},{"key":"medicine","rank":3,"focuses":["Psychiatrie"]},{"key":"observation","rank":3,"focuses":["Instinct"]},{"key":"persuasion","rank":3,"focuses":["Tromperie","Invocation"]},{"key":"resilience","rank":4,"focuses":["Discipline"]},{"key":"stealth","rank":5,"focuses":["Déguisement"]},{"key":"tactics","rank":2,"focuses":["Opérations clandestines"]}],"stress":19,"injuries":3,"armour":2,"courage":9,"attacks":[{"name":"Dague","focus":"Armes de mêlée","range":"contact","damage":4,"salvo":null,"qualities":"Perforant 1 ; Caché","escalation":false},{"name":"Pistolet","focus":"Armes de poing","range":"close","damage":9,"salvo":"Vicieux","qualities":"Combat rapproché, Caché","escalation":false},{"name":"Paroles insidieuses","focus":"Attaque mentale","range":null,"damage":8,"salvo":null,"qualities":"Voir Paroles insidieuses","escalation":false}],"abilities":[{"name":"Paroles insidieuses","text":"Nyarlathotep sait exactement quoi dire pour saper les gens et semer doute et discorde. Il peut faire des attaques mentales avec le profil ci-dessus, en utilisant son focus Tromperie. Quand il fait une attaque mentale, il peut dépenser 1 Menace pour lui ajouter l''un de ces effets : Intense, Persistant 4 ou Piège."},{"name":"Perception extraordinaire 1","text":"Ajoute 1 succès automatique à ses tests de Perception."},{"name":"Raisonnement extraordinaire 1","text":"Ajoute 1 succès automatique à ses tests de Raisonnement."},{"name":"Volonté extraordinaire 1","text":"Ajoute 1 succès automatique à tous ses tests de Volonté. Gagne aussi +1 Puissance, +1 aux attaques mentales, +1 Courage et +1 stress maximum (inclus)."},{"name":"Se repaître de la peur","text":"Chaque fois qu''un personnage à portée moyenne de la créature subit une blessure mentale, générez 2 Menace."},{"name":"Immunité (peur)","text":"Immunisé contre le stress, les vérités et autres effets causés par : peur."},{"name":"Apparence mortelle","text":"Sous cette forme humaine, dangereuse mais pas plus résistante qu''un humain, Nyarlathotep n''est pas invulnérable. Vaincu, il s''effondre, pris de convulsions, puis éclate pour révéler une forme bien plus vaste et monstrueuse, l''une de ses centaines d''autres formes. Les témoins doivent réussir un test de Volonté + Résilience de difficulté 3 ou subir 11 dés de dégâts mentaux avec Vidange, Perforant 3 et Étourdissant. La forme monstrueuse ne garde ni le stress ni les blessures de la forme humaine, et s''envole d''ordinaire aussitôt vers l''espace."},{"name":"Invocateur","text":"Nyarlathotep peut toujours invoquer ses Serviteurs ou ses Suzerains. Un Serviteur coûte 1 Menace, ou une Menace égale à la moitié de leur nombre pour un groupe ; un Suzerain coûte 2 Menace."},{"name":"Inquiétant 6","text":"Quand la créature apparaît pour la première fois dans une scène, elle génère 6 Menace qu''elle seule peut utiliser."},{"name":"Sorts et rituels","text":"Puissance 8. Lance ses sorts avec la Volonté et connaît tous les sorts et rituels que le MJ souhaite, mais préfère éviter d''user ouvertement de capacités surnaturelles sous forme humaine."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Nyarlathotep' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Formes monstrueuses de Nyarlathotep', 'Messager des Dieux extérieurs (forme monstrueuse)', 'L''une des mille formes monstrueuses du Chaos rampant, celle qu''il révèle quand sa forme humaine est vaincue. Porteur de folie aux mille visages, il ne garde rien des blessures de son apparence mortelle. (VO : Nyarlathotep''s Monstrous Forms)', '["Némésis","Mythe"]', 'Gamemaster Guide', 258, '{"rank":"nemesis","truths":["Messager des Dieux extérieurs","Porteur de folie aux mille visages"],"attributes":{"agility":9,"brawn":11,"coordination":10,"insight":18,"reason":14,"will":14},"skills":[{"key":"academia","rank":5,"focuses":["Occultisme"]},{"key":"fighting","rank":3,"focuses":["Main nue"]},{"key":"medicine","rank":3,"focuses":["Psychiatrie"]},{"key":"observation","rank":3,"focuses":["Instinct"]},{"key":"persuasion","rank":3,"focuses":["Intimidation","Invocation"]},{"key":"resilience","rank":4,"focuses":["Discipline"]},{"key":"stealth","rank":5,"focuses":["Déguisement"]},{"key":"tactics","rank":2,"focuses":["Opérations clandestines"]}],"stress":21,"injuries":5,"armour":6,"courage":9,"attacks":[{"name":"Griffes mortelles","focus":"Main nue","range":"contact","damage":7,"salvo":null,"qualities":"Perforant 2","escalation":false},{"name":"Forme démentielle","focus":"Attaque mentale","range":null,"damage":11,"salvo":null,"qualities":"Vidange, Perforant 3","escalation":false}],"abilities":[{"name":"Brutal 1","text":"Fait et défend ses attaques de mêlée avec la Force au lieu de l''Agilité. Ajoute +1 à ses attaques de mêlée (inclus ci-dessus)."},{"name":"Force extraordinaire 2","text":"Ajoute 2 succès automatiques à tous ses tests de Force. Ajoute aussi +2 à ses attaques de mêlée, à son stress maximum et à son Armure (inclus ci-dessus)."},{"name":"Perception extraordinaire 1","text":"Ajoute 1 succès automatique à ses tests de Perception."},{"name":"Raisonnement extraordinaire 1","text":"Ajoute 1 succès automatique à ses tests de Raisonnement."},{"name":"Volonté extraordinaire 1","text":"Ajoute 1 succès automatique à tous ses tests de Volonté. Gagne aussi +1 Puissance, +1 aux attaques mentales, +1 Courage et +1 stress maximum (inclus)."},{"name":"Se repaître de la peur","text":"Chaque fois qu''un personnage à portée moyenne de la créature subit une blessure mentale, générez 2 Menace."},{"name":"Effroyable 3","text":"Nyarlathotep inspire la terreur. Peut faire des attaques mentales, avec +3 et l''effet Perforant 3 (inclus ci-dessus). De plus, la première fois qu''un personnage voit cette créature, il doit aussitôt réussir un test de Volonté + Résilience de difficulté 3 ou subir un stress mental comme s''il était victime de cette attaque mentale."},{"name":"Vol","text":"Se déplace librement dans les zones aériennes au-dessus du champ de bataille. Porter des objets ou des créatures en vol peut demander un test d''Athlétisme + Force."},{"name":"Immunité (froid, peur, poison, maladie, chaleur, vide)","text":"Immunisé contre le stress, les vérités et autres effets causés par : froid, peur, poison, maladie, chaleur, vide."},{"name":"Taille 4","text":"Subit une blessure après avoir subi 9 stress (après réductions) d''une seule attaque, au lieu de 5. D''autres actions peuvent être plus faciles ou plus difficiles selon sa taille."},{"name":"Invocateur","text":"Nyarlathotep peut toujours invoquer ses Serviteurs ou ses Suzerains. Un Serviteur coûte 1 Menace, ou une Menace égale à la moitié de leur nombre pour un groupe ; un Suzerain coûte 2 Menace."},{"name":"Inquiétant 6","text":"Quand la créature apparaît pour la première fois dans une scène, elle génère 6 Menace qu''elle seule peut utiliser."},{"name":"Coriace 2","text":"Peut encaisser 2 blessures supplémentaires (incluses ci-dessus). Peut aussi dépenser 3 Menace pour ignorer une blessure."},{"name":"Sorts et rituels","text":"Puissance 8. Lance ses sorts avec la Volonté et connaît tous les sorts et rituels que le MJ souhaite."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Formes monstrueuses de Nyarlathotep' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Sarthothus, le dieu brisé', 'Entité extradimensionnelle', 'Être d''une puissance invraisemblable aux géométries impossibles, Sarthothus a été vaincu jadis par Nyarlathotep et son esprit éclaté en fragments dispersés sur Terre et dans d''autres dimensions. Ces fragments sont devenus le Blauer Kristall, les cristaux bleus prisés des Atlantes et aujourd''hui des Nachtwölfe, qui ignorent l''intelligence inhumaine qui y œuvre à réunir l''esprit du dieu. (VO : Sarthothus: The Sundered God)', '["Némésis","Mythe"]', 'Gamemaster Guide', 259, '{"rank":"nemesis","truths":["Le dieu brisé","Formes et géométries impossibles","Conscience éparpillée","Entité extradimensionnelle"],"attributes":{"agility":10,"brawn":null,"coordination":10,"insight":20,"reason":20,"will":20},"skills":[{"key":"academia","rank":5,"focuses":["Occultisme"]},{"key":"fighting","rank":3,"focuses":["Main nue"]},{"key":"observation","rank":4,"focuses":["Instinct"]},{"key":"resilience","rank":5,"focuses":["Discipline"]}],"stress":27,"injuries":3,"armour":0,"courage":13,"attacks":[{"name":"Étreinte fractale","focus":"Main nue","range":"contact","damage":"Voir Étreinte fractale","salvo":null,"qualities":null,"escalation":false},{"name":"Géométries brise-esprit","focus":"Attaque mentale","range":null,"damage":12,"salvo":null,"qualities":"Intense, Persistant 6, Perforant 5","escalation":false}],"abilities":[{"name":"Impossible à ne pas voir","text":"Les attaques mentales de Sarthothus n''affectent pas les créatures qui ne peuvent pas le voir."},{"name":"Structure en expansion","text":"Sarthothus apparaît à la Taille 0. Lancez 1 dé de combat au début de chacun de ses tours ; sur un effet, il gagne +1 Taille. Seul un bannissement ou un confinement magique peut l''arrêter. À la Taille 5, il traite tous les ennemis à portée courte comme à son contact ; la suite est laissée au MJ. Il ne subit une blessure qu''après 5+X stress (après réductions) d''une seule attaque."},{"name":"Perception extraordinaire 2","text":"Ajoute 2 succès automatiques à ses tests de Perception."},{"name":"Raisonnement extraordinaire 2","text":"Ajoute 2 succès automatiques à ses tests de Raisonnement."},{"name":"Volonté extraordinaire 2","text":"Ajoute 2 succès automatiques à tous ses tests de Volonté. Gagne aussi +2 aux attaques mentales, +2 Courage et +2 stress maximum (inclus)."},{"name":"Effroyable 5","text":"Sarthothus défie l''entendement. Peut faire des attaques mentales, avec +5 et l''effet Perforant 5 (inclus ci-dessus). De plus, la première fois qu''un personnage voit cette créature, il doit aussitôt réussir un test de Volonté + Résilience de difficulté 5 ou subir un stress mental comme s''il était victime de cette attaque mentale."},{"name":"Étreinte fractale","text":"Tout ce qui touche Sarthothus est emporté dans un royaume impossible ou piégé dans ses géométries infinies. Aucune attaque physique ne peut le blesser (l''arme, l''énergie ou le projectile disparaît), sauf peut-être la magie ou les armes à la qualité Fléau, à la discrétion du MJ. Une créature qui le touche (attaque à mains nues, arme naturelle, ou frappée par son Étreinte fractale) disparaît dans ce vide. Un personnage peut dépenser 1 point de Fortune pour en revenir indemne, dans la zone qu''il a quittée, 3 rounds plus tard ; il n''en garde aucun souvenir cohérent et subit l''attaque mentale de Sarthothus."},{"name":"Immunité (froid, maladie, peur, douleur, poison, chaleur, vide)","text":"Immunisé contre le stress, les vérités et autres effets causés par : froid, maladie, peur, douleur, poison, chaleur, vide."},{"name":"Menaçant","text":"Sa seule présence est de mauvais augure : quand la créature apparaît pour la première fois dans une scène, générez 1 Menace."},{"name":"Inquiétant 5","text":"Quand la créature apparaît pour la première fois dans une scène, elle génère 5 Menace qu''elle seule peut utiliser."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Sarthothus, le dieu brisé' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Shub-Niggurath', 'Chèvre noire des bois, Dieu extérieur', 'Une fécondité perverse marque sa présence : partout où elle est invoquée, le monde grouille d''une vie impure qui cherche à s''engendrer sous des formes blasphématoires. La Chèvre noire des bois est une déchirure suppurante dans la réalité, un portail par lequel le monde est refait pour les êtres qui veulent y revenir.', '["Némésis","Mythe"]', 'Gamemaster Guide', 260, '{"rank":"nemesis","truths":["Mère féconde d''une vie horrible","Bouches innombrables","Membres innombrables","Toujours affamée"],"attributes":{"agility":4,"brawn":20,"coordination":10,"insight":18,"reason":9,"will":17},"skills":[{"key":"fighting","rank":4,"focuses":["Main nue"]},{"key":"observation","rank":3,"focuses":[]},{"key":"resilience","rank":5,"focuses":["Endurance","Discipline"]},{"key":"survival","rank":4,"focuses":[]}],"stress":27,"injuries":5,"armour":13,"courage":11,"attacks":[{"name":"Piétinement","focus":"Main nue","range":"contact","damage":11,"salvo":null,"qualities":"Zone, Étourdissant","escalation":false},{"name":"Présence horrifique","focus":"Attaque mentale","range":null,"damage":10,"salvo":null,"qualities":"Perforant 3, Étourdissant","escalation":false}],"abilities":[{"name":"Brutal 2","text":"Fait et défend ses attaques de mêlée avec la Force au lieu de l''Agilité. Ajoute +2 à ses attaques de mêlée (inclus ci-dessus)."},{"name":"Force extraordinaire 2","text":"Ajoute 2 succès automatiques à tous ses tests de Force. Ajoute aussi +2 à ses attaques de mêlée, à son stress maximum et à son Armure (inclus ci-dessus)."},{"name":"Récupération rapide 5","text":"Retire 5 stress à la fin de chacun de ses tours. Si elle a des blessures au début de son tour, elle peut dépenser 2 Menace pour en retirer une complètement. Cesse de fonctionner quand la créature est vaincue."},{"name":"Effroyable 3","text":"Shub-Niggurath inspire la terreur. Peut faire des attaques mentales, avec +3 et l''effet Perforant 3 (inclus ci-dessus). De plus, la première fois qu''un personnage voit cette créature, il doit aussitôt réussir un test de Volonté + Résilience de difficulté 3 ou subir un stress mental comme s''il était victime de cette attaque mentale."},{"name":"Tentacules agrippants","text":"À chacun de ses tours, elle peut tenter de piéger toutes les créatures à son contact en dépensant une ou plusieurs Menace par créature. Chacune doit réussir un test d''Agilité + Athlétisme de difficulté égale à la Menace dépensée pour elle (réduite de 1 par point de Taille de la créature). Une créature piégée ne peut tenter de se libérer qu''à son tour, comme pour l''effet Piège. Les créatures piégées au début du tour de Shub-Niggurath sont traînées vers le centre de sa masse et dévorées par ses bouches : elles subissent 6 dés de dégâts physiques avec Vidange et Intense, au début de chacun de ses tours tant qu''elles restent piégées."},{"name":"Immunité (froid, peur, poison, maladie, vide)","text":"Immunisé contre le stress, les vérités et autres effets causés par : froid, peur, poison, maladie, vide."},{"name":"Incorporel 6","text":"Trou dans la réalité plutôt que créature corporelle : 6 Armure (incluse ci-dessus), déplacement libre en terrain difficile ; pour 1 Menace, elle franchit une barrière solide (mur, porte). Elle perd cette Armure contre toute attaque ou danger magique, le feu, l''électricité ou toute autre énergie dirigée."},{"name":"Invulnérable","text":"Ne peut subir de blessure d''aucune attaque physique, hormis la magie, le feu, l''électricité ou toute autre énergie dirigée. Vaincue, elle est seulement bannie."},{"name":"Menaçant","text":"Sa seule présence est de mauvais augure : quand la créature apparaît pour la première fois dans une scène, générez 1 Menace."},{"name":"Vision nocturne","text":"Voit dans l''obscurité : ignore toute hausse de difficulté ou de plage de complication due au manque de lumière, et peut tenter des tests normalement impossibles dans le noir."},{"name":"Taille 6","text":"Subit une blessure après avoir subi 11 stress (après réductions) d''une seule attaque, au lieu de 5. D''autres actions peuvent être plus faciles ou plus difficiles selon sa taille."},{"name":"Inquiétant 6","text":"Quand la créature apparaît pour la première fois dans une scène, elle génère 6 Menace qu''elle seule peut utiliser."},{"name":"Coriace 2","text":"Peut encaisser 2 blessures supplémentaires (incluses ci-dessus). Peut aussi dépenser 3 Menace pour ignorer une blessure."},{"name":"Sorts et rituels","text":"Puissance 8. Lance ses sorts avec la Volonté et connaît tous les sorts que le MJ choisit."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Shub-Niggurath' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Wendigo', 'Dieu du vent des étendues sauvages', 'L''immensité sauvage a un esprit : un dieu porté par le vent, violent et sanglant, qui arrache à ses élus leur civilisation jusqu''à en faire des bêtes féroces. Ses apparitions sont brèves et violentes ; le Soleil noir et les Nachtwölfe ont tenté de le corrompre et de l''asservir, mais le sauvage ne se dompte pas.', '["Némésis","Mythe"]', 'Gamemaster Guide', 262, '{"rank":"nemesis","truths":["Marcheur du vent","Hurlement du vent du nord"],"attributes":{"agility":18,"brawn":18,"coordination":11,"insight":13,"reason":9,"will":18},"skills":[{"key":"athletics","rank":4,"focuses":[]},{"key":"fighting","rank":5,"focuses":["Main nue"]},{"key":"observation","rank":4,"focuses":[]},{"key":"resilience","rank":3,"focuses":[]},{"key":"survival","rank":4,"focuses":["Pistage"]}],"stress":23,"injuries":5,"armour":10,"courage":8,"attacks":[{"name":"Griffes puissantes","focus":"Main nue","range":"contact","damage":9,"salvo":null,"qualities":"Perforant 2, Piège","escalation":false},{"name":"Hurlement du vent du nord","focus":"Attaque mentale","range":null,"damage":10,"salvo":null,"qualities":"Vidange, Perforant 3","escalation":false}],"abilities":[{"name":"Rapidité mortelle","text":"Terriblement rapide, le Wendigo ajoute +1 à la difficulté de toutes les attaques à distance contre lui. Si une attaque à distance le rate, il peut aussitôt dépenser 1 Menace pour faire une action mineure de déplacement."},{"name":"Agilité extraordinaire 1","text":"Ajoute 1 succès automatique à tous ses tests d''Agilité."},{"name":"Force extraordinaire 2","text":"Ajoute 2 succès automatiques à tous ses tests de Force. Ajoute aussi +2 à ses attaques de mêlée, à son stress maximum et à son Armure (inclus ci-dessus)."},{"name":"Effroyable 3","text":"Le Wendigo inspire la terreur. Peut faire des attaques mentales, avec +3 et l''effet Perforant 3 (inclus ci-dessus). De plus, la première fois qu''un personnage voit cette créature, il doit aussitôt réussir un test de Volonté + Résilience de difficulté 3 ou subir un stress mental comme s''il était victime de cette attaque mentale."},{"name":"Vol","text":"Se déplace librement dans les zones aériennes au-dessus du champ de bataille. Porter des objets ou des créatures en vol peut demander un test d''Athlétisme + Force."},{"name":"Bourrasque","text":"Par une action, le Wendigo dépense une ou plusieurs Menace et vise une zone à portée moyenne. Les créatures de cette zone doivent réussir un test de Force + Athlétisme de difficulté égale à la Menace dépensée, ou être renversées et subir 6 stress physique avec Étourdissant et Perforant 2, projetées en l''air puis retombant. Les petits objets volent, et les véhicules de la zone sont renversés si la Menace dépensée dépasse le double de leur Taille ; leurs passagers subissent des dégâts comme si le véhicule était vaincu."},{"name":"Immunité (froid, peur, poison, maladie)","text":"Immunisé contre le stress, les vérités et autres effets causés par : froid, peur, poison, maladie."},{"name":"Menaçant","text":"Sa seule présence est de mauvais augure : quand la créature apparaît pour la première fois dans une scène, générez 1 Menace."},{"name":"Vision nocturne","text":"Voit dans l''obscurité : ignore toute hausse de difficulté ou de plage de complication due au manque de lumière, et peut tenter des tests normalement impossibles dans le noir."},{"name":"Taille 5","text":"Subit une blessure après avoir subi 10 stress (après réductions) d''une seule attaque, au lieu de 5. D''autres actions peuvent être plus faciles ou plus difficiles selon sa taille."},{"name":"Inquiétant 6","text":"Quand la créature apparaît pour la première fois dans une scène, elle génère 6 Menace qu''elle seule peut utiliser."},{"name":"Coriace 2","text":"Peut encaisser 2 blessures supplémentaires (incluses ci-dessus). Peut aussi dépenser 3 Menace pour ignorer une blessure."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Wendigo' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Yig', 'Père des serpents', 'Le grand dieu Yig, serpent antique, père des serpents, dont toutes les créatures rampantes tirent leur essence. Changeant sans cesse de peau et de forme, il se glisse inaperçu dans le monde, sous forme humaine comme ses enfants ophidiens, ou par les tunnels qu''il creuse dans les ténèbres souterraines.', '["Némésis","Mythe"]', 'Gamemaster Guide', 262, '{"rank":"nemesis","truths":["Père des serpents","Maudit et venimeux"],"attributes":{"agility":12,"brawn":17,"coordination":9,"insight":18,"reason":10,"will":17},"skills":[{"key":"academia","rank":3,"focuses":["Occultisme"]},{"key":"athletics","rank":4,"focuses":["Escalade"]},{"key":"fighting","rank":5,"focuses":["Main nue"]},{"key":"medicine","rank":3,"focuses":["Toxicologie"]},{"key":"observation","rank":3,"focuses":["Instinct","Odorat et goût"]},{"key":"resilience","rank":4,"focuses":["Endurance"]},{"key":"survival","rank":4,"focuses":[]}],"stress":27,"injuries":4,"armour":9,"courage":9,"attacks":[{"name":"Étreinte","focus":"Main nue","range":"contact","damage":8,"salvo":null,"qualities":"Piège","escalation":false},{"name":"Morsure venimeuse","focus":"Main nue","range":"contact","damage":8,"salvo":null,"qualities":"Persistant 6, Perforant 1 (voir Morsure venimeuse)","escalation":false},{"name":"Répulsion serpentine","focus":"Attaque mentale","range":null,"damage":6,"salvo":null,"qualities":"Perforant 1","escalation":false}],"abilities":[{"name":"Force extraordinaire 1","text":"Ajoute 1 succès automatique à tous ses tests de Force. Ajoute aussi +1 à ses attaques de mêlée, à son stress maximum et à son Armure (inclus ci-dessus)."},{"name":"Effroyable 1","text":"Yig inspire la peur. Peut faire des attaques mentales, avec +1 et l''effet Perforant 1 (inclus ci-dessus). De plus, la première fois qu''un personnage voit cette créature, il doit aussitôt réussir un test de Volonté + Résilience de difficulté 1 ou subir un stress mental comme s''il était victime de cette attaque mentale."},{"name":"Immunité (peur, poison, maladie)","text":"Immunisé contre le stress, les vérités et autres effets causés par : peur, poison, maladie."},{"name":"Menaçant","text":"Sa seule présence est de mauvais augure : quand la créature apparaît pour la première fois dans une scène, générez 1 Menace."},{"name":"Sens aiguisés (odorat et goût)","text":"Réduit de 2 la difficulté de tous les tests liés à l''odorat ou au goût (minimum 0). Il perçoit par l''odorat des choses que les humains ne peuvent pas sentir."},{"name":"Taille 1","text":"Subit une blessure après avoir subi 6 stress (après réductions) d''une seule attaque, au lieu de 5. D''autres actions peuvent être plus faciles ou plus difficiles selon sa taille."},{"name":"Inquiétant 3","text":"Quand la créature apparaît pour la première fois dans une scène, elle génère 3 Menace qu''elle seule peut utiliser."},{"name":"Coriace 1","text":"Peut encaisser 1 blessure supplémentaire (incluse ci-dessus). Peut aussi dépenser 3 Menace pour ignorer une blessure."},{"name":"Sang toxique","text":"Chaque fois qu''une créature à son contact inflige une ou plusieurs blessures physiques à Yig, elle subit aussitôt 6 stress physique avec l''effet Persistant 4, éclaboussée par son sang très corrosif, sauf si elle réussit un test d''Agilité + Athlétisme de difficulté 2."},{"name":"Morsure venimeuse","text":"Les attaques de Morsure venimeuse de Yig ont +2 en difficulté, sauf si la cible est piégée par son Étreinte. Toute créature affectée par l''effet Persistant de la morsure reçoit aussitôt la vérité Empoisonné. Tant qu''elle dure, elle subit les dégâts persistants à chaque tour, avec en plus les effets Intense et Perforant 2. Retirer cette vérité demande des soins (Perception + Médecine, difficulté 4) ou un traitement équivalent."},{"name":"Sorts et rituels","text":"Puissance 8. Lance ses sorts avec la Volonté et connaît tous les sorts que le MJ choisit."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Yig' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');

INSERT INTO npcs (prenom, nom, role, description, tags, source, page, system_data)
SELECT NULL, 'Yog-Sothoth', 'La Porte et la Clé, Dieu extérieur', 'La Voie, la Porte et la Clé : Yog-Sothoth maintient le temps et l''espace et permet d''en briser les lois, présent à la fois en tous lieux et en tous univers. Une part de son être a été emprisonnée dans le soleil noir par les Hyperboréens, et le Soleil noir de Reinhard Weissler cherche à la libérer ; il se manifeste pourtant par des bulles, des anneaux lumineux ou un vide d''ébène, et implante son savoir impie dans l''esprit de ceux qui l''appellent.', '["Némésis","Mythe"]', 'Gamemaster Guide', 263, '{"rank":"nemesis","truths":["La Voie, la Porte et la Clé","Existe en tous temps, lieux et dimensions, et au-delà"],"attributes":{"agility":14,"brawn":null,"coordination":14,"insight":15,"reason":15,"will":18},"skills":[{"key":"fighting","rank":4,"focuses":["Exotique"]},{"key":"observation","rank":5,"focuses":["Perception"]},{"key":"resilience","rank":5,"focuses":["Discipline"]}],"stress":23,"injuries":5,"armour":10,"courage":11,"attacks":[{"name":"Sphères","focus":"Exotique","range":null,"damage":6,"salvo":null,"qualities":"Vidange, Intense ; Débilitant","escalation":false},{"name":"Trait d''argent","focus":"Exotique","range":"long","damage":8,"salvo":null,"qualities":"Zone, Vicieux","escalation":false},{"name":"Forme impossible","focus":"Attaque mentale","range":null,"damage":8,"salvo":null,"qualities":"Perforant 3, Étourdissant","escalation":false}],"abilities":[{"name":"Effroyable 3","text":"Yog-Sothoth inspire la terreur. Peut faire des attaques mentales, avec +3 et l''effet Perforant 3 (inclus ci-dessus). De plus, la première fois qu''un personnage voit cette créature, il doit aussitôt réussir un test de Volonté + Résilience de difficulté 1 ou subir un stress mental comme s''il était victime de cette attaque mentale."},{"name":"Vol","text":"Yog-Sothoth vole, et même à vitesse supersonique : il peut atteindre n''importe quelle zone dans ou au-dessus d''un environnement par une action mineure."},{"name":"Immunité (froid, peur, poison, douleur, maladie, vide)","text":"Immunisé contre le stress, les vérités et autres effets causés par : froid, peur, poison, douleur, maladie, vide."},{"name":"Incorporel 10","text":"Présent partout et en tout temps, il se manifeste de façon impossible et intangible : 10 Armure (incluse ci-dessus), déplacement libre en terrain difficile ; pour 1 Menace, il franchit une barrière solide (mur, porte). Il perd cette Armure contre toute attaque ou danger magique."},{"name":"Invulnérable","text":"Ne peut subir de blessure d''aucune attaque physique ou mentale, hormis les attaques magiques ou les armes à la qualité Fléau. Si une attaque contre laquelle il est immunisé devait lui infliger une blessure, 2 points sont aussitôt ajoutés à la Menace. Vaincu, il est seulement banni."},{"name":"Menaçant","text":"Sa seule présence est de mauvais augure : quand la créature apparaît pour la première fois dans une scène, générez 1 Menace."},{"name":"Vision nocturne","text":"Voit dans l''obscurité : ignore toute hausse de difficulté ou de plage de complication due au manque de lumière, et peut tenter des tests normalement impossibles dans le noir."},{"name":"Taille","text":"Yog-Sothoth a la taille qu''il veut et peut en changer une fois par tour ; le MJ détermine les effets des très grandes tailles (zones occupées, contact, portée courte). Pour les dégâts, il est toujours traité comme de Taille 10 : il subit une blessure après 15 stress (après réductions) d''une seule attaque."},{"name":"Inquiétant 15","text":"Quand la créature apparaît pour la première fois dans une scène, elle génère 15 Menace qu''elle seule peut utiliser."},{"name":"Translocation","text":"À chaque round, Yog-Sothoth peut choisir un personnage à son contact et le transporter instantanément en tout point de l''espace ou du temps. Un personnage réticent peut tenter un test de Volonté + Résilience de difficulté 4 pour rester où et quand il est."},{"name":"Coriace 2","text":"Peut encaisser 2 blessures supplémentaires (incluses ci-dessus). Peut aussi dépenser 3 Menace pour ignorer une blessure."},{"name":"Sorts et rituels","text":"Puissance 8. Lance ses sorts avec la Volonté et connaît tous les sorts que le MJ choisit. Il peut toujours utiliser Observation pour lancer un sort, quelle que soit la compétence normalement requise."}],"threatSpends":[]}'
WHERE NOT EXISTS (SELECT 1 FROM npcs WHERE nom = 'Yog-Sothoth' AND COALESCE(prenom, '') = '' AND COALESCE(source, '') = 'Gamemaster Guide');
